function normalizeShortDramaGenre(value = "", sourceText = "") {
  let raw = text(value)
    .replace(/^(?:内容类型|小说类型|短剧类型|genre)[：:]?\s*/i, "")
    .replace(/[\r\n]+/g, " ")
    .replace(/[|｜/\\]+/g, "，")
    .replace(/(?:标签|类型)\s*[：:]?/g, "")
    .replace(/[“”\"'‘’【】\[\]]/g, "")
    .trim();
  const pieces = raw.split(/[，,；;]+/).map((item) => text(item)).filter(Boolean);
  raw = pieces.slice(0, 3).join("").replace(/短剧/g, "");
  // 这里只做格式校正，不用本地词库替 AI 判断题材；AI 空结果统一回退为中性占位。
  if (!raw) raw = "剧情";
  raw = raw.replace(/短剧.*$/, "短剧").replace(/剧短剧$/, "短剧");
  if (!/短剧$/.test(raw)) raw += "短剧";
  return raw.slice(0, 40);
}

function enrichGenreWithMarketTags(base = "", sourceText = "") {
  return normalizeShortDramaGenre(base, sourceText);
}

