function v7827GlobalizeStyleAuthority(fields = []) {
  const out = Array.isArray(fields) ? [...fields] : [];
  if (out.length < 11) return out;
  // 统一风格只定义全片美学基线；具体焦段/现场光源/逐镜构图属于每镜导演层。
  out[4] = "自然叙事镜头体系与克制透视及稳定空间关系";
  out[8] = "动机光优先并保留柔和高光与可读暗部及自然明暗层次";
  out[9] = "强调人物关系与空间纵深及视线组织的电影级叙事构图";
  return out;
}

function normalizeTrailerStyleTemplate(value = "", sourceText = "", genre = "") {
  const blocked = /(?:4\s*K|8\s*K|超高清|高清画质|分辨率|水印|Logo|字幕|对白字幕|标题字|说明文字|画面限制|画质约束)/i;
  const source = text(value)
    .replace(/^(?:统一风格附加视觉信息|统一风格|视觉风格)[：:]?\s*/i, "")
    .replace(/[\r\n]+/g, "，")
    .split(/[，,；;、]+/)
    .map((item) => text(item))
    .filter(Boolean)
    .filter((item) => !blocked.test(item));
  const fallback = visualStyleFallbackProfile(sourceText, genre);
  const find = (patterns, index, reject = null) => source.find((item) => patterns.some((pattern) => pattern.test(item)) && !(reject && reject.test(item))) || fallback[index];
  const fields = [
    find([/电影质感|电视剧质感|短剧质感|老电影质感/], 0),
    find([/胶片实拍|数字.*实拍|实拍质感|电影实拍/], 1),
    find([/胶片颗粒|颗粒感/], 2),
    find([/滤镜|色调/], 3),
    find([/镜头|焦段|柔焦|光晕/], 4, /噪点|畸变/),
    find([/噪点|畸变|镜头呼吸/], 5),
    find([/对比度|反差/], 6),
    find([/饱和度/], 7),
    find([/明暗|阴影|光线|顶光|侧光|轮廓光|实景光|窗光|灯光/], 8, /滤镜|镜头|光晕/),
    find([/叙事构图|构图/], 9),
    find([/氛围感|氛围/], 10),
  ];
  // 字段模板化自动校正：固定十一项、固定顺序、缺项按当前题材补齐。
  const normalized = fields.map((item, index) => text(item) || fallback[index]).slice(0, 11);
  return v7827GlobalizeStyleAuthority(normalized).join("，").slice(0, 1800);
}

