function countRegexHits(raw = "", patterns = []) {
  return (patterns || []).reduce((total, pattern) => {
    const flags = pattern.flags.includes("g") ? pattern.flags : `${pattern.flags}g`;
    return total + Math.min(5, raw.match(new RegExp(pattern.source, flags))?.length || 0);
  }, 0);
}

function detectProfessionalVisualProfiles(source = "", limit = 2) {
  const raw = normalizeSkillSource(source);
  const scored = PROFESSIONAL_CINEMATIC_PROFILES.map((profile) => {
    const hits = countRegexHits(raw, profile.patterns);
    return { ...profile, hits, score: profile.priority + hits * 8 };
  }).filter((item) => item.hits > 0);
  if (!scored.length) return [{ ...PROFESSIONAL_CINEMATIC_PROFILES[0], hits: 0, score: 0 }];
  return scored.sort((a, b) => b.score - a.score || b.hits - a.hits).slice(0, Math.max(1, limit));
}

function detectCinematicStyleModifiers(source = "", limit = 2) {
  const raw = normalizeSkillSource(source);
  return CINEMATIC_STYLE_MODIFIERS
    .map((item) => ({ ...item, hits: countRegexHits(raw, item.patterns) }))
    .filter((item) => item.hits > 0)
    .sort((a, b) => b.hits - a.hits)
    .slice(0, Math.max(0, limit));
}

function buildProfessionalVisualStyleSkill(sourceText = "", maxLength = 1600) {
  const profiles = detectProfessionalVisualProfiles(sourceText, 2);
  const primary = profiles[0] || PROFESSIONAL_CINEMATIC_PROFILES[0];
  const secondary = profiles[1];
  const modifiers = detectCinematicStyleModifiers(sourceText, 2);
  const lines = [
    "【专业风格画质自动路由｜必须落实到统一风格附加视觉信息】",
    `主风格：${primary.name}。${primary.style}。`,
    "镜头美学基线：统一风格只提供透视、空间连续性和整体镜头性格；具体焦段由每镜叙事任务、Scene Memory与人物调度决定，不得机械复用统一风格中的焦段。",
    `运镜基线：${primary.movement}。`,
    secondary ? `辅题材兼容：${secondary.name}只吸收与原文场景直接相关的色彩/材质，不得覆盖主风格或造成滤镜冲突。` : "",
    modifiers.length ? `场景修饰：${modifiers.map((item) => `${item.name}=${item.rule}`).join("；")}。` : "",
    "统一底线：高动态范围、柔和高光滚降、暗部可辨、自然肤色、真实纹理、主光有动机；禁止青绿病态、死黑、灰脏、无理由阴冷、过饱和橙青、廉价美颜和每镜随机换滤镜。",
  ];
  return fitCompleteSkillLines(lines, Math.max(700, maxLength));
}

function detectCameraMovementSkills(source = "", limit = 3) {
  const raw = normalizeSkillSource(source);
  const scored = CAMERA_MOVEMENT_ROUTE_SKILLS.map((skill) => {
    const hits = countRegexHits(raw, skill.patterns);
    return { ...skill, hits, score: skill.priority + hits * 7 };
  }).filter((item) => item.hits > 0);
  return scored.sort((a, b) => b.score - a.score || b.hits - a.hits).slice(0, Math.max(1, limit));
}

function buildCameraMovementRouting(sourceText = "", scenes = [], maxLength = 1800) {
  const sceneList = Array.isArray(scenes) && scenes.length ? scenes : [];
  const sceneRoutes = [];
  const counts = new Map();
  const pool = new Map();
  sceneList.slice(0, 60).forEach((scene, index) => {
    const sceneSource = `${text(scene?.source_text || scene?.text)} ${text(scene?.guidance)}`;
    const skills = detectCameraMovementSkills(sceneSource, 2);
    skills.forEach((skill) => {
      counts.set(skill.id, (counts.get(skill.id) || 0) + 1);
      if (!pool.has(skill.id)) pool.set(skill.id, skill);
    });
    if (index < 12 && skills.length) sceneRoutes.push(`${index + 1}:${skills.map((item) => item.name).join("+")}`);
  });
  detectCameraMovementSkills(sourceText, 6).forEach((skill) => {
    counts.set(skill.id, (counts.get(skill.id) || 0) + 1);
    if (!pool.has(skill.id)) pool.set(skill.id, skill);
  });
  const selected = [...pool.values()]
    .sort((a, b) => (counts.get(b.id) || 0) - (counts.get(a.id) || 0) || b.score - a.score)
    .slice(0, 8);
  const lines = [
    "【专业运镜自动路由｜每镜必须选择真正服务剧情的运镜】",
    `命中运镜Skill：${selected.length ? selected.map((item) => item.name).join("、") : "固定叙事与轻微渐进推镜"}`,
    ...selected.map((item) => `- ${item.name}：${item.rule}。`),
    sceneRoutes.length ? `逐段运镜路由：${sceneRoutes.join("；")}` : "逐段运镜路由：按当前动作选择固定/轻推/跟拍，信息不足时宁可少动。",
    "运镜硬规则：每镜1个主运镜，最多1个辅助；写清起点、方向、速度关系和终点落点；保持180度轴线、人物出入画方向和焦点连续；连续3镜不得复用同一推镜模板。",
  ];
  return {
    prompt: compactTransportPromptText(fitCompleteSkillLines(lines, Math.max(700, maxLength))),
    names: selected.length ? selected.map((item) => item.name) : ["固定叙事与轻推"],
  };
}

function buildStyleContinuitySkill(style = {}, sourceText = "") {
  const confirmed = trailerStyleForAi(style?.trailer_style || "");
  const automatic = buildProfessionalVisualStyleSkill(sourceText, 900);
  return [
    "【统一视觉连续性 Skill｜单条重生成也必须保持】",
    confirmed ? `当前工作区已确认统一视觉：${confirmed}` : automatic,
    "本次统一视觉只作为成像、色彩、颗粒、反差、饱和度、光学质感与全片美学基线；具体焦段、现场光源、构图、运镜由当前镜原文、Scene Memory和导演决策负责。不得把统一风格词重复塞进每个 prompt，也不得借风格新增剧情。",
  ].filter(Boolean).join("\n");
}

function normalizeSkillSource(value = "") {
  return text(value).replace(/\s+/g, " ").slice(0, 50000);
}

function detectAutoVisualSkills(source = "", limit = 6) {
  const raw = normalizeSkillSource(source);
  if (!raw) return [];
  const scored = [];
  AUTO_VISUAL_SKILLS.forEach((skill) => {
    let hits = 0;
    (skill.patterns || []).forEach((pattern) => {
      const flags = pattern.flags.includes("g") ? pattern.flags : `${pattern.flags}g`;
      const matches = raw.match(new RegExp(pattern.source, flags));
      hits += Math.min(4, matches?.length || 0);
    });
    if (!hits) return;
    scored.push({ ...skill, hits, score: skill.priority + hits * 6 });
  });
  return scored.sort((a, b) => b.score - a.score || b.hits - a.hits).slice(0, Math.max(1, limit));
}

function buildAutoVisualSkillLine(skill = {}) {
  return `- ${text(skill.name) || "通用原文还原"}：${text(skill.rule)}；统一执行链=原文事实→视觉载体→主体动作与对象→可见结果。只增强事实的可拍摄表达，不新增剧情事实。`;
}

function fitCompleteSkillLines(lines = [], maxLength = 1600) {
  const kept = [];
  let used = 0;
  (Array.isArray(lines) ? lines : []).forEach((line) => {
    const value = text(line);
    if (!value) return;
    const cost = value.length + (kept.length ? 1 : 0);
    if (used + cost > Math.max(360, maxLength)) return;
    kept.push(value);
    used += cost;
  });
  return kept.join("\n");
}


const LOCAL_HELPER_CACHE = new Map();

function readLocalHelperCache(key) {
  const entry = LOCAL_HELPER_CACHE.get(key);
  if (!entry) return null;
  entry.usedAt = Date.now();
  return entry.value;
}

function writeLocalHelperCache(key, value, maxEntries = 18) {
  LOCAL_HELPER_CACHE.set(key, { value, usedAt: Date.now() });
  if (LOCAL_HELPER_CACHE.size <= maxEntries) return value;
  const oldest = [...LOCAL_HELPER_CACHE.entries()].sort((a, b) => (a[1]?.usedAt || 0) - (b[1]?.usedAt || 0))[0];
  if (oldest) LOCAL_HELPER_CACHE.delete(oldest[0]);
  return value;
}

function compactTransportPromptText(value = "") {
  return String(value || "")
    .replace(/\r/g, "")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]{2,}/g, " ")
    .trim();
}

function buildAutoSkillRouting(sourceText = "", scenes = [], maxLength = 1600) {
  const source = normalizeSkillSource(sourceText);
  const sceneList = Array.isArray(scenes) && scenes.length ? scenes : [];
  const cacheKey = `route|${Math.max(360, maxLength)}|${buildCharacterSourceFingerprint(source)}|${sceneList.slice(0, 20).map((scene) => `${text(scene?.source_text || scene?.text)}#${text(scene?.guidance)}#${uniqueTextList(scene?.characters || []).join(",")}`).join("||")}`;
  const cached = readLocalHelperCache(cacheKey);
  if (cached) return cached;
  const skillCounts = new Map();
  const sceneSkillMap = new Map();
  const sceneRoutes = [];
  sceneList.slice(0, 60).forEach((scene, index) => {
    const sceneSource = `${text(scene?.source_text || scene?.text)} ${text(scene?.guidance)}`;
    const skills = detectAutoVisualSkills(sceneSource, 3);
    const lockedCharacters = normalizeSceneCharactersMode(scene?.characters_mode) === "manual" ? uniqueTextList(scene?.characters || []).slice(0, 5) : [];
    skills.forEach((skill) => {
      skillCounts.set(skill.id, (skillCounts.get(skill.id) || 0) + 1);
      if (!sceneSkillMap.has(skill.id)) sceneSkillMap.set(skill.id, skill);
    });
    if (index < 12 && (skills.length || lockedCharacters.length)) {
      const skillPart = skills.length ? skills.map((item) => item.name).join("+") : "通用原文还原";
      const characterPart = lockedCharacters.length ? `，锁定人物=${lockedCharacters.join("+")}` : "";
      sceneRoutes.push(`${index + 1}:${skillPart}${characterPart}`);
    }
  });
  const globalSkills = detectAutoVisualSkills(source, 12);
  globalSkills.forEach((skill) => skillCounts.set(skill.id, (skillCounts.get(skill.id) || 0) + 1));
  const selectedPool = new Map([...sceneSkillMap.entries(), ...globalSkills.map((skill) => [skill.id, skill])]);
  const selected = [...selectedPool.values()]
    .sort((a, b) => (skillCounts.get(b.id) || 0) - (skillCounts.get(a.id) || 0) || b.score - a.score)
    .slice(0, 12);
  const skillNames = selected.map((item) => item.name);
  const skillLines = selected.map((skill) => buildAutoVisualSkillLine(skill));
  const routeLine = sceneRoutes.length ? `逐段路由：${sceneRoutes.slice(0, 12).join("；")}` : "逐段路由：按当前原文执行通用原文还原";
  const prompt = fitCompleteSkillLines([
    "【AI自动Skill路由｜本次必须实际执行】",
    `已调用Skill：${skillNames.length ? skillNames.join("、") : "通用原文还原"}`,
    "执行要求：先按逐段路由选择实际命中的1-3项Skill，再按“事实理解→视觉承载→动作与对象→可见结果→镜头表达”的顺序生成该段；Skill不是参考案例，必须真正参与场景、动作节点和镜头数量判断。不得套固定剧情，不得复制规则原句，不得用本地模板替代AI理解。",
    ...skillLines,
    routeLine,
  ], Math.max(360, maxLength));
  return writeLocalHelperCache(cacheKey, {
    prompt: compactTransportPromptText(prompt),
    names: skillNames.length ? skillNames : ["通用原文还原"],
  });
}

function promptDensityRules() {
  const mode = readPromptDensity();
  const base = PROMPT_DENSITY_RULES[mode] || PROMPT_DENSITY_RULES.strict;
  const logic = text(readFieldValue("#promptExampleLogic", state.promptExampleLogic || "")).slice(0, 1200);
  const exampleText = text(readFieldValue("#promptExampleText", state.promptExampleText || "")).slice(0, 1600);
  if (mode === "example") {
    return `${base}\n案例提炼逻辑：${logic || "尚未提炼，请仅按通用标准细节版生成，不得猜测案例规则。"}`;
  }
  if (mode === "reference") {
    return `${base}\n样例提炼逻辑：${logic || "请优先学习样例的输出格式、场景写法、动作链密度与对白分行方式。"}\n参考样例（仅学习写法，不复制剧情）：${exampleText || "尚未填写参考样例，请退回通用标准细节版逻辑，不得虚构案例。"}`;
  }
  return base;
}


function normalizeDialogueValidationText(value = "") {
  return String(value || "")
    .replace(/^[\s“”"'‘’]+|[\s“”"'‘’]+$/g, "")
    .replace(/[\s，,。！？!?；;：:、“”"'‘’]+/g, "")
    .toLowerCase();
}

function extractQuotedSourceCounts(sourceText = "") {
  const counts = new Map();
  const source = String(sourceText || "");
  const regex = /[“"]([^”"]{1,800})[”"]/g;
  let match;
  while ((match = regex.exec(source))) {
    const key = normalizeDialogueValidationText(match[1]);
    if (!key) continue;
    counts.set(key, (counts.get(key) || 0) + 1);
  }
  return counts;
}


function extractLikelySpokenSourceQuotes(sourceText = "") {
  const source = String(sourceText || "");
  const spoken = new Map();
  const regex = /[“"]([^”"]{1,800})[”"]/g;
  let match;
  while ((match = regex.exec(source))) {
    const quote = text(match[1]);
    const quoteKey = normalizeDialogueValidationText(quote);
    if (!quoteKey) continue;
    const before = source.slice(Math.max(0, match.index - 100), match.index);
    const after = source.slice(match.index + match[0].length, match.index + match[0].length + 60);
    const context = `${before} ${after}`;
    const speechCue = /说|问|喊|道|开口|回答|质问|呵斥|命令|低声|冷声|厉声|声音|传来|听筒|电话|吼|叫|嘟囔|喃喃|笑着说|哭着说|补充道|接着说|回了一句|回应|劝道|解释道|反问/;
    const nonSpeechCue = /游戏|标题|书名|歌名|名为|叫做|屏幕显示|手机显示|纸上写着|表格写着|文件写着|横幅|标语|系统提示|弹幕|聊天记录|群消息|短信|合同|名单|病历|化验单|热搜|搜索页/;
    const lineStart = source.lastIndexOf("\n", match.index - 1) + 1;
    const lineEndCandidate = source.indexOf("\n", match.index + match[0].length);
    const lineEnd = lineEndCandidate < 0 ? source.length : lineEndCandidate;
    const wholeLine = source.slice(lineStart, lineEnd).trim();
    const standaloneDialogue = new RegExp(`^[“"]${quote.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}[”"](?:[。！？!?])?$`).test(wholeLine);
    if ((speechCue.test(context) || standaloneDialogue) && !nonSpeechCue.test(context)) {
      spoken.set(quoteKey, quote);
    }
  }
  return spoken;
}

function parseDialogueValidationLine(line = "") {
  const raw = String(line || "").trim();
  const match = raw.match(/^([^：:]+?)[：:]\s*[“"]([\s\S]*?)[”"]$/);
  if (!match) return null;
  return {
    speaker: text(match[1]).replace(/[（(][^）)]*[）)]/g, "").trim(),
    quote: text(match[2]),
  };
}

function collectGeneratedDialogueAssignments(outlineShots = []) {
  const assignments = [];
  (Array.isArray(outlineShots) ? outlineShots : []).forEach((shot, shotIndex) => {
    const units = Array.isArray(shot?.timeline_segments) && shot.timeline_segments.length
      ? shot.timeline_segments
      : [shot];
    units.forEach((unit, segmentIndex) => {
      const localSeen = new Set();
      const pushAssignment = (speakerRaw, quoteRaw, origin) => {
        const speaker = text(speakerRaw).replace(/[（(][^）)]*[）)]/g, "").trim();
        const quote = text(quoteRaw).replace(/^[“"]|[”"]$/g, "").trim();
        const quoteKey = normalizeDialogueValidationText(quote);
        if (!quoteKey) return;
        const localKey = `${speaker}|${quoteKey}`;
        if (localSeen.has(localKey)) return;
        localSeen.add(localKey);
        assignments.push({ speaker, quote, quoteKey, origin, shotIndex, segmentIndex });
      };
      if (text(unit?.speech_text)) {
        String(unit.speech_text).split(/\n+/).map((item) => text(item)).filter(Boolean)
          .forEach((quote) => pushAssignment(unit.speaker, quote, "speech_text"));
      }
      if (Array.isArray(unit?.dialogue_lines)) {
        unit.dialogue_lines.forEach((line) => {
          const parsed = parseDialogueValidationLine(line);
          if (parsed) pushAssignment(parsed.speaker, parsed.quote, "dialogue_lines");
        });
      }
    });
  });
  return assignments;
}

function validateGeneratedDialogueAttribution(outlineShots = [], sourceText = "") {
  const assignments = collectGeneratedDialogueAssignments(outlineShots);
  const sourceCounts = extractQuotedSourceCounts(sourceText);
  const likelySpoken = extractLikelySpokenSourceQuotes(sourceText);
  const issues = [];
  const byQuote = new Map();
  assignments.forEach((item) => {
    if (!item.speaker) {
      issues.push({ type: "missing_speaker", quote: item.quote, speakers: [] });
    }
    if (/^[A-Z](?:\d+)?$/i.test(item.speaker)) {
      issues.push({ type: "alias_code_speaker", quote: item.quote, speakers: [item.speaker] });
    }
    if (sourceCounts.size && !sourceCounts.has(item.quoteKey)) {
      issues.push({ type: "fabricated_quote", quote: item.quote, speakers: [item.speaker] });
    } else if (!likelySpoken.size) {
      issues.push({ type: "unwanted_dialogue", quote: item.quote, speakers: [item.speaker] });
    } else if (!likelySpoken.has(item.quoteKey)) {
      issues.push({ type: "non_spoken_quote", quote: item.quote, speakers: [item.speaker] });
    }
    if (!byQuote.has(item.quoteKey)) byQuote.set(item.quoteKey, []);
    byQuote.get(item.quoteKey).push(item);
  });
  byQuote.forEach((items, quoteKey) => {
    const speakers = [...new Set(items.map((item) => item.speaker).filter(Boolean))];
    const quote = items[0]?.quote || quoteKey;
    if (speakers.length > 1) {
      issues.push({ type: "conflicting_speakers", quote, speakers });
    }
    const allowedCount = sourceCounts.get(quoteKey) || 1;
    const uniqueOccurrences = new Set(items.map((item) => `${item.shotIndex}:${item.segmentIndex}:${item.speaker}`));
    if (uniqueOccurrences.size > allowedCount) {
      issues.push({ type: "repeated_quote", quote, speakers });
    }
  });
  likelySpoken.forEach((quote, quoteKey) => {
    if (!byQuote.has(quoteKey)) {
      issues.push({ type: "missing_quote", quote, speakers: [] });
    }
  });
  const uniqueIssues = [];
  const seen = new Set();
  issues.forEach((issue) => {
    const key = `${issue.type}|${normalizeDialogueValidationText(issue.quote)}|${(issue.speakers || []).join(",")}`;
    if (!seen.has(key)) {
      seen.add(key);
      uniqueIssues.push(issue);
    }
  });
  return { ok: uniqueIssues.length === 0, issues: uniqueIssues.slice(0, 12), assignments };
}

function dialogueCorrectionInstruction(issues = []) {
  const details = issues.slice(0, 8).map((issue, index) => {
    const speakers = issue.speakers?.length ? `，当前错误说话人：${issue.speakers.join("、")}` : "";
    const label = issue.type === "conflicting_speakers" ? "同一句台词被分配给多个角色"
      : issue.type === "repeated_quote" ? "同一句台词重复出现"
        : issue.type === "missing_speaker" ? "台词缺少说话人"
          : issue.type === "alias_code_speaker" ? "speaker 错填成 A/B/C 代号"
            : issue.type === "unwanted_dialogue" ? "原文无人物口语却生成了对白"
              : issue.type === "non_spoken_quote" ? "把系统/聊天/文件等非口语文字当成对白"
                : issue.type === "missing_quote" ? "明确对白未写入任何镜头"
                  : "生成了原文没有的台词";
    return `${index + 1}. ${label}：“${issue.quote}”${speakers}`;
  }).join("\n");
  return `AI对白归属纠错（必须整批重新生成，不能通过删除重复行蒙混过关）：\n${details}\n重新阅读原文中每句引号前后的叙述语法，在内部建立“台词—唯一说话人”表。speaker 必须使用人物卡真实姓名或已确认别名，禁止填写 A/B/C。每句原文对白只能出现一次并归属一个说话人。台词中被直接点名、称呼或命令的人是受话者，不得因为姓名出现在台词里就判为说话人。若原文写“他的声音从听筒里传来：‘某某，下楼挪车。’”，说话人应是“他/对应角色”，被叫到的“某某”只是受话者。两个人先后说话必须拆成两个连续时段，每个时段只保留一个 speaker 和一段 speech_text。`;
}

async function requestOutlineWithDialogueValidation(endpoint, basePayload, sourceText, _maxAttempts = 1) {
  const protocolDraft = {
    ...basePayload,
    must_cover_details: trimApiConstraintText(basePayload.must_cover_details, API_CONSTRAINT_FIELD_LIMIT),
    shot_rhythm_requirements: trimApiConstraintText(basePayload.shot_rhythm_requirements, API_CONSTRAINT_FIELD_LIMIT),
  };
  const payload = sanitizeApiRequestBody(protocolDraft);
  const started = performance.now();
  const sourceKey = text(payload?.scene?.source_key || basePayload?.scene?.source_key);
  const generatorMeta = {
    source_hash: text(state.outlineSourceHashV77 || state.sourceSnapshotV77?.source_hash || state.characterCoreV2?.source_hash),
    source_revision: Number(state.sourceSnapshotV77?.source_revision || state.characterCoreV2?.source_revision || 0),
    character_revision: Number(state.characterCoreV2?.character_revision || 0),
    source_key: sourceKey,
    source_index: Number(payload?.scene?.source_index || 0),
    expected_sources: [{ source_key: sourceKey, source_index: Number(payload?.scene?.source_index || 1), source_text: sourceText }],
  };
  const nativeService = globalThis.__V78_NATIVE_GENERATOR_SERVICE__;
  let data;
  if (nativeService) {
    data = await nativeService.requestRegeneration({ endpoint, draft: protocolDraft, v77Payload: payload, meta: generatorMeta, executeLegacy: globalThis.__V78_GENERATOR_HOST_BRIDGE__?.executeLegacy });
  } else {
    const generator = globalThis.__V78_OUTLINE_GENERATOR_ADAPTER__;
    const protocolService = globalThis.__V78_GENERATOR_PROTOCOL_SERVICE__;
    const protocolBundle = protocolService ? protocolService.prepareRegeneration({ draft: protocolDraft, v77Payload: payload, meta: generatorMeta }) : null;
    const executeGeneratorRequest = async (candidatePayload) => normalizeApiCharacterReferences(await postJSON(endpoint, candidatePayload));
    data = generator ? await generator.requestRegeneration({ nativePayload: payload, candidatePayload: protocolBundle?.v78_payload || payload, protocolDecision: protocolBundle?.decision || null, meta: generatorMeta, executeV77: executeGeneratorRequest, executeV78: executeGeneratorRequest }) : await executeGeneratorRequest(protocolBundle?.selected_payload || payload);
  }
  data.dialogue_validation_retry_count = 0;
  data.dialogue_validation_issues = [];
  data.visual_quality_issues = [];
  data.regenerate_request_seconds = Math.max(0, Math.round((performance.now() - started) / 100) / 10);
  data.regenerate_payload_chars = JSON.stringify(payload).length;
  data.single_pass_only = true;
  data.single_pass_feedback = "当前分镜本次点击仅请求一次，AI返回内容已直接接收。";
  return data;
}

function togglePromptExamplePanel() {
  const panel = $("#promptExamplePanel");
  if (!panel) return;
  panel.classList.toggle("hidden", !["example", "reference"].includes(readPromptDensity()));
}

async function extractPromptExampleLogic() {
  const example = text(readFieldValue("#promptExampleText"));
  if (!example) return apiError("请先粘贴至少一条画面描述案例。");
  const button = $("#extractExampleLogicBtn");
  const status = $("#promptExampleStatus");
  setButtonBusy(button, true, "AI提炼中");
  if (status) status.textContent = "正在提炼案例中的通用拆镜逻辑…";
  try {
    const style = readStyle();
    const instruction = `这不是小说正文，而是一条或多条优秀的“原文转镜头画面描述”案例。请只提炼成可适配所有小说类型的通用生成逻辑，输出一段简洁规则文字。必须提炼：如何判断场景、如何拆1-4秒时段、画面描述的信息顺序、动作链密度、景别/机位/运镜/转场选择、对白与无对白的区别。严禁复述案例中的具体人物、地点、服装、台词和剧情结果。案例：\n${example}`;
    const data = await postJSON("/api/optimize-style-copy", {
      novel_text: instruction,
      genre: "通用小说原文转画面案例逻辑",
      trailer_style: trailerStyleForAi(style.trailer_style, novelText, style.genre),
      genre_note: "只提炼原文转画面的通用拆镜逻辑，不判断小说题材。",
      trailer_style_note: "输出可直接叠加到画面生成指令中的简洁规则，不输出具体案例内容。",
    });
    const candidate = [text(data.trailer_style), text(data.genre)].sort((a, b) => b.length - a.length)[0];
    if (!candidate) throw new Error("AI 没有返回可用的案例逻辑，请换模型后再试。");
    state.promptExampleLogic = candidate.slice(0, 2400);
    writeFieldValue("#promptExampleLogic", state.promptExampleLogic);
    if (status) status.textContent = "案例逻辑已提炼。选择“案例学习增强版”生成时才会使用，不影响其他模式。";
    clearFinalSegments();
    scheduleDraftSave();
  } catch (error) {
    if (status) status.textContent = error.message;
    apiError(error.message);
  } finally {
    setButtonBusy(button, false);
  }
}

