function temporaryMustRenderV22(state = "") {
  return ["visible", "visual_exposition", "visible_candidate", "screen_or_memory_visible", "background_visible", "addressee_visible"].includes(text(state));
}

function temporaryContinuityGroupV22(sourceScenes = [], lineIndex = 0) {
  let group = 1;
  for (let index = 0; index <= Math.min(lineIndex, sourceScenes.length - 1); index += 1) {
    if (index === 0) continue;
    const source = text(sourceScenes[index]?.source_text || sourceScenes[index]?.text);
    const explicitBreak = /(?:与此同时|另一边|另一处|次日|翌日|第二天|几天后|数日后|多年后|数年后|后来|当晚|第二天早上|回忆里|回忆中|梦中|梦里|幻境中|镜头切到|场景切到|电话另一端|来到|抵达|赶到|走进|进入|回到|返回|离开.*(?:后|之后)|换到|转到)/.test(source);
    if (explicitBreak) group += 1;
  }
  return `temp_scene_${group}`;
}

function temporaryContinuityIdV22(label = "", sceneGroup = "temp_scene_1") {
  const normalized = text(label).replace(/[\s，,。；;：:、（）()【】\[\]]+/g, "").toLowerCase();
  let hash = 2166136261;
  for (const ch of normalized) { hash ^= ch.charCodeAt(0); hash = Math.imul(hash, 16777619); }
  return `${sceneGroup}_${(hash >>> 0).toString(36)}`;
}

function normalizeTemporaryCharacterV22(item = {}, fallback = {}) {
  const label = text(item?.label || item?.source_phrase || fallback?.label).slice(0, 40);
  if (!label) return null;
  const participation = text(item?.participation_state || fallback?.participation_state || "visible_candidate").slice(0, 30);
  const sceneGroup = text(item?.continuity_scene_key || fallback?.continuity_scene_key || "temp_scene_1").slice(0, 60);
  return {
    label,
    source_phrase: text(item?.source_phrase || fallback?.source_phrase || label).slice(0, 80),
    entity_type: text(item?.entity_type || fallback?.entity_type || "temporary_character").slice(0, 40),
    count: Math.max(1, Number(item?.count || fallback?.count || 1) || 1),
    gender_hint: text(item?.gender_hint || fallback?.gender_hint).slice(0, 30),
    age_stage_hint: text(item?.age_stage_hint || fallback?.age_stage_hint).slice(0, 40),
    identity_hint: text(item?.identity_hint || fallback?.identity_hint || label).slice(0, 120),
    species_hint: text(item?.species_hint || fallback?.species_hint).slice(0, 50),
    participation_state: participation,
    must_render: item?.must_render === true || fallback?.must_render === true || temporaryMustRenderV22(participation),
    continuity_scope: text(item?.continuity_scope || fallback?.continuity_scope || "scene_short_term").slice(0, 50),
    continuity_scene_key: sceneGroup,
    continuity_id: text(item?.continuity_id || fallback?.continuity_id || temporaryContinuityIdV22(label, sceneGroup)).slice(0, 100),
    continuity_profile: text(item?.continuity_profile || fallback?.continuity_profile).slice(0, 260),
    wardrobe_state: text(item?.wardrobe_state || fallback?.wardrobe_state).slice(0, 180),
    rendered: item?.rendered === true,
    ai_discovered: item?.ai_discovered === true,
    manual_added_v7824: item?.manual_added_v7824 === true || fallback?.manual_added_v7824 === true,
    selection_source_v7824: text(item?.selection_source_v7824 || fallback?.selection_source_v7824).slice(0, 30),
    temporary_entity_id: text(item?.temporary_entity_id || item?.entity_id || fallback?.temporary_entity_id || fallback?.entity_id).slice(0, 120),
  };
}

function mergeTemporaryCharactersV22(required = [], returned = [], sourceText = "", sceneGroup = "temp_scene_1") {
  const result = [];
  const byKey = new Map();
  const add = (raw, fromAi = false) => {
    const normalized = normalizeTemporaryCharacterV22(raw, { continuity_scene_key: sceneGroup });
    if (!normalized) return;
    if (fromAi) normalized.ai_discovered = true;
    const key = text(normalized.continuity_id) || text(normalized.label).toLowerCase();
    const existing = byKey.get(key) || result.find((item) => item.label === normalized.label);
    if (existing) {
      const merged = normalizeTemporaryCharacterV22({ ...existing, ...normalized, rendered: existing.rendered || normalized.rendered, ai_discovered: existing.ai_discovered || normalized.ai_discovered }, { continuity_scene_key: sceneGroup });
      Object.assign(existing, merged || {});
      return;
    }
    byKey.set(key, normalized);
    result.push(normalized);
  };
  (Array.isArray(required) ? required : []).forEach((item) => add(item, false));
  (Array.isArray(returned) ? returned : []).forEach((item) => add(item, true));
  // 若AI返回了同名人物的连续性描述，优先保留；本地只做结构合并，不往prompt里拼任何模板句。
  return result.slice(0, 12);
}

function temporaryVisibleCastV22(items = []) {
  return (Array.isArray(items) ? items : [])
    .map((item) => normalizeTemporaryCharacterV22(item))
    .filter((item) => item && item.must_render && !["mentioned_only", "offscreen_voice"].includes(text(item.participation_state)))
    .slice(0, 12);
}

function v7824ManualTemporaryForScene(sourceKey = "") {
  const scene = (state.scenes || []).find((item) => text(item.source_key) === text(sourceKey));
  return Array.isArray(scene?.manual_temporary_characters_v7824) ? scene.manual_temporary_characters_v7824 : [];
}

function v7824AiPrimaryTemporary(returned = [], sourceText = "", sceneGroup = "temp_scene_1", sourceKey = "") {
  const formalNames = new Set((state.characters || []).flatMap((item) => {
    const n = normalizeCharacterRecord(item);
    return uniqueTextList([n.name, n.display_name, ...(n.aliases || [])]).map((value) => text(value).replace(/^(?:我的?|他的?|她的?)/, ""));
  }).filter(Boolean));
  const out = [];
  const add = (raw, manual = false) => {
    const item = normalizeTemporaryCharacterV22(raw, { continuity_scene_key: sceneGroup });
    if (!item) return;
    const labelNorm = text(item.label).replace(/^(?:我的?|他的?|她的?)/, "");
    const phraseNorm = text(item.source_phrase).replace(/^(?:我的?|他的?|她的?)/, "");
    if (!manual && [...formalNames].some((name) => name && (labelNorm === name || phraseNorm === name))) return;
    item.ai_discovered = !manual;
    item.manual_added_v7824 = manual || raw?.manual_added_v7824 === true;
    item.selection_source_v7824 = manual ? "manual" : "ai_primary";
    if (!item.continuity_id) item.continuity_id = temporaryContinuityIdV22(item.label, sceneGroup);
    const key = text(item.continuity_id) || text(item.label);
    const existing = out.find((x) => (text(x.continuity_id) || text(x.label)) === key || text(x.label) === text(item.label));
    if (existing) Object.assign(existing, { ...existing, ...item, ai_discovered: existing.ai_discovered || item.ai_discovered, manual_added_v7824: existing.manual_added_v7824 || item.manual_added_v7824 });
    else out.push(item);
  };
  (Array.isArray(returned) ? returned : []).forEach((item) => add(item, item?.manual_added_v7824 === true));
  v7824ManualTemporaryForScene(sourceKey).forEach((item) => add(item, true));
  return out.slice(0, 12);
}

function extractTemporaryCharactersV37(sourceLine = "", formalBaseNames = new Set(), sourceIndex = 1, sceneGroup = "temp_scene_1") {
  const result = [];
  const source = String(sourceLine || "");
  for (const match of source.matchAll(TEMPORARY_ROLE_PATTERN_V37)) {
    const phrase = text(match[0]);
    if (!phrase || /^(?:众人|大家|全场|路人)$/.test(phrase)) continue;
    if ([...formalBaseNames].some((name) => name && (phrase.includes(name) || source.slice(Math.max(0, match.index - name.length), (match.index || 0) + phrase.length + name.length).includes(name)))) continue;
    const label = phrase.replace(/^(?:[一二两三四五六七八九十百千万几多0-9]+(?:名|位|个)?|一个|一位|那名|这名|几名|几个|几位|两个|两位|数名|一群|一队|一排)/, "") || phrase;
    if (result.some((item) => item.label === label)) continue;
    const countMatch = phrase.match(/[0-9]+|一|二|两|三|四|五|六|七|八|九|十|几|多|数/);
    const countMap = {一:1,二:2,两:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9,十:10};
    const count = countMatch ? (Number(countMatch[0]) || countMap[countMatch[0]] || 1) : 1;
    const participationState = temporaryParticipationStateV15(source, phrase);
    const item = normalizeTemporaryCharacterV22({
      label: label.slice(0, 40),
      source_phrase: phrase.slice(0, 80),
      entity_type: "temporary_character",
      count,
      identity_hint: label.slice(0, 80),
      gender_hint: /哥|弟|叔|伯|舅|父|男人|男性|男孩|少年|王子|公子|少爷|丈夫|夫君/.test(label) ? "男" : (/姐|妹|姑|姨|母|女人|女性|女孩|少女|妇人|夫人|小姐|公主|妻子|娘子/.test(label) ? "女" : ""),
      age_stage_hint: /爷爷|奶奶|祖父|祖母|老人|老者|长者/.test(label) ? "老年" : (/孩子|小孩|男孩|女孩|孩童/.test(label) ? "儿童" : ""),
      participation_state: participationState,
      must_render: temporaryMustRenderV22(participationState),
      continuity_scope: "scene_short_term",
      continuity_scene_key: sceneGroup,
      continuity_id: temporaryContinuityIdV22(label, sceneGroup),
    }, { continuity_scene_key: sceneGroup });
    if (item) result.push(item);
    if (result.length >= 10) break;
  }
  return result;
}

function extractCrowdCharactersV37(sourceLine = "") {
  const source = String(sourceLine || "");
  const result = [];
  CROWD_ROLE_PATTERNS_V37.forEach((pattern) => {
    for (const match of source.matchAll(pattern)) {
      const label = text(match[0]);
      if (!label || result.some((item) => item.label === label)) continue;
      result.push({ label, count: 1, participation_state: "background_visible", identity_hint: label });
      if (result.length >= 4) return;
    }
  });
  return result;
}

function extractSystemEntitiesV37(sourceLine = "") {
  const source = String(sourceLine || "");
  const interfaces = [];
  SYSTEM_INTERFACE_PATTERNS_V37.forEach(([pattern, type]) => {
    if (!pattern.test(source) || interfaces.some((item) => item.type === type)) return;
    interfaces.push({ type, participation_state: "screen_visible", content_hint: type });
    pattern.lastIndex = 0;
  });
  SYSTEM_SPRITE_PATTERN_V37.lastIndex = 0;
  const sprites = SYSTEM_SPRITE_PATTERN_V37.test(source)
    ? [{ type: "系统精灵", participation_state: "visible_candidate", identity_hint: "系统精灵" }]
    : [];
  SYSTEM_SPRITE_PATTERN_V37.lastIndex = 0;
  return { interfaces: interfaces.slice(0, 5), sprites };
}

function buildShotStrategyForLineV37(sourceLine = "", plan = {}, lineIndex = 0, previousPrimary = "") {
  const source = text(sourceLine);
  let strategy = "中景交代动作→中近景推进关系→近景落可见反应";
  let primary = "中景";
  if ((plan.system_entities || []).length || (plan.system_sprites || []).length) {
    strategy = "人物中景保留现实空间→主观/过肩中景呈现系统界面→局部特写落实关键数值/图标→人物近景落反应";
    primary = "主观中景";
  } else if (/(?:来到|走进|进入|抵达|推开.*门|新的|另一边|多年后|回忆里|梦中|与此同时)/.test(source)) {
    strategy = "全景或中远景建立新空间→跟拍中景落实人物走位→中近景落关键发现";
    primary = "中远景";
  } else if (/冲|跑|追|推|拉|砸|撞|扑|起身|转身|走到|挥|夺|抢|抱|跪|倒下|崩|击|射|刺|砍|打|扇|泼/.test(source)) {
    strategy = "中远景/全身景交代完整动作→移动中景跟随过程→局部特写强调关键接触点→近景表现动作结果";
    primary = "中远景";
  } else if (/说|问|喊|回答|质问|怒斥|开口|声音/.test(source) && ((plan.allowed || []).length + (plan.temporary_characters || []).length >= 2)) {
    strategy = "双人/多人中景建立站位→过肩中近景推进说话人→反打近景捕捉受话者反应→必要物件特写落冲突点";
    primary = "双人中景";
  } else if (/手机|合同|名单|照片|戒指|钥匙|门把手|指纹|证据|文件|药瓶|信件|按钮|屏幕/.test(source)) {
    strategy = "中景建立人物与道具关系→物件/局部特写揭示关键细节→中近景回到人物处理动作→近景落反应";
    primary = "物件特写";
  } else if ((plan.crowd_characters || []).length) {
    strategy = "群像全景交代空间与群体阵列→中景突出主要人物→近景捕捉关键反应或关系变化";
    primary = "群像全景";
  } else if (/忽然|猛地|发现|看见|意识到|愣住|僵住|震惊|心头|眼神|手指/.test(source)) {
    strategy = "中近景铺垫人物状态→近景捕捉反应变化→仅在关键线索上使用大特写/局部特写";
    primary = "中近景";
  }
  if (primary === previousPrimary && !/(?:对话|说|问|喊|回答)/.test(source)) {
    const variants = [
      "侧面中远景交代动作关系→中景推进→近景落点",
      "前景遮挡下的中景建立层次→中近景推进→局部特写落关键物",
      "中近景先给人物状态→缓慢拉远至中景揭示空间关系→近景回落",
    ];
    strategy = variants[lineIndex % variants.length];
    primary = lineIndex % 2 ? "中近景" : "侧面中远景";
  }
  return { strategy, primary };
}

function buildLineCharacterPlansV36(novelText = "") {
  const sourceScenes = splitOutlineSourceScenes(novelText);
  const registry = (state.characters || []).map((item) => normalizeCharacterRecord(item));
  const groups = new Map();
  registry.forEach((character, index) => {
    const base = characterBaseName(character.base_name || character.name);
    if (!groups.has(base)) groups.set(base, []);
    groups.get(base).push({ ...character, _registry_index: index });
  });
  const validNames = new Set(registry.map((item) => text(item.name)).filter(Boolean));
  const formalBaseNames = new Set([...groups.keys()].filter(Boolean));
  let previousVisible = [];
  const previousStageByBase = new Map();
  let previousShotPrimary = "";
  return sourceScenes.map((scene, lineIndex) => {
    const source = text(scene.source_text);
    const existingScene = (state.scenes || []).find((item) => {
      const sourceIndex = normalizeSourceIndex(item?.source_index, 0);
      return (sourceIndex > 0 && sourceIndex === lineIndex + 1) || text(item?.source_text || item?.text) === source;
    });
    const sourceKey = buildSceneSourceKey(source, lineIndex + 1);
    const stableExistingScene = (state.scenes || []).find((item) => text(item?.source_key) === sourceKey) || existingScene;
    const existingMode = normalizeSceneCharactersMode(stableExistingScene?.characters_mode);
    const existingEffectiveIds = stableExistingScene ? sceneEffectiveSlotIds(stableExistingScene) : [];
    const existingAllowedRaw = existingEffectiveIds.length
      ? existingEffectiveIds.map((slotId) => text(characterCardBySlotId(slotId)?.name || characterCardBySlotId(slotId)?.display_name)).filter(Boolean).slice(0, 8)
      : uniqueTextList(stableExistingScene?.characters || []).slice(0, 8);
    const hasAuthoritativeUiSelection = Boolean(stableExistingScene) && (existingMode === "manual" || existingAllowedRaw.length > 0);
    const hits = [];
    const referenced = [];
    groups.forEach((cards, baseName) => {
      const representative = cards[0];
      const tokens = uniqueTextList(cards.flatMap((card) => characterLineTokensV36(card)));
      let best = null;
      let mentionedAt = -1;
      tokens.forEach((token) => {
        const at = source.indexOf(token);
        if (at >= 0 && (mentionedAt < 0 || at < mentionedAt)) mentionedAt = at;
        const result = tokenDirectlyVisibleInLineV36(source, token);
        if (result.visible && (!best || result.priority < best.priority || (result.priority === best.priority && result.index < best.index))) best = { ...result, token };
      });
      const chosen = chooseCharacterCardForLineV37(cards, source, previousStageByBase.get(baseName) || "");
      if (best && chosen?.name) hits.push({ name: chosen.name, baseName, stage_key: chosen.stage_key || normalizeCharacterStageKeyV37(chosen.age_stages), priority: best.priority, index: best.index, characterIndex: chosen._registry_index || 0 });
      else if (mentionedAt >= 0 && chosen?.name) referenced.push({ name: chosen.name, baseName, index: mentionedAt, characterIndex: chosen._registry_index || 0 });
    });
    let allowed;
    if (hasAuthoritativeUiSelection) {
      allowed = existingAllowedRaw.map((selected) => {
        if (validNames.has(selected)) return selected;
        const base = characterBaseName(selected);
        const cards = groups.get(base) || [];
        return chooseCharacterCardForLineV37(cards, source, previousStageByBase.get(base) || "")?.name || "";
      }).filter(Boolean);
    } else {
      allowed = hits.sort((a, b) => a.priority - b.priority || a.index - b.index || a.characterIndex - b.characterIndex).map((item) => item.name);
    }
    const pronounContinuation = /^(?:可|却|但|但是|而|于是|随后|后来|结果|没想到|偏偏|果然|从此|因此|这时|此时|紧接着)|^(?:他|她|他们|她们|两人|双方)/.test(source);
    if (!hasAuthoritativeUiSelection && !allowed.length && pronounContinuation && previousVisible.length) allowed = [...previousVisible];
    allowed = uniqueTextList(allowed).slice(0, 8);
    allowed.forEach((name) => {
      const card = registry.find((item) => item.name === name);
      const base = characterBaseName(card?.base_name || name);
      const stageKey = normalizeCharacterStageKeyV37(card?.stage_key || card?.age_stages);
      if (base && stageKey) previousStageByBase.set(base, stageKey);
    });
    const onlyMentioned = uniqueTextList(referenced.sort((a, b) => a.index - b.index).map((item) => item.name)).filter((name) => !allowed.includes(name)).slice(0, 8);
    previousVisible = allowed.length ? [...allowed] : previousVisible;
    const temporarySceneGroup = temporaryContinuityGroupV22(sourceScenes, lineIndex);
    const localTemporaryCandidates = extractTemporaryCharactersV37(source, formalBaseNames, lineIndex + 1, temporarySceneGroup);
    const localCrowdCandidates = extractCrowdCharactersV37(source);
    const manualTemporaryCharacters = Array.isArray(stableExistingScene?.manual_temporary_characters_v7824)
      ? stableExistingScene.manual_temporary_characters_v7824.map((item) => ({ ...item, manual_added_v7824: true, selection_source_v7824: "manual" }))
      : [];
    const system = extractSystemEntitiesV37(source);
    const stageBindings = allowed.map((name) => {
      const card = registry.find((item) => item.name === name);
      return { name, base_name: characterBaseName(card?.base_name || name), stage: text(card?.stage_label || card?.age_stages) };
    });
    const partialPlan = {
      allowed,
      temporary_scene_group: temporarySceneGroup,
      temporary_characters: manualTemporaryCharacters,
      crowd_characters: [],
      system_entities: system.interfaces,
      system_sprites: system.sprites,
    };
    const shotPlan = buildShotStrategyForLineV37(source, partialPlan, lineIndex, previousShotPrimary);
    previousShotPrimary = shotPlan.primary;
    return {
      line_index: lineIndex + 1,
      source_text: source,
      source_key: sourceKey,
      relation_selected_slot_ids: normalizeSceneCastSlotIds(stableExistingScene?.relation_selected_slot_ids),
      keyword_selected_slot_ids: normalizeSceneCastSlotIds(stableExistingScene?.keyword_selected_slot_ids),
      manual_added_slot_ids: normalizeSceneCastSlotIds(stableExistingScene?.manual_added_slot_ids),
      manual_excluded_slot_ids: normalizeSceneCastSlotIds(stableExistingScene?.manual_excluded_slot_ids),
      character_slot_ids: stableExistingScene ? sceneEffectiveSlotIds(stableExistingScene) : [],
      allowed,
      mentioned_only: onlyMentioned,
      visual_center: allowed[0] || manualTemporaryCharacters[0]?.label || system.interfaces[0]?.type || "",
      characters_mode: hasAuthoritativeUiSelection ? existingMode : "auto",
      whitelist_source: hasAuthoritativeUiSelection ? "current_scene_selection" : "source_semantics",
      stage_bindings: stageBindings,
      temporary_characters: manualTemporaryCharacters,
      manual_temporary_characters_v7824: manualTemporaryCharacters,
      local_temporary_candidates_v7824: localTemporaryCandidates,
      crowd_characters: [],
      local_crowd_candidates_v7824: localCrowdCandidates,
      temporary_judge_v7824: "ai_primary",
      system_entities: system.interfaces,
      system_sprites: system.sprites,
      shot_strategy: shotPlan.strategy,
      shot_primary: shotPlan.primary,
    };
  });
}

function characterDisplayForPlanV36(name = "") {
  const hit = (state.characters || []).find((item) => text(normalizeCharacterRecord(item).name) === text(name));
  if (!hit) return text(name);
  return text(normalizeCharacterRecord(hit).display_name) || text(name);
}

function buildLineCharacterWhitelistPromptV36(plans = []) {
  const rows = (plans || []).slice(0, 150).map((plan) => {
    const allowed = plan.allowed.length ? plan.allowed.map(characterDisplayForPlanV36).join("、") : "无正式人物";
    const stages = (plan.stage_bindings || []).map((item) => `${characterDisplayForPlanV36(item.name)}=${item.stage || "单阶段"}`).join("；") || "无";
    const manualTemporary = (plan.manual_temporary_characters_v7824 || []).map((item) => text(item.label || item.source_phrase)).filter(Boolean).join("、");
    const temporary = manualTemporary ? `人工指定:${manualTemporary}` : "由AI读取当前原文自行判断";
    const crowd = (plan.crowd_characters || []).map((item) => item.label).join("、") || "无";
    const systems = (plan.system_entities || []).map((item) => item.type).join("、") || "无";
    const sprites = (plan.system_sprites || []).map((item) => item.type).join("、") || "无";
    const mentioned = plan.mentioned_only.length ? plan.mentioned_only.map(characterDisplayForPlanV36).join("、") : "无";
    return `${plan.line_index}|正式:${allowed}|阶段:${stages}|临时:${temporary}|群体:${crowd}|系统:${systems}|精灵:${sprites}|仅提:${mentioned}|景别:${plan.shot_strategy}`;
  });
  return [
    "【逐行出镜层级、年龄阶段与景别计划 v37｜必须逐行执行】",
    "逐行只使用‘正式’名单中的正式人物并遵循阶段绑定；临时人物由AI读取当前原文自行判断，本地候选不是白名单也不是必达项。只有用户人工添加的临时人物是本镜强制补充；mentioned_only/offscreen_voice不得强行实体入画。临时人物只用文字动态表达，禁止输出内部字段名。景别按叙事功能执行。",
    ...rows,
  ].join("\n").slice(0, 12000);
}

function buildAnalysisNovelPayload(novelText = "") {
  const appendix = buildCharacterGuideAppendix();
  const original = text(novelText);
  const aiGenreSkill = buildMarketGenreSkillPrompt(original);
  const fixedVisualStyleSkill = [
    "【统一风格附加视觉信息十一字段模板｜最高优先级】",
    "只输出一行，严格依次覆盖：电影/电视剧/短剧电影质感、胶片或数字实拍、胶片颗粒、滤镜、镜头、镜头畸变或胶片噪点、对比度、饱和度、光线与明暗层次、电影级叙事构图、整体氛围感。",
    "不得缺项、换序、写字段名、写剧情或引用旧结果；每项必须根据当前全文自由判断。",
  ].join("\n");
  const globalAdvice = text(readFieldValue("#globalAnalysisAdvice", state.global_analysis_advice)).slice(0, 1800);
  const globalAdviceBlock = [
    "【用户填写的统一风格与人物全局建议｜高优先级】",
    globalAdvice || "未填写；由AI完全依据当前原文自由判断",
    "该建议只控制内容类型、时代世界观、统一视觉、人物身份与造型方向；不得据此新增人物、改名、改关系或改写剧情。",
  ].join("\n");
  const source = appendix ? `${appendix}\n\n【小说原文开始】\n${original}\n【小说原文结束】` : original;
  const professionalVisualStyleSkill = buildProfessionalVisualStyleSkill(original, 1800);
  const merged = [UNIVERSAL_ANALYSIS_ALIGNMENT_SKILL_V36, UNIVERSAL_CHARACTER_LOGIC_SKILL_V38, globalAdviceBlock, UNIVERSAL_CHARACTER_RECOGNITION_SKILL_FAST, HIGH_QUALITY_CHARACTER_APPEARANCE_SKILL_FAST, aiGenreSkill, professionalVisualStyleSkill, fixedVisualStyleSkill, source].filter(Boolean).join("\n\n");
  return appendInstructionToNovel(merged, "analysis");
}

const API_CONSTRAINT_FIELD_LIMIT = 1000000;

const V783_TEMPORARY_DYNAMIC_TEXT_RULE = `【临时人物AI主判与纯文字动态规则｜V78.2.6｜高优先级】正式人物只来自当前强制名单。每个本镜的名单外人物/群体由AI直接阅读当前source_text自行判断：只有当前镜真实可见才返回temporary_characters；只有声音返回offscreen_voice；只被提及返回mentioned_only且不得实体入画。软件本地候选、称谓词库和旧visual_exposition结果都不是最终裁判，不得因为本地候选存在就强行加人。“沈家、某公司、某宗门、某班级、某军队”等家族/组织名称本身不是人物；只有原文明示具体成员、人数、阵列、站位、动作或镜头明确切到可见成员时，才可返回群体临时人物。AI返回的temporary_characters就是本镜主结果，字段只用于结构化反馈，不得把visual_exposition、continuity_id、temp_character_xxx等内部字段写进画面正文。可见临时人物必须依据当前原文写清必要身份/人数、准确空间位置、姿态/朝向、连续动作链、视线/表情/直接反应、与正式人物或道具的互动；continuity只维持静态身份与服装短期一致，不得替代当前动作。`;

const V7824_BLOCKING_VISUAL_DENSITY_RULE = `【站位、调度与画面内容密度｜V78.2.6｜最高优先级】
1. 先判断本时段是否真的有人物可见。没有可见人物时，禁止出现“人物当前站位、人物所在位置、人物保持站位”等模板词，只写可拍的空间、物件、环境变化、构图和镜头落点。
2. 有人物时，站位必须是可拍的blocking，不写抽象“在场/位于当前位置”。优先使用“左/中/右 + 前景/中景/后景 + 具体空间锚点（门口、窗边、床侧、书案旁、桌前、走廊尽头等） + 身体朝向/视线轴”，多人时写清谁靠近谁、谁挡住谁、谁先进入/退出以及前后景层级。
3. 每个时段只写与当前原文有用的可见信息。正文约70%-85%用于当前原文特有的动作、互动、道具和空间变化；删除“高级感、氛围拉满、人物在场、环境保持一致”等低信息量空话，不用重复形容词凑字数。
4. 动作必须形成因果链：起始状态→2到5个连续可见动作→作用对象/道具变化→直接反应→动作后的新状态→镜头落点。不能只写结果，也不能用镜头术语代替动作。
5. 多人场面先建立scene geography和冲突轴，再推进关键反应：全景/中远景负责人数和站位，中景/中近景负责关系与动作，近景/特写只承接关键表情或物件，不得用特写描述完整走位。
6. 连续镜头保持180度轴线、视线方向、人物左右关系、运动方向和持物状态；若当前原文没有位置变化，沿用上一镜动作结束后的站位，不重新随机布置。
7. 精品模式与普通模式共享同一Master Visual Prompt。精品导出只允许增加引用格式，不得删减、泛化或替换站位、动作、互动、场景状态、道具行为和镜头落点。`;

const V7830_MULTI_CUT_STORYTELLING_RULE = `【原文分镜多镜头切换表达｜V78.3.0｜最终最高优先级】
1. 本规则覆盖此前“只有新事件才能切镜”“每个时段必须120到240字”“每个时段塞3到6个视觉节点”等旧密度要求。外层仍是一行原文一张卡；真正的镜头来回切换放在同一卡的 timeline_segments 中。
2. 非常短的静态信息/纯空镜允许1个镜头；普通叙事优先2个；对白、人物情绪、多人关系优先2到3个；动作冲突、揭示、明显前后反应可3到4个。不要为了数量编造不存在的人物、动作、台词、道具或结果。
3. 优先使用自然的影视覆盖顺序：建立场面/双人关系 → 当前主体动作或说话人 → 听者/对手反应 → 手部/眼神/关键道具细节 → 必要时回到主体或结果。不是每条都必须五步，按原文需要选择2到4个即可。
4. 对白镜头要有来回切换：先拍说话人，再拍听者真实反应，必要时再切回说话人或关键细节；每个时段仍只允许一个 speaker，同一句原文对白只出现一次。
5. 动作镜头优先“整体动作可读 → 关键过程/接触细节 → 动作结果或他人反应”；多人镜头优先“群体/空间关系 → 核心人物 → 关键反应”；规则、旁白、世界观说明优先“可见环境/秩序 → 与原文有关的物件/行为 → 结果或反应”，不能为了可视化强造人物。
6. 每个小镜头正文用大白话，只写观众这一秒真正看到的东西，通常40到110个中文字符；避免长篇光影文学、抽象氛围、摄影教学、重复人物外形和统一风格。画面丰富来自镜头切换，不来自把一个prompt写得很复杂。
7. 镜头头字段继续各自填写 shot_size、shot_angle、movement、transition；相邻小镜头应根据观看重点合理变化景别/焦段/机位/构图，但必须保持180度轴线、人物左右关系、视线、持物、动作方向和场景连续。
8. 普通模式与精品模式使用完全相同的多镜头母版。参考图只在生成完成后做视觉锚定，不得减少 timeline_segments、不许把多个镜头压回一个，也不得把大白话正文改成参考图说明。
9. 返回前静默检查：除确实只需单镜的简单原文外，如果一张卡可以通过“主体+反应”或“场面+细节”更清楚表达却仍只有一个平铺镜头，应在总剧情事实不变的前提下重新拆成2到4个连续时段。`;

const V78302_SCENE_EVENT_OWNERSHIP_RULE = `【分镜场景锚点与内容事件单一归属｜V78.3.0.2｜最高优先级】
1. 一行原文对应一张外层分镜卡，一张卡必须只有一个确定的 scene_anchor / visual_context。当前原文没有明确换地点时，必须继承上一张卡的场景；只有地点、时间+环境、电话两端、回忆/梦境/穿越、明确室内外或独立空间切换时才新建场景锚点。
2. 同一张卡内所有 timeline_segments 共用同一场景锚点。第一个小镜头可以自然交代场景，后续小镜头默认继承，不要每镜重复“在某某场景内”；人物可以在同一场景内改变站位、朝向和镜位。
3. 每张卡先在内部建立内容事件表：对白事件、动作事件、反应事件、道具事件、信息揭示事件。每个事件只能分配给一个 timeline_segment 作为 owner；后续小镜头只能拍该事件造成的新状态、受话者反应、细节或结果，禁止再次完整复述同一句对白、同一个动作或同一个信息。
4. 同一句原文对白只允许一个 owner 时段填写 speech_text；其他时段只拍听者/对手反应，不得再次写完整台词。原文确实重复说了同一句话时，才允许按原文实际出现次数分别拥有独立事件。
5. 同一个动作事件要拆“过程/细节/结果”而不是重复执行。例如“拿起文件扔到桌上”只能发生一次：可以分别拍手伸向文件、文件落桌、旁人反应，但不得在多个时段重复写“再次拿起并扔到桌上”。
6. scene_anchor、内容事件 owner、卡内 local timeline 与整部视频 global timeline 是不同层级：AI只负责卡内镜头和事件分配；全局绝对秒数由软件统一顺排，不得让相邻外层卡出现重叠或倒序。`;

globalThis.__V78_MULTI_CUT_STORYTELLING__=Object.freeze({version:"v78.3.0.3",mode:"timeline_segments",defaultCuts:"2-4",plainLanguage:true,sceneAnchor:true,eventOwnership:true,canonicalTimeline:true});

