function buildSceneTemplatePrompt(source = "", scene = {}, shot = {}, forcedBranch = "") {
  const branch = forcedBranch || detectSceneTemplateBranch(source);
  if (!branch) return "";
  if (branch === 'ceo') return buildCeoTemplatePrompt(source, scene, shot);
  if (branch === 'campus') return buildCampusTemplatePrompt(source, scene, shot);
  if (branch === 'palace') return buildPalaceTemplatePrompt(source, scene, shot);
  if (branch === 'revenge') return buildRevengeTemplatePrompt(source, scene, shot);
  if (branch === 'emergency') return buildEmergencyTemplatePrompt(source, scene, shot);
  if (branch === 'celebration') return buildCelebrationTemplatePrompt(source, scene, shot);
  if (branch === 'family_conflict') return buildFamilyConflictTemplatePrompt(source, scene, shot);
  if (branch === 'courtroom') return buildCourtroomTemplatePrompt(source, scene, shot);
  return "";
}

function buildStoryInterfacePrompt(sourceValue = "", scene = {}, shot = {}) {
  const source = text(sourceValue) || text(scene?.source_text || scene?.text);
  if (!sourceNeedsStoryInterface(source)) return "";
  if (sourceNeedsSystemInterface(source)) return buildSystemTemplatePrompt(source, scene, shot);
  if (sourceNeedsBarrageInterface(source)) return buildBarrageTemplatePrompt(source, scene, shot);
  if (sourceNeedsScreenInterface(source)) return buildChatUiTemplatePrompt(source, scene, shot);
  if (sourceNeedsDocumentInterface(source)) return buildDocumentTemplatePrompt(source, scene, shot);
  return "";
}

function directorVisibleReaction(sourceText, lead, second = "") {
  const source = text(sourceText);
  const target = second && second !== lead ? second : "对面的人";
  if (/死寂|鸦雀无声|瞬间安静|全场安静/.test(source)) return `周围人的动作同时停住，视线集中到${lead}身上`;
  if (/震惊|错愕|惊呆|意外|没想到|得知|发现|意识到|真相/.test(source)) return `${lead}动作突然停住，抬眼看向${target}`;
  if (/愤怒|生气|恼怒|暴怒|恨意/.test(source)) return `${lead}下颌绷紧，手指用力收紧`;
  if (/伤心|难过|委屈|心寒|失望|绝望|崩溃|痛苦/.test(source)) return `${lead}垂下视线，手指慢慢攥紧`;
  if (/害怕|恐惧|惊慌|紧张|不安/.test(source)) return `${lead}呼吸一滞，身体下意识后退`;
  if (/尴尬|难堪|羞辱|丢脸|局促/.test(source)) return `${lead}避开周围视线，手指紧紧攥住衣角`;
  if (/开心|高兴|惊喜|激动|庆幸|欣喜/.test(source)) return `${lead}眼睛亮起，笑意迅速展开`;
  if (/冷静|决绝|坚定|下定决心|不再犹豫/.test(source)) return `${lead}站直身体，目光变得坚定`;
  if (/怀疑|疑惑|警惕|戒备/.test(source)) return `${lead}微微眯眼，视线紧盯${target}`;
  if (/松了口气|放松|安心/.test(source)) return `${lead}肩膀慢慢放松，呼吸恢复平稳`;
  return "";
}

function directorActionClause(sourceText, lead, second = "") {
  let source = text(sourceText)
    .replace(/[“\"][^”\"]{0,180}[”\"]/g, "")
    .replace(/[‘'][^’']{0,180}[’']/g, "")
    .replace(/【[^】]{0,100}】/g, "");
  const clauses = source
    .split(/[，,；;。！？!?：:]/)
    .map((item) => text(item).replace(/^(于是|然后|随后|接着|下一秒|当时|此时|原来|后来|结果|没想到|忽然|突然)\s*/, ""))
    .filter((item) => item.length >= 2);
  const visibleVerb = /走|跑|冲|追|逃|进|出|离开|转身|起身|坐下|跪下|倒下|停步|后退|靠近|推开|关上|打开|拿起|放下|放到|放在|摆到|摆在|铺开|摊开|按住|取出|掏出|递出|推过|摔|砸|扔|抓住|握紧|抱住|扶住|举手|举杯|低头|抬眼|回头|看向|盯着|对视|拨通|按下|签下|写下|画出|划出|制作|做出|记录|比较|翻开|拔剑|挥剑|格挡|闪避|施法|跃起|落地|亮起|震动|碎裂|坍塌|开口|质问|回答|宣布|笑|哭|参加|前往|赶到|返回|醒来/;
  let clause = clauses.find((item) => visibleVerb.test(item)) || "";
  if (!clause && /说|问|喊|回答|解释|宣布|质问|开口/.test(sourceText)) {
    return `${lead}看向${second || "对面的人"}开口，抬手做出一个简短手势`;
  }
  if (!clause && /参加|赴|前往|赶往/.test(sourceText)) {
    return `${lead}走向场景入口，抬眼确认前方`;
  }
  if (!clause) return "";
  clause = clause
    .replace(/^(我为了|为了|因为|由于|当|在)/, "")
    .replace(/才发现|竟然|居然/g, "发现")
    .replace(/自己的|本人/, "");
  if (clause.length > 42) {
    const cut = Math.max(clause.lastIndexOf("，", 42), clause.lastIndexOf("、", 42));
    clause = clause.slice(0, cut > 20 ? cut : 42).replace(/[，、\s]+$/g, "");
  }
  if (/^(走|跑|冲|追|逃|进|出|离开|转身|起身|坐下|跪下|倒下|停步|后退|靠近|推开|关上|打开|拿起|放下|放到|放在|摆到|摆在|取出|掏出|递出|推过|摔|砸|扔|抓住|握紧|抱住|扶住|举手|举杯|低头|抬眼|回头|看向|拨通|按下|签下|写下|翻开|拔剑|挥剑|格挡|闪避|施法|跃起|落地)/.test(clause)) {
    return `${lead}${clause}`;
  }
  return clause;
}

function directorAbstractPrompt(sourceText, names, location, profile) {
  const subjects = directorRoleSubjects(sourceText, names);
  const lead = subjects[0] || directorFallbackSubject(sourceText);
  const second = subjects.find((item) => item !== lead) || "对面的人";
  const object = directorVisualObject(sourceText);
  const reaction = directorVisibleReaction(sourceText, lead, second);
  if (/马上|即将|就要|快要|正(?:在)?赶来|赶到|到达|来了|逼近|现身/.test(sourceText)) {
    const ancient = /古代|宫|王爷|侯爷|世子|将军|皇子|公主|侍卫|王侯|府邸|朝堂/.test(`${sourceText} ${location}`);
    const fantasy = /玄幻|仙侠|宗门|灵力|魔气|仙山|神殿/.test(`${sourceText} ${location}`);
    const scifi = /未来|星舰|机甲|基地|太空|科技/.test(`${sourceText} ${location}`);
    const figure = ancient ? "高大权贵男子" : fantasy ? "气场强烈的高大身影" : scifi ? "身穿深色战术服的高大身影" : `${lead}`;
    const clothing = ancient ? "深色长袍与披风被迎面气流掀起" : fantasy ? "衣袍和周身能量微光随步伐向后拖曳" : scifi ? "战术外套与肩部装甲反射冷光" : "外套下摆随快速步伐向后扬起";
    return `${figure}从${location}的纵深尽头快步逼近，${clothing}→两侧建筑、道路与随行人群被拉成强烈纵深透视，压迫感随距离缩短不断增强→附近人物停下动作同时回头，镜头以长焦压缩空间后快速推近，停在来人即将进入正面近景的位置`;
  }
  if (/多年后|数年后|第二天|翌日|次日|清晨|黎明|傍晚|黄昏|深夜|夜里/.test(sourceText)) {
    const time = /清晨|黎明/.test(sourceText) ? "清晨" : /傍晚|黄昏/.test(sourceText) ? "傍晚" : /深夜|夜里/.test(sourceText) ? "夜晚" : /第二天|翌日|次日/.test(sourceText) ? "次日" : "多年后";
    return `大全景，${time}的${location}，${lead}从场景一侧走入画面→周围建筑、地面线条与远处人影拉出清楚纵深→镜头稳定轻推并停在主体进入画面后的落点`;
  }
  if (/发现|找到|看见|注意到|认出/.test(sourceText) && object) {
    return `特写，${location}，${lead}低头查看${object}，指尖停在物品边缘，视线迅速凝住，镜头轻微推近`;
  }
  if (/所有人都知道|只有我|被瞒|欺骗|背叛|偏心|排挤|孤立/.test(sourceText)) {
    return `近景，${location}，${lead}扫过周围回避视线的人，手指慢慢收紧，最后低头压住情绪，镜头缓慢推近`;
  }
  if (/得知|听说|发现|意识到|明白|认出|没想到|原来|真相/.test(sourceText)) {
    const visibleChange = reaction || `${lead}手上的动作突然停住，抬眼看向${second}`;
    return `近景，${location}，${visibleChange}，镜头缓慢推近`;
  }
  if (/决定|选择|答应|拒绝|发誓|下定决心|不再犹豫|准备/.test(sourceText)) {
    const objectAction = object ? `伸手握住${object}` : "缓慢站直身体";
    return `中近景，${location}，${lead}短暂停顿后${objectAction}，抬眼看向前方，目光逐渐坚定，镜头轻微推近`;
  }
  if (reaction) {
    return `${profile.shot_size}，${location}，${reaction}，身体状态出现清晰变化，镜头${profile.movement}`;
  }
  return "";
}

function directorConcretePrompt(sourceText, names, location, profile) {
  const subjects = directorRoleSubjects(sourceText, names);
  const lead = subjects[0] || directorFallbackSubject(sourceText);
  const second = subjects.find((item) => item !== lead) || "";
  const action = directorActionClause(sourceText, lead, second);
  const reaction = directorVisibleReaction(sourceText, lead, second);
  const object = directorVisualObject(sourceText);
  let mainAction = action;
  if (!mainAction && object) {
    mainAction = `${lead}把${object}拿到眼前，视线停在物品上`;
  }
  if (!mainAction) {
    mainAction = second ? `${lead}抬眼看向${second}` : `${lead}停在场景中央，缓慢抬眼`;
  }
  const clauses = [mainAction];
  if (reaction && !mainAction.includes(reaction.slice(0, 8))) clauses.push(reaction);
  const environment = /病房|医院|诊室|手术室/.test(location)
    ? "诊桌、椅背、窗边冷光与门口人影拉出清楚前中后景"
    : /客厅|卧室|厨房|餐厅|家中|别墅|公寓/.test(location)
      ? "沙发、桌面、门框与室内光线拉出清楚前中后景"
      : /酒店|宴会厅|酒会|婚礼|会场/.test(location)
        ? "灯光、桌面陈设与周围宾客拉出清楚前中后景"
        : /校园|教室|走廊|操场|宿舍/.test(location)
          ? "课桌、走廊线条与周围学生拉出清楚前中后景"
          : /古代|宫殿|府邸|庭院|古城|军营/.test(location)
            ? "宫墙廊柱、衣摆与随行人物拉出清楚前中后景"
            : /玄幻|仙山|宗门|秘境|魔宫/.test(location)
              ? "雾气、能量微光与远处地形拉出清楚前中后景"
              : /未来|科技|飞船|太空|基地/.test(location)
                ? "冷色设备光、金属结构与远处人影拉出清楚前中后景"
                : "门框、桌面、走道或周围人影拉出清楚前中后景";
  const cameraText = profile.movement === "稳定拍摄" ? "镜头稳定停在动作结束点" : `镜头${profile.movement}并停在直接反应上`;
  const nodes = [clauses[0], environment, clauses.slice(1).join("，") || cameraText, cameraText]
    .filter(Boolean)
    .filter((item, index, items) => items.indexOf(item) === index)
    .slice(0, 4);
  return nodes.join("→");
}

function normalizedClauseKey(value) {
  return text(value).replace(/[，。！？；：、,.!?;:\s]/g, "").replace(/同一|画面|镜头|人物/g, "").slice(0, 120);
}

function clauseSimilarity(left, right) {
  const a = normalizedClauseKey(left);
  const b = normalizedClauseKey(right);
  if (!a || !b) return 0;
  if (a === b || a.includes(b) || b.includes(a)) return Math.min(a.length, b.length) / Math.max(a.length, b.length);
  const grams = (value) => {
    const set = new Set();
    for (let i = 0; i < value.length - 1; i += 1) set.add(value.slice(i, i + 2));
    return set;
  };
  const ga = grams(a);
  const gb = grams(b);
  if (!ga.size || !gb.size) return 0;
  let hit = 0;
  ga.forEach((item) => { if (gb.has(item)) hit += 1; });
  return hit / Math.max(ga.size, gb.size);
}

function promptClauseScore(clause, scene, shot, index) {
  let score = 0;
  const value = text(clause);
  const names = directorSceneCharacters(scene, shot, `${value} ${text(scene?.source_text || scene?.text)}`);
  if (names.some((name) => value.includes(name))) score += 5;
  if (/走|跑|冲|追|逃|推|举手|举杯|起身|转身|走出|拨通|拿出|递|放下|站稳|倒下|跪下|摇晃|抬眼|低头|回头|收紧|后退|靠近|停住|扫过|碰撞|亮起|打开|关上|签字|抬手|俯身|拔剑|挥剑|格挡|闪避|施法|跃起|落地|碎裂|坍塌/.test(value)) score += 5;
  if (/杯子|酒杯|手机|合同|协议|桌面|门口|洗手台|婴儿床|屏幕|文件|信件|戒指|照片|钥匙|药物|长剑|刀|枪|弓箭|信物|法器|书卷|线索/.test(value)) score += 3;
  if (/反应|笑容僵住|瞳孔|脸色|血色|手指|呼吸|身体重心|视线|眼眶|嘴角|肩膀/.test(value)) score += 3;
  if (/结束时|停在|最终|句末|动作完成|画面定格/.test(value)) score += 2;
  if (index === 0 && /全景|中景|近景|特写|平视|俯拍|仰拍|跟拍|推近|手持/.test(value)) score += 2;
  if (/光影层次|电影颗粒|4K|高清|质感|低饱和|冷暖|高级感/.test(value)) score -= 5;
  if (/气氛压抑|情绪复杂|画面表现|展现出|关系恶化|继续保持|仍然维持/.test(value)) score -= 4;
  return score;
}

function maxPromptCharsForSegment(duration, density = readPromptDensity()) {
  const seconds = Math.max(1, Number(duration) || 2);
  if (density === "detailed") return Math.min(230, 120 + seconds * 24);
  if (density === "balanced") return Math.min(190, 88 + seconds * 22);
  return Math.min(140, 65 + seconds * 18);
}

function splitPromptClauses(value) {
  const source = text(value);
  if (!source) return [];
  const primary = source.split(/[；;。]/).map((item) => text(item)).filter(Boolean);
  const result = [];
  primary.forEach((item) => {
    if (item.length > 150) {
      const parts = item.split(/[，,]/).map((part) => text(part)).filter(Boolean);
      if (parts.length > 3) {
        parts.forEach((part) => result.push(part));
        return;
      }
    }
    result.push(item);
  });
  return result;
}

function compactPromptForFocus(promptValue, duration, scene, shot, segmentIndex = 0, previousClauses = []) {
  const density = readPromptDensity();
  const maxChars = maxPromptCharsForSegment(duration, density);
  const rawClauses = splitPromptClauses(promptValue);
  if (!rawClauses.length) return { prompt: text(promptValue), clauses: previousClauses, changed: false };
  const unique = [];
  rawClauses.forEach((clause) => {
    if (unique.some((kept) => clauseSimilarity(kept, clause) >= 0.78)) return;
    if (segmentIndex > 0 && previousClauses.some((previous) => clauseSimilarity(previous, clause) >= 0.82)) return;
    unique.push(clause);
  });
  const maxClauseCount = density === "detailed" ? 4 : density === "balanced" ? 3 : 2;
  const ranked = unique.map((clause, index) => ({ clause, index, score: promptClauseScore(clause, scene, shot, segmentIndex) }));
  const mustKeep = new Set();
  if (ranked.length) mustKeep.add(0);
  const bestAction = [...ranked].sort((a, b) => b.score - a.score || a.index - b.index)[0];
  if (bestAction) mustKeep.add(bestAction.index);
  const lastResult = [...ranked].reverse().find((item) => /结束时|停在|最终|反应|瞳孔|脸色|眼眶|手指|身体重心|视线/.test(item.clause));
  if (lastResult) mustKeep.add(lastResult.index);
  const selected = [];
  ranked
    .sort((a, b) => (mustKeep.has(b.index) - mustKeep.has(a.index)) || b.score - a.score || a.index - b.index)
    .forEach((item) => {
      if (selected.length >= maxClauseCount) return;
      if (item.score < -1 && !mustKeep.has(item.index)) return;
      selected.push(item);
    });
  selected.sort((a, b) => a.index - b.index);
  let clauses = selected.map((item) => item.clause);
  if (!clauses.length) clauses = unique.slice(0, maxClauseCount);
  let prompt = clauses.join("；");
  while (prompt.length > maxChars && clauses.length > 2) {
    const removable = clauses
      .map((clause, index) => ({ clause, index, score: promptClauseScore(clause, scene, shot, segmentIndex) }))
      .filter((item) => item.index !== 0)
      .sort((a, b) => a.score - b.score || b.index - a.index)[0];
    if (!removable) break;
    clauses.splice(removable.index, 1);
    prompt = clauses.join("；");
  }
  if (prompt.length > maxChars) {
    const cut = Math.max(prompt.lastIndexOf("，", maxChars), prompt.lastIndexOf("；", maxChars));
    prompt = prompt.slice(0, cut > maxChars * 0.65 ? cut : maxChars).replace(/[，；、\s]+$/g, "");
  }
  const changed = text(promptValue).replace(/[。；;\s]+$/g, "") !== prompt.replace(/[。；;\s]+$/g, "");
  return { prompt, clauses: [...previousClauses, ...clauses].slice(-12), changed };
}

function repairPromptAgeConflict(promptValue, sceneText, shot) {
  let prompt = text(promptValue);
  const source = text(sceneText);
  if (!/出生|新生儿|产房|婴儿床|襁褓|刚出生/.test(source)) return prompt;
  const scene = sourceSceneById(text(shot?.parent_scene_id) || text((shot?.parent_scene_ids || [])[0]));
  const names = directorSceneCharacters(scene, shot, source);
  names.forEach((name) => {
    const character = state.characters.find((item) => text(item.name) === name);
    if (!character || isParentCharacter(character)) return;
    const babyLabel = character.gender === "男" ? "新生男婴" : character.gender === "女" ? "新生女婴" : "新生婴儿";
    prompt = prompt
      .replace(new RegExp(`${name}（?年轻亚洲女性[^，；。]*）?`, "g"), `${name}（${babyLabel}）`)
      .replace(new RegExp(`${name}（?年轻亚洲男性[^，；。]*）?`, "g"), `${name}（${babyLabel}）`)
      .replace(new RegExp(`${name}（?约?大学生[^，；。]*）?`, "g"), `${name}（${babyLabel}）`);
  });
  return prompt;
}

function isWeakDirectorPrompt(promptValue, sourceText = "", requiredCharacters = []) {
  const prompt = text(promptValue);
  if (!prompt || prompt.length < 24) return true;
  const genericPhrases = /当前剧情实景空间|画面先交代|落实原文|完成原文中的|动作对象|受力方向|主要人物|必要群像|视觉中心|起始位置|关系恶化|画面表现|展现出|神情复杂|人物表情发生变化|根据原文|当前场景中的人物/;
  if (genericPhrases.test(prompt)) return true;
  const malformedTail = outlinePromptHasMalformedTail(prompt);
  const repeatedCameraHeaders = (prompt.match(/(?:大全景|全景|远景|中景|中近景|近景|特写)[-，,、\s]*(?:平视|俯视|仰视|侧视|低机位|高机位)/g) || []).length >= 3;
  if (malformedTail || repeatedCameraHeaders) return true;
  const actionHits = (prompt.match(/站|坐|走|跑|冲|追|逃|停|看|抬眼|低头|回头|举手|举杯|推|递|拿|放|打开|关上|亮起|震动|转身|扶住|抓住|握紧|抱住|拨通|签下|写下|翻开|拔剑|挥剑|格挡|闪避|施法|收紧|开口|对视|前倾|护住|起身|跪下|倒下|后退|靠近|碎裂|坍塌/g) || []).length;
  const sourceCore = text(sourceText).replace(/[，。！？；：、\s]/g, "");
  const promptCore = prompt.replace(/^(?:\d+\s*-\s*\d+s\s*)?(?:大全景|全景|中景|近景|特写|中近景)[，,]?/, "").replace(/[，。！？；：、\s]/g, "");
  const hasVisualLanguage = /大全景|全景|中景|近景|特写|俯拍|跟拍|推近|稳定拍摄|轻推/.test(prompt);
  const nearCopy = sourceCore.length > 12 && promptCore.includes(sourceCore.slice(0, Math.min(sourceCore.length, 30))) && actionHits < 2 && !hasVisualLanguage;
  const required = uniqueTextList(requiredCharacters).filter(Boolean).slice(0, 3);
  const hasCharacterSignal = required.some((name) => prompt.includes(name)) || /\b我\b|主角|女主|男主|女性|男性|女孩|男孩|孩子|老人|母亲|父亲|丈夫|妻子|同学|同事|老师|医生|警察|皇帝|王爷|将军|弟子/.test(prompt);
  const missingCharacter = required.length > 0 && !hasCharacterSignal && prompt.length < 48;
  return nearCopy || missingCharacter;
}

function buildDirectorPrompt(sourceText, scene, shot, clauseIndex = 0) {
  const context = `${text(scene?.source_context)} ${text(scene?.source_text || scene?.text)} ${text(scene?.next_context)}`;
  const names = directorSceneCharacters(scene, shot, `${sourceText} ${context}`);
  const location = directorLocationAnchor(sourceText, context);
  const profile = directorCameraProfile(sourceText, shot?.subject_kind);
  const action = directorActionClause(sourceText, names[0] || directorFallbackSubject(sourceText), names[1] || "");
  if (action) return directorConcretePrompt(sourceText, names, location, profile);
  const abstractPrompt = directorAbstractPrompt(sourceText, names, location, profile);
  if (abstractPrompt) return abstractPrompt;
  return directorConcretePrompt(sourceText, names, location, profile);
}

function directorClauses(sourceText) {
  return String(sourceText || "")
    .split(/[，,；;。！？!?]/)
    .map((item) => text(item))
    .filter((item) => item.length >= 3)
    .slice(0, 4);
}

function enhanceShotWithDirectorQuality(scene, shot) {
  const sourceText = text(shot.source_basis) || text(scene?.source_text || scene?.text);
  const requiredCharacters = directorSceneCharacters(scene, shot, `${sourceText} ${text(scene?.source_context)} ${text(scene?.next_context)}`);
  const existingSegments = normalizeTimelineSegments(shot.timeline_segments);
  if (existingSegments.length) {
    if (existingSegments.length === 1 && isWeakDirectorPrompt(existingSegments[0].prompt, sourceText, requiredCharacters)) {
      const only = existingSegments[0];
      const duration = only.end_offset - only.start_offset;
      const clauses = directorClauses(sourceText);
      if (duration >= 5 && clauses.length >= 2) {
        const firstDuration = Math.max(2, Math.floor(duration / 2));
        const secondDuration = duration - firstDuration;
        const firstPrompt = buildDirectorPrompt(clauses[0], scene, shot, 0);
        const secondSource = clauses.slice(1).join("，") || sourceText;
        const secondPrompt = buildDirectorPrompt(secondSource, scene, shot, 1);
        if (firstPrompt && secondPrompt) {
          shot.timeline_segments = normalizeTimelineSegments([
            { ...only, start_offset: 0, end_offset: firstDuration, source_basis: clauses[0], prompt: firstPrompt, ...directorCameraProfile(clauses[0], shot.subject_kind) },
            { ...only, start_offset: firstDuration, end_offset: firstDuration + secondDuration, source_basis: secondSource, prompt: secondPrompt, transition: "连续承接", ...directorCameraProfile(secondSource, shot.subject_kind) },
          ]);
          shot.prompt = timelinePrompt(shot.timeline_segments);
          shot.duration = duration;
          shot.end_second = shot.start_second + duration;
          return true;
        }
      }
    }
    let changed = false;
    shot.timeline_segments = existingSegments.map((segment, index) => {
      if (!isWeakDirectorPrompt(segment.prompt, segment.source_basis || sourceText, requiredCharacters)) return segment;
      const segmentSource = text(segment.source_basis) || sourceText;
      const profile = directorCameraProfile(segmentSource, segment.subject_kind || shot.subject_kind);
      const replacement = buildDirectorPrompt(segmentSource, scene, { ...shot, ...segment }, index);
      if (!replacement) return segment;
      changed = true;
      return {
        ...segment,
        prompt: replacement,
        shot_size: text(segment.shot_size) || profile.shot_size,
        shot_angle: text(segment.shot_angle) || profile.shot_angle,
        movement: text(segment.movement) || profile.movement,
      };
    });
    if (changed) {
      shot.prompt = timelinePrompt(shot.timeline_segments);
      return true;
    }
    return false;
  }

  if (!isWeakDirectorPrompt(shot.prompt, sourceText, requiredCharacters)) return false;
  const profile = directorCameraProfile(sourceText, shot.subject_kind);
  const replacement = buildDirectorPrompt(sourceText, scene, shot, 0);
  if (!replacement) return false;
  shot.prompt = replacement;
  shot.shot_size = text(shot.shot_size) || profile.shot_size;
  shot.shot_angle = text(shot.shot_angle) || profile.shot_angle;
  shot.movement = text(shot.movement) || profile.movement;
  return true;
}

function applyDirectorQualityPass(sceneId = "") {
  let changed = 0;
  state.outlineShots.forEach((shot) => {
    const parentId = text(shot.parent_scene_id) || text((shot.parent_scene_ids || [])[0]);
    if (sceneId && parentId !== sceneId) return;
    const scene = sourceSceneById(parentId);
    if (enhanceShotWithDirectorQuality(scene, shot)) changed += 1;
  });
  if (changed) {
    sortOutlineShots();
  }
  return changed;
}


const PROMPT_BAD_PHRASES = /背景人物、家具或建筑线条保持简洁|周围环境保持简洁|画面先交代|落实原文|完成原文中的|当前剧情实景空间|动作对象|受力方向|视觉中心|人物保持原有站位|视线方向稳定|画面没有其他变化|黑色字样|诡异字样|神秘符号|不知名文字|凭空出现的文字|可读文字|纸上写着|表格上写着|写下[^，。→]{0,40}(?:字样|文字|翻身|会坐|会走|说话)/;

function stripInlineCharacterCardDetails(promptValue = "") {
  let result = String(promptValue || "");
  (state.characters || []).forEach((character) => {
    const name = text(character?.name);
    if (!name) return;
    const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    result = result.replace(new RegExp(`${escaped}（[^）]{28,260}）`, "g"), name);
  });
  return result.replace(/\s+/g, " ").trim();
}

function promptSemanticTokens(value = "") {
  const source = text(value)
    .replace(/00:\d{2}-00:\d{2}/g, "")
    .replace(/场景[：:]/g, "")
    .replace(/[，。！？；：、,.!?;:\s|→()（）“”]/g, "");
  const tokens = new Set();
  const dictionary = [
    "婴儿床", "襁褓", "新生儿", "双胞胎", "妹妹", "姐姐", "妈妈", "爸爸", "母亲", "父亲", "孩子", "病房", "医院", "诊室", "客厅", "卧室", "餐厅", "厨房", "宴会厅", "宫门", "庭院", "办公室", "教室", "走廊", "长石道", "打分表", "评分表", "表格", "纸张", "签字笔", "手机", "合同", "文件", "照片", "戒指", "药盒", "酒杯", "长剑", "法器", "车辆", "行李", "翻身", "坐", "走", "说话", "哭", "笑", "抬眼", "低头", "回头", "推", "写", "画", "拿", "放", "递", "拨通", "签字", "举手", "起身", "离开", "逼近", "怀孕", "结婚", "上市", "收购", "偏心", "公平", "规则", "比较", "评分"
  ];
  dictionary.forEach((item) => { if (source.includes(item)) tokens.add(item); });
  (state.characters || []).forEach((character) => {
    const name = text(character?.name);
    if (name && source.includes(name)) tokens.add(name);
  });
  return tokens;
}

function promptGroundingScore(promptValue = "", sourceValue = "", contextValue = "") {
  const promptTokens = promptSemanticTokens(promptValue);
  if (!promptTokens.size) return 0;
  const sourceTokens = promptSemanticTokens(`${sourceValue} ${contextValue}`);
  let hits = 0;
  promptTokens.forEach((token) => { if (sourceTokens.has(token)) hits += 1; });
  return hits / Math.max(1, promptTokens.size);
}

function promptVisualActionCount(value = "") {
  return (text(value).match(/走|跑|冲|追|停|坐|站|抬眼|低头|回头|举手|推|递|拿|放|铺开|画出|点下|写下|按住|翻动|抓住|握紧|抱住|扶住|拨通|签下|翻开|拔剑|挥剑|格挡|闪避|施法|亮起|震动|转身|起身|后退|靠近|掀起|落下|打开|关上/g) || []).length;
}

function isUngroundedPrompt(promptValue = "", sourceValue = "", contextValue = "", previousPrompt = "") {
  const prompt = stripInlineCharacterCardDetails(promptValue);
  if (!prompt || prompt.length < 36) return true;
  if (PROMPT_BAD_PHRASES.test(prompt)) return true;
  if (previousPrompt && clauseSimilarity(prompt, previousPrompt) >= 0.72) return true;
  const grounding = promptGroundingScore(prompt, sourceValue, contextValue);
  if (sourceNeedsStoryInterface(sourceValue) && !promptHasRequiredStoryInterface(prompt, sourceValue)) return true;
  const actions = promptVisualActionCount(prompt);
  const evidence = `${text(sourceValue)} ${text(contextValue)} ${(state.characters || []).map((item) => `${text(item?.name)} ${text(item?.role)}`).join(" ")}`;
  const roleTokens = ["护士", "医生", "亲戚", "高管", "秘书", "合伙人", "同学", "老师", "警察", "侍卫", "王侯", "王爷", "将军", "皇帝", "公主", "弟子", "路人", "宾客"];
  const unsupportedRole = roleTokens.some((token) => prompt.includes(token) && !evidence.includes(token));
  if (unsupportedRole) return true;
  const hasConcreteScene = /病房|医院|诊室|客厅|卧室|餐厅|厨房|宴会厅|宫门|庭院|办公室|教室|走廊|街道|长石道|车内|车外|树林|山道|宗门|基地|飞船|战场/.test(prompt);
  const hasKnownCharacter = (state.characters || []).some((character) => text(character?.name) && prompt.includes(text(character.name))) || /妈妈|爸爸|母亲|父亲|孩子|婴儿|女主|男主|医生|护士|同学|高管|侍卫|王侯/.test(prompt);
  return grounding < 0.12 && (!hasConcreteScene || !hasKnownCharacter || actions < 1);
}

function contextualCharacterNames(scene, shot, sourceValue = "") {
  const names = directorSceneCharacters(scene, shot, `${sourceValue} ${text(scene?.source_context)} ${text(scene?.next_context)}`);
  return uniqueTextList(names).slice(0, 4);
}

function manualSceneCharacterNames(scene = {}) {
  return normalizeSceneCharactersMode(scene?.characters_mode) === "manual"
    ? uniqueTextList(scene?.characters || [])
    : [];
}

function requiredCharacterPromptNote(scene = {}) {
  const names = manualSceneCharacterNames(scene);
  if (!names.length) {
    return "本镜人物为自动判断：当前原文仅有环境或道具时允许无人镜头，禁止擅自补入无关人物。";
  }
  return `本镜人物为用户手动锁定：${names.join("、")}。成品画面正文必须逐个出现这些人物名字，并给出与当前原文相符的站位、动作或直接反应；未勾选人物不得加入。`;
}

function parentAndChildNames(names = []) {
  const parents = [];
  const children = [];
  names.forEach((name) => {
    const character = (state.characters || []).find((item) => text(item.name) === text(name));
    if (character && isParentCharacter(character)) parents.push(name);
    else children.push(name);
  });
  return { parents, children };
}

function allSelectedNamesPresent(promptValue = "", names = []) {
  const prompt = text(promptValue);
  return names.every((name) => prompt.includes(name));
}

function groundedEnvironmentDetail(location = "") {
  if (/医院|病房|诊室|产房/.test(location)) return "窗边冷光、床栏、诊桌与门口过道拉出清楚的前中后景";
  if (/客厅|家中|别墅|公寓/.test(location)) return "沙发、茶几、门框与窗边自然光拉出清楚的前中后景";
  if (/餐厅|饭桌|餐桌|宴会厅/.test(location)) return "桌面陈设、椅背与周围人物拉出清楚的前中后景";
  if (/宫门|宫殿|府邸|庭院|古城/.test(location)) return "宫墙、廊柱、石道与随行人物拉出压迫性的纵深透视";
  if (/宗门|秘境|仙山|魔宫/.test(location)) return "雾气、山石、能量微光与远处地形拉出清楚的空间纵深";
  if (/基地|飞船|未来|科技/.test(location)) return "金属结构、设备冷光与远处人影拉出清楚的空间纵深";
  return "门框、地面线条、桌面或周围人影拉出清楚的前中后景";
}

function buildGroundedPromptForSource(sourceValue = "", scene = {}, shot = {}, variant = 0) {
  const source = text(sourceValue) || text(scene?.source_text || scene?.text);
  const context = `${text(scene?.source_context)} ${text(scene?.source_text || scene?.text)} ${text(scene?.next_context)}`;
  const location = directorLocationAnchor(source, context);
  const manualNames = manualSceneCharacterNames(scene);
  let names = manualNames.length ? manualNames : contextualCharacterNames(scene, shot, source);
  if (!manualNames.length && /打分表|评分表|打分规则|评分规则|表格/.test(source)) {
    const parentNames = names.filter((name) => {
      const character = (state.characters || []).find((item) => text(item.name) === text(name));
      return character && isParentCharacter(character);
    });
    if (parentNames.length) names = parentNames;
  }
  const lead = names[0] || "";
  const second = names[1] || "";
  const extras = names.slice(2);
  const environment = groundedEnvironmentDetail(location);
  const object = directorVisualObject(source);
  const interfacePrompt = buildStoryInterfacePrompt(source, scene, shot);
  if (interfacePrompt) return interfacePrompt;

  if (/出生|新生儿|双胞胎|婴儿床|襁褓/.test(source)) {
    const grouped = parentAndChildNames(names);
    const babies = grouped.children.length >= 2 ? `${grouped.children[0]}与${grouped.children[1]}` : grouped.children[0] || "两名新生婴儿";
    const parents = grouped.parents.length >= 2 ? `${grouped.parents[0]}与${grouped.parents[1]}` : grouped.parents[0] || "父母";
    return `${babies}分别躺在并排的透明婴儿床里，浅色襁褓边缘与细小手指随着呼吸轻微起伏→${parents}一左一右俯身查看，窗边冷光、床栏与门口过道拉出清楚前中后景→${grouped.parents[0] || "母亲"}抬眼与${grouped.parents[1] || "父亲"}对视，后者缓慢点头，镜头停在父母达成决定与两名婴儿同框的瞬间`;
  }

  if (/养孩子.*偏心|最怕偏心|公平|端平/.test(source) && names.length) {
    const grouped = parentAndChildNames(names);
    const children = grouped.children.length >= 2 ? `${grouped.children[0]}与${grouped.children[1]}` : grouped.children[0] || "两个孩子";
    const parentA = grouped.parents[0] || lead || "母亲";
    const parentB = grouped.parents[1] || second || "父亲";
    return `${children}并排处于画面两侧，${parentA}先替一侧整理襁褓，又立即伸手检查另一侧的被角→${parentB}把两件同款用品重新摆到对称位置，床栏、窗光与两人的手臂形成平衡构图→两人同时停下动作看向两个孩子，镜头停在刻意维持公平的对称画面上`;
  }

  if (/打分表|评分表|打分规则|评分规则|表格/.test(source)) {
    if (names.length >= 2) {
      return `${lead}把空白表格纸铺在茶几中央，${second}握着黑色签字笔沿直尺边缘划出整齐分栏→笔帽、尺子与两人的手臂在桌面形成清楚前后层次，纸面只保留模糊线条和不可读标记→${lead}伸手指向其中一栏，${second}停笔抬眼确认${extras.length ? `，${extras.join("与")}在画面后景保持可见` : ""}，镜头停在两人同时按住纸角与打分表逐渐成形的位置`;
    }
    return `空白纸张、直尺与黑色签字笔整齐铺在${location}的桌面中央→笔尖沿尺边划出连续分栏，纸面只出现模糊线条和不可读圆点，桌沿与窗光拉出清楚纵深→镜头缓慢推近并停在逐渐成形的打分表上，不出现任何无关人物`;
  }

  if (/马上|即将|就要|快要|赶来|赶到|逼近|现身|到了/.test(source)) {
    const ancient = /王侯|王爷|侯爷|世子|将军|宫门|古代|锦袍|侍卫/.test(`${source} ${context}`);
    const figure = ancient ? "逆光中的高大权贵身影" : lead ? `${lead}的身影` : "远处快速逼近的身影";
    const clothing = ancient ? "玄色锦袍与披风被迎面气流掀起" : "外套下摆随快速步伐向后扬起";
    return `${figure}从${location}的纵深尽头快步逼近，${clothing}→${environment}，道路与两侧人物被长焦压缩成强烈纵深，距离缩短带来的压迫感不断增强→附近人物同时停下动作回头望向来人方向，镜头迅速推近并停在来人即将进入正面近景的位置`;
  }

  if (!names.length && object) {
    return `${object}被置于${location}的画面中心，边缘、材质与当前原文对应的操作痕迹清楚可见→桌沿、门框、光线或地面线条拉出真实前中后景，周围不出现无关人物→镜头沿${object}表面缓慢推近，停在原文要求展示的关键变化或结果上`;
  }

  const action = directorActionClause(source, lead || directorFallbackSubject(source), second || "对面的人");
  const reaction = directorVisibleReaction(source, lead || directorFallbackSubject(source), second || "对面的人");
  const main = action || (object ? `${lead || "画面中的人物"}伸手拿起${object}并将它移到画面中心` : `${lead || "主角"}停下原本动作，抬眼看向${second || "前方"}`);
  const extraNames = extras.length ? `，${extras.join("与")}在画面另一侧作出与原文一致的整体反应` : "";
  const end = reaction || `${second || "对面的人"}的动作随即停住，视线落到${lead || "主体"}身上`;
  return `${main}→${environment}，关键道具、人物站位与动作关系在同一画面中保持清楚${extraNames}→${end}，镜头停在动作结果与直接反应同时成立的位置`;
}

function applySpecializedCarrierTemplates(sceneId = "") {
  let changed = 0;
  state.outlineShots.forEach((shot) => {
    const parentId = text(shot.parent_scene_id) || text((shot.parent_scene_ids || [])[0]);
    if (sceneId && parentId !== sceneId) return;
    const scene = sourceSceneById(parentId);
    const source = text(shot.source_basis) || text(scene?.source_text || scene?.text);
    const branch = detectCarrierTemplateBranch(source);
    if (!branch) return;
    const rewritePrompt = (segmentLike = {}) => {
      if (branch === 'system') return buildSystemTemplatePrompt(source, scene, { ...shot, ...segmentLike });
      if (branch === 'barrage') return buildBarrageTemplatePrompt(source, scene, { ...shot, ...segmentLike });
      if (branch === 'chatui') return buildChatUiTemplatePrompt(source, scene, { ...shot, ...segmentLike });
      if (branch === 'document') return buildDocumentTemplatePrompt(source, scene, { ...shot, ...segmentLike });
      return buildGroundedPromptForSource(source, scene, { ...shot, ...segmentLike }, 0);
    };
    const segments = normalizeTimelineSegments(shot.timeline_segments);
    if (segments.length) {
      let localChanged = false;
      shot.timeline_segments = segments.map((segment) => {
        const nextPrompt = rewritePrompt(segment);
        if (!nextPrompt) return segment;
        if (text(segment.prompt) === nextPrompt) return segment;
        localChanged = true;
        return { ...segment, prompt: nextPrompt };
      });
      if (localChanged) {
        shot.prompt = timelinePrompt(shot.timeline_segments);
        changed += 1;
      }
      return;
    }
    const nextPrompt = rewritePrompt();
    if (nextPrompt && text(shot.prompt) !== nextPrompt) {
      shot.prompt = nextPrompt;
      changed += 1;
    }
  });
  return changed;
}

function applySpecializedSceneTemplates(sceneId = "") {
  let changed = 0;
  state.outlineShots.forEach((shot) => {
    const parentId = text(shot.parent_scene_id) || text((shot.parent_scene_ids || [])[0]);
    if (sceneId && parentId !== sceneId) return;
    const scene = sourceSceneById(parentId);
    const source = text(shot.source_basis) || text(scene?.source_text || scene?.text);
    const branch = detectSceneTemplateBranch(source);
    if (!branch) return;
    const rewritePrompt = (segmentLike = {}) => buildSceneTemplatePrompt(source, scene, { ...shot, ...segmentLike }, branch);
    const segments = normalizeTimelineSegments(shot.timeline_segments);
    if (segments.length) {
      let localChanged = false;
      shot.timeline_segments = segments.map((segment) => {
        const nextPrompt = rewritePrompt(segment);
        if (!nextPrompt) return segment;
        if (text(segment.prompt) === nextPrompt) return segment;
        localChanged = true;
        return { ...segment, prompt: nextPrompt };
      });
      if (localChanged) {
        shot.prompt = timelinePrompt(shot.timeline_segments);
        changed += 1;
      }
      return;
    }
    const nextPrompt = rewritePrompt();
    if (nextPrompt && text(shot.prompt) !== nextPrompt) {
      shot.prompt = nextPrompt;
      changed += 1;
    }
  });
  return changed;
}

function repairMissingStoryInterfaces(sceneId = "") {
  let changed = 0;
  state.outlineShots.forEach((shot) => {
    const parentId = text(shot.parent_scene_id) || text((shot.parent_scene_ids || [])[0]);
    if (sceneId && parentId !== sceneId) return;
    const scene = sourceSceneById(parentId);
    const source = text(shot.source_basis) || text(scene?.source_text || scene?.text);
    if (!sourceNeedsStoryInterface(source)) return;
    const segments = normalizeTimelineSegments(shot.timeline_segments);
    if (segments.length) {
      shot.timeline_segments = segments.map((segment, index) => {
        const prompt = text(segment.prompt);
        if (promptHasRequiredStoryInterface(prompt, source)) return segment;
        changed += 1;
        return { ...segment, prompt: buildStoryInterfacePrompt(source, scene, { ...shot, ...segment }, index) || buildGroundedPromptForSource(source, scene, { ...shot, ...segment }, index) };
      });
      shot.prompt = timelinePrompt(shot.timeline_segments);
      return;
    }
    if (!promptHasRequiredStoryInterface(shot.prompt, source)) {
      shot.prompt = buildStoryInterfacePrompt(source, scene, shot) || buildGroundedPromptForSource(source, scene, shot, 0);
      changed += 1;
    }
  });
  return changed;
}

function ensureManualSceneCharactersInPrompts(sceneId = "") {
  let missingCount = 0;
  state.outlineShots.forEach((shot) => {
    const parentId = text(shot.parent_scene_id) || text((shot.parent_scene_ids || [])[0]);
    if (sceneId && parentId !== sceneId) return;
    const scene = sourceSceneById(parentId);
    const required = manualSceneCharacterNames(scene);
    if (!required.length) return;

    shot.characters = [...required];
    shot.scene_characters = [...required];
    shot.visible_characters = [...required];
    shot.scene_characters_mode = "manual";

    const segments = normalizeTimelineSegments(shot.timeline_segments);
    const promptText = segments.length ? segments.map((segment) => text(segment.prompt)).join(" ") : text(shot.prompt);
    if (!allSelectedNamesPresent(promptText, required)) missingCount += 1;
    if (segments.length) {
      shot.timeline_segments = segments.map((segment) => ({ ...segment, visible_characters: [...required] }));
    }
  });
  // 只校验并记录，不再调用本地模板重写AI生成的画面语义。
  return missingCount;
}

function cleanGeneratedPromptResidue(sceneId = "") {
  let changed = 0;
  state.outlineShots.forEach((shot) => {
    const parentId = text(shot.parent_scene_id) || text((shot.parent_scene_ids || [])[0]);
    if (sceneId && parentId !== sceneId) return;
    const segments = normalizeTimelineSegments(shot.timeline_segments);
    if (segments.length) {
      shot.timeline_segments = segments.map((segment) => {
        const before = text(segment.prompt);
        const after = cleanNewStandardBody(before)
          .replace(new RegExp(STRICT_BAD_SHOT_PHRASES.source, "g"), "")
          .replace(/\s+/g, " ")
          .trim();
        if (after !== before) changed += 1;
        return { ...segment, prompt: after || before };
      });
      shot.prompt = timelinePrompt(shot.timeline_segments);
    } else {
      const before = text(shot.prompt);
      const after = cleanNewStandardBody(before)
        .replace(new RegExp(STRICT_BAD_SHOT_PHRASES.source, "g"), "")
        .replace(/\s+/g, " ")
        .trim();
      if (after && after !== before) {
        shot.prompt = after;
        changed += 1;
      }
    }
  });
  return changed;
}

function repairUngroundedAndDuplicatePrompts(sceneId = "") {
  let changed = 0;
  state.outlineShots.forEach((shot) => {
    const parentId = text(shot.parent_scene_id) || text((shot.parent_scene_ids || [])[0]);
    if (sceneId && parentId !== sceneId) return;
    const scene = sourceSceneById(parentId);
    const context = `${text(scene?.source_context)} ${text(scene?.source_text || scene?.text)} ${text(scene?.next_context)}`;
    const segments = normalizeTimelineSegments(shot.timeline_segments);
    if (segments.length) {
      let previousPrompt = "";
      shot.timeline_segments = segments.map((segment, index) => {
        const source = text(segment.source_basis) || text(shot.source_basis) || text(scene?.source_text || scene?.text);
        const cleaned = stripInlineCharacterCardDetails(segment.prompt);
        const bad = isUngroundedPrompt(cleaned, source, context, previousPrompt);
        const nextPrompt = bad ? buildGroundedPromptForSource(source, scene, { ...shot, ...segment }, index) : cleaned;
        if (nextPrompt !== text(segment.prompt)) changed += 1;
        previousPrompt = nextPrompt;
        return { ...segment, prompt: nextPrompt };
      });
      shot.prompt = timelinePrompt(shot.timeline_segments);
      return;
    }
    const source = text(shot.source_basis) || text(scene?.source_text || scene?.text);
    const cleaned = stripInlineCharacterCardDetails(shot.prompt);
    const nextPrompt = isUngroundedPrompt(cleaned, source, context, "")
      ? buildGroundedPromptForSource(source, scene, shot, 0)
      : cleaned;
    if (nextPrompt !== text(shot.prompt)) changed += 1;
    shot.prompt = nextPrompt;
  });
  if (changed) sortOutlineShots();
  return changed;
}

