  if (Array.isArray(data.characters)) {
    state.characters = buildAnalysisCharacterCards(data.characters, novelText);
    repairCharacterAgeStages(novelText, { force: true });
    state.characters = buildAnalysisCharacterCards(state.characters, novelText);
    enforceCharacterGuideInvariant(novelText);
  }
