function sourceContentEventsV78302(sourceText = "") {
  const source = text(sourceText);
  if (!source) return [];
  const events = [];
  let seq = 0;
  const quoteMatches = [...source.matchAll(/[“"]([^”"]+)[”"]/g)];
  quoteMatches.forEach((match) => {
    const quote = text(match?.[1]);
    if (!quote) return;
    seq += 1;
    events.push({ id: `dialogue_${seq}`, type: "dialogue", text: quote, source_index: Number(match.index || 0) });
  });
  const withoutQuotes = source.replace(/[“"][^”"]+[”"]/g, " ");
  withoutQuotes.split(/[。！？!?；;]+/).map((item) => text(item)).filter((item) => item.length >= 2).forEach((clause) => {
    seq += 1;
    const type = /(?:看|望|愣|笑|哭|皱|抿|低头|抬眼|僵|沉默|反应)/.test(clause) ? "reaction"
      : /(?:拿|递|推|拉|走|跑|冲|转身|起身|坐|站|打开|关上|扔|放|拍|抱|抓|扶|跪)/.test(clause) ? "action"
        : /(?:手机|文件|合同|照片|戒指|钥匙|杯|门|屏幕|道具)/.test(clause) ? "prop" : "fact";
    events.push({ id: `${type}_${seq}`, type, text: clause.slice(0, 240), source_index: source.indexOf(clause) });
  });
  return events.sort((a, b) => a.source_index - b.source_index || a.id.localeCompare(b.id));
}

function applyContentEventOwnershipV78302(shot = {}, scene = {}) {
  const segments = normalizeTimelineSegments(shot.timeline_segments);
  if (!segments.length) return shot;
  const sourceText = scene.source_text || scene.text || shot.source_basis;
  const events = sourceContentEventsV78302(sourceText);
  const assignments = new Map(segments.map((_, index) => [index, []]));
  const dialogueAllowed = extractQuotedSourceCounts(sourceText);
  const dialogueSeen = new Map();

  const claimDialogue = (quoteRaw, index) => {
    const quoteKey = normalizeDialogueValidationText(quoteRaw);
    if (!quoteKey) return { keep: true, eventId: "" };
    const seen = dialogueSeen.get(quoteKey) || 0;
    const allowed = dialogueAllowed.get(quoteKey) || 1;
    if (seen >= allowed) return { keep: false, eventId: "" };
    const matching = events.find((event) => event.type === "dialogue"
      && normalizeDialogueValidationText(event.text) === quoteKey
      && event.owner_segment_index === undefined);
    const eventId = matching?.id || `dialogue_owner_${quoteKey.slice(0, 24)}_${seen + 1}`;
    if (matching) matching.owner_segment_index = index;
    dialogueSeen.set(quoteKey, seen + 1);
    assignments.get(index).push(eventId);
    return { keep: true, eventId };
  };

  segments.forEach((segment, index) => {
    let hadOwnershipConflict = false;
    if (text(segment.speech_text)) {
      const claim = claimDialogue(segment.speech_text, index);
      if (!claim.keep) {
        // 事件所有权层修正：非法的第二个 owner 失去“说这句话”的事件资格，
        // 但该时段自己的反应/动作画面正文完整保留，不在最终文本阶段做字符串去重。
        segment.speech_mode = "none";
        segment.speaker = "";
        segment.speech_text = "";
        hadOwnershipConflict = true;
      }
    }
    if (Array.isArray(segment.dialogue_lines) && segment.dialogue_lines.length) {
      const kept = [];
      segment.dialogue_lines.forEach((line) => {
        const parsed = parseDialogueValidationLine(line);
        if (!parsed?.quote) { kept.push(line); return; }
        const claim = claimDialogue(parsed.quote, index);
        if (claim.keep) kept.push(line);
        else hadOwnershipConflict = true;
      });
      segment.dialogue_lines = kept;
    }
    if (hadOwnershipConflict) segment.content_event_conflict_v78302 = "duplicate_dialogue_owner_removed";
  });

  const nonDialogue = events.filter((event) => event.type !== "dialogue");
  nonDialogue.forEach((event, eventIndex) => {
    const target = Math.min(segments.length - 1, Math.floor(eventIndex * segments.length / Math.max(1, nonDialogue.length)));
    event.owner_segment_index = target;
    assignments.get(target).push(event.id);
  });
  const nextSegments = segments.map((segment, index) => ({
    ...segment,
    content_event_ids_v78302: uniqueTextList(assignments.get(index) || []),
    content_event_owner_v78302: true,
  }));
  shot.content_events_v78302 = events;
  shot.timeline_segments = nextSegments;
  shot.prompt = timelinePrompt(nextSegments);
  return shot;
}

function sceneContextFromCardV78302(scene = {}, previousContext = "") {
  const shots = (state.outlineShots || []).filter((shot) => {
    const ids = uniqueTextList([shot.parent_scene_id, ...(shot.parent_scene_ids || [])]);
    return ids.includes(text(scene.id));
  });
  const direct = text(scene.visual_context)
    || text(shots.find((shot) => text(shot.visual_context))?.visual_context)
    || text(shots.flatMap((shot) => normalizeTimelineSegments(shot.timeline_segments)).find((segment) => text(segment.visual_context))?.visual_context)
    || text(scene.scene_memory?.last_visual_context)
    || text(scene.scene_memory?.location_hint);
  return normalizeConcreteSceneContext(direct, scene.source_text || scene.text, previousContext, shots[0]?.prompt || "")
    || inferSceneContextFromSourceLine(scene.source_text || scene.text, previousContext)
    || text(previousContext);
}

function ensureSceneCardAnchorsV78302(reason = "scene_anchor_sync") {
  const orderedScenes = [...(state.scenes || [])].sort((a, b) => Number(a.source_index || 0) - Number(b.source_index || 0));
  let previousContext = "";
  let previousAnchor = "";
  orderedScenes.forEach((scene, index) => {
    const anchorId = text(scene.scene_anchor_id || scene.temporary_scene_group) || previousAnchor || `scene_anchor_${index + 1}`;
    let context = sceneContextFromCardV78302(scene, previousContext);
    if (!context && previousContext) context = previousContext;
    scene.scene_anchor_id = anchorId;
    scene.scene_visual_context_v78302 = context;
    scene.scene_context_source_v78302 = text(scene.visual_context) ? "current_card" : (previousContext && context === previousContext ? "inherited" : "resolved");
    if (context) scene.visual_context = context;
    (state.outlineShots || []).forEach((shot) => {
      const ids = uniqueTextList([shot.parent_scene_id, ...(shot.parent_scene_ids || [])]);
      if (!ids.includes(text(scene.id))) return;
      shot.scene_anchor_id = anchorId;
      if (context) shot.visual_context = context;
      if (Array.isArray(shot.timeline_segments) && shot.timeline_segments.length) {
        const promptRevision = Math.max(0, Number.parseInt(shot.prompt_edit_revision, 10) || 0);
        const timelineRevision = Math.max(0, Number.parseInt(shot.timeline_edit_revision, 10) || 0);
        const preserveInvalidManualText = Boolean(text(shot.timeline_validation_error)) || promptRevision > timelineRevision;
        if (!preserveInvalidManualText) {
          shot.timeline_segments = normalizeTimelineSegments(shot.timeline_segments).map((segment) => ({
            ...segment,
            visual_context: context || text(segment.visual_context),
            prompt: canonicalScenePromptBody(segment.prompt, context || segment.visual_context).body,
            scene_anchor_id: anchorId,
          }));
          applyContentEventOwnershipV78302(shot, scene);
        }
      }
    });
    if (context) previousContext = context;
    previousAnchor = anchorId;
  });
  state.sceneAnchorSyncV78302 = { reason, at: new Date().toISOString(), scene_count: orderedScenes.length };
  return orderedScenes;
}

function rebuildCanonicalOutlineTimelineV78302(reason = "canonical_timeline") {
  if (!Array.isArray(state.outlineShots) || !state.outlineShots.length) return { changed: false, total_seconds: 0, reason };
  sortOutlineShots();
  let cursor = 0;
  let changed = false;
  state.outlineShots.forEach((shot) => {
    ensureEditableTimelineCurrent(shot, `canonical:${reason}`);
    const promptRevision = Math.max(0, Number.parseInt(shot.prompt_edit_revision, 10) || 0);
    const timelineRevision = Math.max(0, Number.parseInt(shot.timeline_edit_revision, 10) || 0);
    const preserveInvalidManualText = Boolean(text(shot.timeline_validation_error)) || promptRevision > timelineRevision;
    const segments = normalizeTimelineSegments(shot.timeline_segments);
    if (segments.length) {
      const duration = Math.max(1, Number(segments[segments.length - 1].end_offset || 1));
      shot.duration = duration;
      if (!preserveInvalidManualText) {
        shot.timeline_segments = segments;
        shot.prompt = timelinePrompt(segments);
      }
    } else {
      shot.duration = Math.max(1, Number.parseInt(shot.duration, 10) || Number(shot.end_second) - Number(shot.start_second) || 1);
    }
    const nextStart = cursor;
    const nextEnd = cursor + shot.duration;
    if (Number(shot.start_second) !== nextStart || Number(shot.end_second) !== nextEnd) changed = true;
    shot.start_second = nextStart;
    shot.end_second = nextEnd;
    cursor = nextEnd;
  });
  state.outputs = state.outlineShots;
  state.canonicalTimelineV78302 = { version: "v78.3.0.3", reason, total_seconds: cursor, changed, at: new Date().toISOString() };
  return { changed, total_seconds: cursor, reason };
}

globalThis.__V78_SCENE_EVENT_TIMELINE_V78302__ = Object.freeze({
  version: "v78.3.0.3",
  ensureSceneCards: ensureSceneCardAnchorsV78302,
  rebuildTimeline: rebuildCanonicalOutlineTimelineV78302,
  sourceEvents: sourceContentEventsV78302,
});


function autoSceneCharacterPool(scene = {}, index = -1, validNames = new Set()) {
  const promptText = outlineShotsByScene(scene.id).map((shot) => formatShotLine(shot)).join("\n");
  const inferred = inferSceneCharacterNames(scene, index).filter((name) => validNames.has(name));
  const guidanceSource = text(scene?.guidance);
  const guidanceNames = uniqueTextList([
    ...characterNamesMentioned(guidanceSource),
    ...roleMatchedCharacterNames(guidanceSource),
    ...explicitGuidanceCharacterRequirements(guidanceSource),
  ]).filter((name) => validNames.has(name));
  const actualVisible = sceneCharacterUnion(scene.id).filter((name) => validNames.has(name) && promptText.includes(name));
  return uniqueTextList([...inferred, ...guidanceNames, ...actualVisible]).slice(0, 8);
}

function repairSceneContinuityAndCharacters(targetSceneId = "") {
  const validNames = new Set((state.characters || []).map((character) => text(character.name)).filter(Boolean));
  state.scenes = state.scenes.map((scene, index) => {
    const previous = index > 0 ? state.scenes[index - 1] : null;
    const next = index < state.scenes.length - 1 ? state.scenes[index + 1] : null;
    const sourceContext = text(previous?.source_text || previous?.text).slice(-800);
    const nextContext = text(next?.source_text || next?.text).slice(0, 800);
    const mode = normalizeSceneCharactersMode(scene.characters_mode);
    const current = uniqueTextList(scene.characters).filter((name) => validNames.has(name));
    const inferred = autoSceneCharacterPool({ ...scene, source_context: sourceContext, next_context: nextContext }, index, validNames);
    const currentPruned = current.filter((name) => inferred.includes(name));
    const characters = mode === "manual"
      ? current
      : scene.characters_authoritative === true
        ? current
        : uniqueTextList([...(currentPruned.length ? currentPruned : []), ...inferred]).slice(0, 8);
    return {
      ...scene,
      source_context: sourceContext,
      next_context: nextContext,
      characters,
      character_inference_note: mode === "manual" || !inferred.length ? "" : "已按当前原文、当前画面与补充建议共同校正本镜人物",
    };
  });

  state.outlineShots = state.outlineShots.map((shot) => {
    const parentId = text(shot.parent_scene_id) || text((shot.parent_scene_ids || [])[0]);
    if (targetSceneId && parentId !== targetSceneId) return shot;
    const scene = sourceSceneById(parentId);
    if (!scene) return shot;
    const required = uniqueTextList(scene.characters).filter((name) => validNames.has(name));
    const currentVisible = uniqueTextList(shot.visible_characters).filter((name) => validNames.has(name));
    const currentCharacters = uniqueTextList(shot.characters).filter((name) => validNames.has(name));
    return {
      ...shot,
      characters: currentCharacters.length ? uniqueTextList([...currentCharacters, ...required]) : [...required],
      scene_characters: [...required],
      visible_characters: currentVisible.length ? uniqueTextList([...currentVisible, ...required]) : [...required],
      scene_characters_mode: normalizeSceneCharactersMode(scene.characters_mode),
    };
  });
}

function outlineShotsByScene(sceneId) {
  return state.outlineShots.filter((shot) => (shot.parent_scene_ids || []).includes(sceneId) || shot.parent_scene_id === sceneId);
}

function sceneCharacterUnion(sceneId) {
  const hits = [];
  outlineShotsByScene(sceneId).forEach((shot) => {
    uniqueTextList(shot.characters).forEach((name) => {
      if (!hits.includes(name)) hits.push(name);
    });
  });
  return hits;
}

function syncSceneCharacterState() {
  const validNames = new Set(state.characters.map((character) => character.name).filter(Boolean));
  state.scenes = state.scenes.map((scene, index) => {
    const mode = normalizeSceneCharactersMode(scene.characters_mode);
    const currentCharacters = uniqueTextList(scene.characters).filter((name) => validNames.has(name));
    const autoCharacters = autoSceneCharacterPool(scene, index, validNames);
    const prunedCurrent = currentCharacters.filter((name) => autoCharacters.includes(name));
    return {
      ...scene,
      characters_mode: mode,
      characters: mode === "manual"
        ? currentCharacters
        : scene.characters_authoritative === true
          ? prunedCurrent
          : uniqueTextList([...(prunedCurrent.length ? prunedCurrent : []), ...autoCharacters]).slice(0, 8),
      outline_shot_ids: outlineShotsByScene(scene.id).map((shot) => shot.id),
    };
  });
}

function syncSceneCharactersToOutlineShots(sceneId) {
  const scene = sourceSceneById(sceneId);
  if (!scene) return;
  const validNames = new Set(state.characters.map((character) => character.name).filter(Boolean));
  const sceneCharacters = uniqueTextList(scene.characters).filter((name) => validNames.has(name));
  const sceneCharactersMode = normalizeSceneCharactersMode(scene.characters_mode);
  state.outlineShots = state.outlineShots.map((shot) => {
    const parentIds = Array.isArray(shot.parent_scene_ids) ? shot.parent_scene_ids : [];
    if (!parentIds.includes(sceneId) && shot.parent_scene_id !== sceneId) return shot;
    return {
      ...shot,
      scene_characters: sceneCharacters,
      scene_characters_mode: sceneCharactersMode,
      characters: sceneCharactersMode === "manual" ? [...sceneCharacters] : uniqueTextList([...(shot.characters || []), ...sceneCharacters]),
      visible_characters: sceneCharactersMode === "manual" ? [...sceneCharacters] : uniqueTextList([...(shot.visible_characters || []), ...sceneCharacters]),
    };
  });
}

function syncAllSceneCharactersToOutlineShots() {
  state.scenes.forEach((scene) => syncSceneCharactersToOutlineShots(scene.id));
}

function angleLabel(angle) {
  const value = text(angle);
  if (!value || value === "平视") return "";
  if (value.endsWith("镜头") || value === "主观视角" || value === "肩背镜头") return value;
  return `${value}镜头`;
}

function inferShotSizeFromPrompt(prompt) {
  const value = text(prompt);
  const terms = ["全景", "远景", "中远景", "中景", "中近景", "近景", "特写", "大特写", "局部特写"];
  const hits = terms
    .slice()
    .sort((a, b) => b.length - a.length)
    .map((term) => ({ term, index: value.indexOf(term) }))
    .filter(({ index }) => index >= 0)
    .sort((a, b) => a.index - b.index)
    .map(({ term }) => term)
    .filter((term, index, arr) => arr.indexOf(term) === index);
  return hits.join("、");
}

function inferShotAngleFromPrompt(prompt) {
  const value = text(prompt);
  const terms = ["俯拍", "仰拍", "顶视", "低机位", "高机位", "侧拍", "斜侧拍", "背拍", "肩背镜头", "主观视角"];
  return terms.find((term) => value.includes(term)) || "";
}

function inferMovementFromPrompt(prompt) {
  const value = text(prompt);
  const terms = ["推近", "推进", "推镜", "拉镜", "摇镜", "移镜", "跟拍", "环绕", "手持", "变焦", "升降", "前移", "后撤", "轻推", "缓慢前移"];
  const hits = terms
    .slice()
    .sort((a, b) => b.length - a.length)
    .map((term) => ({ term, index: value.indexOf(term) }))
    .filter(({ index }) => index >= 0)
    .sort((a, b) => a.index - b.index)
    .map(({ term }) => term)
    .filter((term, index, arr) => arr.indexOf(term) === index);
  if (hits.length) return hits.join("、");
  return "";
}

function cameraOnlySegment(segment, shot) {
  const value = text(segment).replace(/^[，,、；;。 ]+|[，,、；;。 ]+$/g, "");
  if (!value) return true;
  const shotSize = text(shot.shot_size) || inferShotSizeFromPrompt(shot.prompt);
  const shotAngle = text(shot.shot_angle) || inferShotAngleFromPrompt(shot.prompt);
  const movement = text(shot.movement) || inferMovementFromPrompt(shot.prompt);
  const meta = new Set([
    shotSize,
    shotAngle,
    movement,
    angleLabel(shotAngle),
    "全景",
    "远景",
    "中远景",
    "中景",
    "中近景",
    "近景",
    "特写",
    "大特写",
    "局部特写",
    "俯拍",
    "仰拍",
    "顶视",
    "低机位",
    "高机位",
    "侧拍",
    "斜侧拍",
    "背拍",
    "肩背镜头",
    "主观视角",
    "推镜",
    "拉镜",
    "摇镜",
    "移镜",
    "跟拍",
    "环绕",
    "手持",
    "变焦",
    "升降",
    "硬切",
    "推近",
    "推进",
    "前移",
    "后撤",
    "快速切换",
    "静止定镜",
    "轻推",
    "缓慢前移",
  ].filter(Boolean));
  if (meta.has(value)) return true;
  if (value.endsWith("镜头") && meta.has(value.replace(/镜头$/, ""))) return true;
  return false;
}

function stripPromptCameraMeta(prompt, shot) {
  const value = text(prompt);
  if (!value) return "";
  const parts = value
    .split(/[，,、；;]+/)
    .map((part) => text(part).replace(/^[，,、；;。 ]+|[，,、；;。 ]+$/g, ""))
    .filter(Boolean);
  const cleaned = parts.filter((part) => !cameraOnlySegment(part, shot));
  const unique = [];
  cleaned.forEach((part) => {
    if (!unique.includes(part)) unique.push(part);
  });
  return text(unique.join("，")) || value;
}

function cameraLead(shot) {
  const shotSize = text(shot.shot_size) || inferShotSizeFromPrompt(shot.prompt);
  const shotAngle = text(shot.shot_angle) || inferShotAngleFromPrompt(shot.prompt);
  const movement = text(shot.movement) || inferMovementFromPrompt(shot.prompt);
  const angle = angleLabel(shotAngle);
  const parts = [];
  if (angle && ["中景", "中近景", "近景", "中远景"].includes(shotSize) && (!movement || movement === "静止定镜")) {
    parts.push(angle);
  } else if (shotSize) {
    parts.push(shotSize);
    if (angle && ["全景", "远景", "特写", "大特写", "局部特写"].includes(shotSize)) {
      parts.push(angle);
    }
  } else if (angle) {
    parts.push(angle);
  }
  if (movement && movement !== "静止定镜" && !parts.includes(movement) && parts.length < 2) {
    parts.push(movement);
  }
  if (!parts.length && angle) parts.push(angle);
  return parts.join("，");
}

function classifyShotPromptMode(shot) {
  const value = text(shot?.prompt);
  if (!value) return "regular";
  const hasScreen = SCREEN_INFO_TOKENS.some((token) => value.includes(token));
  const hasOverlay = OVERLAY_INFO_TOKENS.some((token) => value.includes(token));
  const hasPortrait = SCREEN_FACE_BODY_TOKENS.some((token) => value.includes(token));
  if (hasOverlay && !hasPortrait) return "overlay_info";
  if (hasScreen && !hasPortrait) return "screen_info";
  if (hasScreen && hasPortrait) return "screen_lit_portrait";
  return "regular";
}

function sanitizeScreenInfoPrompt(prompt) {
  const value = text(prompt);
  if (!value) return "";
  const quotedMatches = Array.from(value.matchAll(/[【\[]([^】\]]{1,120})[】\]]|[“"'‘]([^”"'’]{1,120})[”"'’]/g));
  let message = text((quotedMatches[0] || [])[1] || (quotedMatches[0] || [])[2]);
  if (!message) {
    const match = value.match(/(?:显示|弹出|出现|界面内容为|界面显示|内容为|如下)[：: ]?(.+)$/);
    if (match) message = text(match[1]).replace(/[【】\[\]“”"'‘’]/g, "");
  }
  if (!message) {
    message = value
      .replace(/[【】\[\]“”"'‘’]/g, "")
      .replace(/(?:特写|大特写|近景|中景|全景|远景|俯拍|仰拍|平视|主观视角|硬切|推进|推近|推镜|跟拍|移镜|摇镜|拉镜|环绕|升降|静止定镜)/g, "")
      .replace(/(?:手机|屏幕)?(?:聊天界面|聊天记录|聊天消息|微信聊天界面|微信好友申请界面|通知界面|通知页|短信界面|短信页|申请页|支付页|转账页|来电界面)(?:特写)?/g, "")
      .replace(/(?:弹出新消息|弹出消息|文字逐字显现|背景干净|界面清晰可见|按钮与界面信息清晰可见)/g, "");
  }
  message = message.replace(/\s{2,}/g, " ").replace(/^[，。；;：:\s]+|[，。；;：:\s]+$/g, "").slice(0, 100);
  const prefix = value.includes("好友申请") || value.includes("申请页")
    ? "手机微信好友申请界面显示"
    : value.includes("通知")
      ? "手机通知界面显示"
      : value.includes("短信")
        ? "手机短信界面显示"
        : value.includes("转账") || value.includes("支付")
          ? "手机支付界面显示"
          : value.includes("来电")
            ? "手机来电界面显示"
            : "手机聊天界面显示";
  if (message) return `${prefix}：${message}`;
  return prefix;
}

function overlayInfoSubject(value) {
  const raw = text(value);
  if (raw.includes("第一排金色弹幕")) return "第一排金色弹幕";
  if (raw.includes("第二排金色弹幕")) return "第二排金色弹幕";
  if (raw.includes("金色弹幕")) return "金色弹幕";
  if (raw.includes("置顶评论")) return "置顶评论";
  if (raw.includes("评论区")) return "评论区";
  if (raw.includes("评论")) return "评论";
  if (raw.includes("提示条")) return "提示条";
  if (raw.includes("提示信息")) return "提示信息";
  return "弹幕";
}

function overlayInfoPrefix(value) {
  const subject = overlayInfoSubject(value);
  if (subject.includes("评论")) return "评论内容为";
  if (subject.includes("提示")) return "提示信息为";
  return "弹幕的内容为";
}

function overlayInfoLead(value) {
  const raw = text(value);
  const subject = overlayInfoSubject(raw);
  if (["掠过", "划过", "刷过"].some((token) => raw.includes(token))) {
    if (raw.includes("快速") || raw.includes("迅速")) return `${subject}快速划过`;
    if (raw.includes("掠过")) return `${subject}掠过`;
    return `${subject}划过`;
  }
  if (raw.includes("弹出")) return `${subject}弹出`;
  if (raw.includes("出现")) return `${subject}出现`;
  if (subject.includes("评论")) return `${subject}刷过`;
  return `${subject}出现`;
}

function cleanOverlayInfoMessage(value, limit = 120) {
  let raw = text(value);
  if (!raw) return "";
  raw = raw
    .replace(/[【】\[\]“”"'‘’]/g, "")
    .replace(/^(?:弹幕的内容为|弹幕内容为|评论内容为|提示信息为|评论为|提示为)[，,：: ]*/g, "")
    .replace(/(?:文字逐字显现|背景干净|界面清晰可见|按钮与界面信息清晰可见)/g, "")
    .replace(/\s{2,}/g, " ")
    .replace(/^[，；;：:\s]+|[，；;：:\s]+$/g, "");
  if (!raw) return "";
  const sentenceChunks = raw.split(/(?<=[。！？!?])/).map((part) => text(part)).filter(Boolean);
  if (sentenceChunks.length) raw = sentenceChunks.slice(0, 2).join("").trim();
  return raw.slice(0, limit).replace(/^[，；;：:\s]+|[，；;：:\s]+$/g, "");
}

function looksLikeGenericOverlayInfoMessage(value) {
  const raw = text(value);
  if (!raw) return true;
  if (OVERLAY_INFO_GENERIC_MESSAGE_TOKENS.includes(raw)) return true;
  if (["弹幕的内容为", "评论内容为", "提示信息为"].includes(raw)) return true;
  const hitCount = OVERLAY_INFO_GENERIC_MESSAGE_TOKENS.filter((token) => raw.includes(token)).length;
  if (hitCount >= 2 && raw.length <= 30) return true;
  return false;
}

function extractFollowingOverlaySentences(value) {
  const sentences = text(value).split(/(?<=[。！？!?])/).map((part) => text(part)).filter(Boolean);
  for (let index = 0; index < sentences.length; index += 1) {
    const sentence = sentences[index];
    if (!OVERLAY_INFO_TOKENS.some((token) => sentence.includes(token))) continue;
    const direct = sentence.match(/(?:弹幕|评论区|评论|提示条|提示信息)[^：:]{0,12}[：:](.+)$/);
    if (direct) {
      const candidate = cleanOverlayInfoMessage(direct[1]);
      if (candidate && !looksLikeGenericOverlayInfoMessage(candidate)) return candidate;
    }
    const trailing = [];
    for (const follow of sentences.slice(index + 1, index + 3)) {
      const cleaned = cleanOverlayInfoMessage(follow);
      if (!cleaned) continue;
      trailing.push(cleaned);
      if (trailing.join("").length >= 90) break;
    }
    const candidate = trailing.join("").trim().slice(0, 120);
    if (candidate && !looksLikeGenericOverlayInfoMessage(candidate)) return candidate;
  }
  return "";
}

function extractOverlayInfoMessageFromSources(...values) {
  const candidates = [];
  values.forEach((raw) => {
    const value = text(raw);
    if (!value) return;
    if (!OVERLAY_INFO_TOKENS.some((token) => value.includes(token))) return;
    const bracketMatches = Array.from(value.matchAll(/[【\[]([^】\]]{4,220})[】\]]/g));
    bracketMatches.forEach((match) => candidates.push(cleanOverlayInfoMessage(match[1])));
    const quoteMatches = Array.from(value.matchAll(/[“"'‘]([^”"'’]{4,220})[”"'’]/g));
    quoteMatches.forEach((match) => candidates.push(cleanOverlayInfoMessage(match[1])));
    const direct = value.match(/(?:弹幕的内容为|弹幕内容为|评论内容为|提示信息为|评论为|提示为)[：: ]?(.+)$/);
    if (direct) candidates.push(cleanOverlayInfoMessage(direct[1]));
    candidates.push(extractFollowingOverlaySentences(value));
  });
  return candidates.find((candidate) => candidate && !looksLikeGenericOverlayInfoMessage(candidate)) || "";
}

function sanitizeOverlayInfoPrompt(prompt) {
  const value = text(prompt);
  if (!value) return "";
  const quotedMatches = Array.from(value.matchAll(/[【\[]([^】\]]{1,160})[】\]]|[“"'‘]([^”"'’]{1,160})[”"'’]/g));
  let message = cleanOverlayInfoMessage(text((quotedMatches[0] || [])[1] || (quotedMatches[0] || [])[2]));
  if (!message) {
    const match = value.match(/(?:弹幕的内容为|弹幕内容为|评论内容为|提示信息为|评论为|提示为)[：: ]?(.+)$/);
    if (match) message = cleanOverlayInfoMessage(match[1]);
  }
  const lead = overlayInfoLead(value);
  if (message && !looksLikeGenericOverlayInfoMessage(message)) {
    return `${lead}，${overlayInfoPrefix(value)}：【${message}】`;
  }
  return lead;
}

function repairOverlayInfoPrompt(prompt, ...contextValues) {
  const value = sanitizeOverlayInfoPrompt(prompt);
  let message = "";
  if (value.includes("：【") && value.endsWith("】")) {
    message = text(value.split("：【", 2)[1].slice(0, -1));
  }
  if (message && !looksLikeGenericOverlayInfoMessage(message)) return value;
  const recovered = extractOverlayInfoMessageFromSources(prompt, ...contextValues);
  if (!recovered) {
    return value
      .replace("，弹幕的内容为：", "")
      .replace("，评论内容为：", "")
      .replace("，提示信息为：", "")
      .replace(/^[，\s]+|[，\s]+$/g, "");
  }
  const prefixSource = [prompt, ...contextValues].map((item) => text(item)).filter(Boolean).join(" ");
  return `${overlayInfoLead(prefixSource)}，${overlayInfoPrefix(prefixSource)}：【${recovered}】`;
}

function graphicOverlayDescription(overlay) {
  if (!overlay || typeof overlay !== "object") return "";
  const label = text(overlay.text);
  if (!label) return "";
  if (overlay.type === "character_tag") return `画面左上方悬浮竖排书法人物介绍字条：${label}`;
  if (overlay.type === "document_tag") return "";
  if (overlay.type === "barrage_tag") return `画面上方掠过金色弹幕字条：${label}`;
  return `画面内简洁图形字条：${label}`;
}

function stripAutomaticDocumentTitle(value) {
  return text(value)
    .replace(/[，,；;]?文件边缘叠加简洁标题字条[：:][^，,；;。]*/g, "")
    .replace(/^[，,；;\s]+|[，,；;\s]+$/g, "");
}

function lipSyncDescription(_shot) {
  // 对白只通过结构化 speaker / speech_text 输出；禁止生成机械口型模板句。
  return "";
}

function sanitizeScreenInfoVisualContext(value) {
  const segments = text(value)
    .split(/[；;]+/)
    .map((part) => text(part))
    .filter(Boolean);
  const kept = [];
  segments.forEach((segment) => {
    if (SCREEN_INFO_STYLE_TOKENS.some((token) => segment.includes(token))) return;
    if (SCREEN_INFO_GENERIC_CONTEXT_TOKENS.includes(segment)) return;
    if (["背景材质保持连续", "当前主要场景", "中性实景光", "实景灯保持统一", "方向统一", "层次清楚"].some((token) => segment.includes(token))) return;
    if (!SCREEN_INFO_FACTUAL_CONTEXT_TOKENS.some((token) => segment.includes(token))) return;
    if (!kept.includes(segment)) kept.push(segment);
  });
  return kept.slice(0, 3).join("；");
}

function sanitizeOverlayInfoVisualContext(value) {
  return sanitizeScreenInfoVisualContext(value);
}

function compactVisualContext(value) {
  const parts = text(value)
    .split(/[；;，,]/)
    .map((part) => text(part))
    .filter(Boolean)
    .filter((part) => !SCREEN_INFO_GENERIC_CONTEXT_TOKENS.some((token) => part === token || part.includes(token)))
    .filter((part) => !["方向统一", "层次清楚", "背景保持连续", "环境保持连续"].some((token) => part.includes(token)));
  const unique = [...new Set(parts)];
  const hasDay = unique.some((part) => /白天|日间|昼/.test(part));
  const hasNight = unique.some((part) => /夜晚|夜间|深夜|傍晚/.test(part));
  const hasSunny = unique.some((part) => /晴天|晴朗/.test(part));
  const anchors = unique.filter((part) => !/^(白天|日间|昼间|夜晚|夜间|深夜|傍晚|晴天|晴朗)$/.test(part));
  const anchor = anchors.join("，");
  const timePhrase = hasNight ? "夜间的" : hasDay && hasSunny ? "晴朗白昼的" : hasDay ? "白昼的" : hasSunny ? "晴朗的" : "";
  return `${timePhrase}${anchor}`.replace(/的的/g, "的").replace(/[，,；;]+$/g, "").slice(0, 240);
}

function formatShotLine(shot) {
  if (Array.isArray(shot?.timeline_segments) && shot.timeline_segments.length) return timelinePrompt(shot.timeline_segments);
  const meta = cameraTagFromSegment(shot);
  const rawBody = stripAutomaticDocumentTitle(stripPromptCameraMeta(shot.prompt, shot));
  const parts = splitScenePromptParts(rawBody, shot.visual_context);
  const dedupedBody = stripDialogueTextFromPromptBody(parts.body, shot);
  const mainBody = mergeSceneIntoPromptBody(parts.scene, dedupedBody || "人物开口后的可见反应与当前动作状态清楚呈现");
  const mainLine = `${formatClock(shot.start_second)}-${formatClock(shot.end_second)} | ${meta} | ${mainBody}`;
  const dialogue = dialogueLinesFromSegment(shot);
  return dialogue ? `${mainLine}\n${dialogue}` : mainLine;
}


function shotMetaText(shot) {
  return cameraTagFromSegment(shot) || "按当前镜头内容判断";
}



function characterAliasLabel(index) {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  if (index < alphabet.length) return alphabet[index];
  const head = alphabet[index % alphabet.length];
  const round = Math.floor(index / alphabet.length) + 1;
  return `${head}${round}`;
}

function buildCharacterAliasEntries() {
  const available = (state.characters || []).filter((item) => text(item?.name) && (text(item?.appearance) || text(item?.role)));
  return available.map((character, index) => {
    const alias = characterAliasLabel(index);
    const names = new Set([text(character.name), alias, `${text(character.name)}${alias}`]);
    (Array.isArray(character.aliases) ? character.aliases : []).forEach((item) => names.add(text(item)));
    return {
      alias,
      name: text(character.name),
      names: [...names].filter(Boolean),
      role: text(character.role),
      appearance: text(character.appearance),
    };
  });
}

function buildUnifiedCharacterLine() {
  const entries = buildCharacterAliasEntries();
  if (!entries.length) return "";
  const parts = entries.map((entry) => {
    const summary = [entry.role, entry.appearance].filter(Boolean).join("：");
    return `${entry.name}${entry.alias}（${summary || "人物特征待补充"}）`;
  });
  return `统一人物：${parts.join('、')}`;
}

function normalizeDialogueSpeaker(rawSpeaker = "", aliasEntries = []) {
  const source = text(rawSpeaker);
  if (!source) return { speaker: "", mood: "" };
  const match = source.match(/^([^（(]+?)(?:[（(]([^）)]+)[）)])?$/);
  const baseName = text(match?.[1] || source);
  const mood = text(match?.[2]);
  const entry = aliasEntries.find((item) => item.names.some((candidate) => candidate === baseName || source.startsWith(candidate)));
  return { speaker: entry ? `${entry.name}` : baseName, mood };
}

function normalizeDialogueLine(line = "", aliasEntries = []) {
  const raw = String(line || "").trim();
  if (!raw || /^\d{1,2}:\d{2}\s*-\s*\d{1,2}:\d{2}\s*\|/.test(raw)) return raw;
  const match = raw.match(/^([^：:]+)[：:]\s*[“\"]?([\s\S]*?)[”\"]?$/);
  if (!match) return raw;
  const info = normalizeDialogueSpeaker(match[1], aliasEntries);
  const quote = text(match[2]);
  if (!info.speaker || !quote) return raw;
  return `${info.speaker}${info.mood ? `（${info.mood}）` : ""}：“${quote}”`;
}


function inferSceneFromBody(body = "") {
  const raw = text(body);
  if (!raw) return "当前场景连续";
  const explicit = raw.match(/场景[：:]\s*([^|，,；;。]+)/);
  if (explicit) return text(explicit[1]);
  const firstClause = raw.split(/[，,；;。]/)[0].trim();
  if (/(里|内|外|中|旁|前|后|上|下|门口|门外|门内|走廊|长廊|客厅|卧室|病房|诊室|殿内|殿外|宫门|庭院|院中|楼道|街口|路口|石道|尽头|桌旁|窗边|床边|会场|大厅|包厢|餐桌|洗手间|卫生间|办公室|教室|操场|车内|车外|站台|江边|河边|海边|山道|林中)$/.test(firstClause)) {
    return firstClause;
  }
  return "当前场景连续";
}

function detectShotMetaFromBody(body = "") {
  const raw = text(body);
  const shotSizes = ["单人胸像近景", "胸像近景", "大远景", "远景", "群像全景", "多人全景", "全景", "中远景", "双人近景", "多人中景", "中近景", "半身", "中景", "近景", "特写", "大特写"];
  const angles = ["平视", "俯视", "俯拍", "仰视", "仰拍", "侧拍", "过肩镜头", "主观视角", "高机位", "低机位", "顶拍"];
  const movements = ["长焦压缩后迅速拉近", "固定快推", "缓慢推镜", "快速推镜", "固定镜头", "半身跟拍", "跟拍", "摇摄", "手持微晃", "缓慢拉近", "快速拉近", "推近后停住", "轻推"];
  const transitions = ["硬切", "快切", "叠化", "闪白转场", "空镜切入", "直接切"];
  const shotSize = shotSizes.find((item) => raw.includes(item)) || "中景";
  const angle = angles.find((item) => raw.includes(item)) || "平视";
  const movement = movements.find((item) => raw.includes(item)) || "固定镜头";
  const transition = transitions.find((item) => raw.includes(item)) || "硬切";
  return { shotSize, angle, movement, transition };
}

function cleanNewStandardBody(body = "") {
  let raw = sanitizeTimelinePrompt(String(body || "")).trim();
  raw = raw.replace(/持续\d+秒，[^，。]*嘴唇同步说出[:：][“"]?[^”"。]*[”"]?[；;，,]?/g, "");
  raw = raw.replace(/(?:仅人物唇语|不生成字幕|不生成或)[^，。；;]*/g, "");
  raw = raw.replace(/(?:我|他|她|人物)?嘴唇同步(?:出|说出)?原文[:：]?[^，。；;]*/g, "");
  raw = raw.replace(/开始话/g, "");
  raw = raw.replace(new RegExp(STRICT_BAD_SHOT_PHRASES.source, "g"), "");
  raw = raw.replace(/^[，,；;、\s]+|[，,；;、\s]+$/g, "");
  raw = raw.replace(/\s+/g, " ");
  return rewriteRiskSensitiveVisualText(normalizeKnownCharacterNameRepeats(raw || "主体的具体可见动作、状态变化或关键道具变化清楚呈现"));
}

function cleanBodyForStandardShot(body = "") {
  let raw = String(body || "").trim();
  raw = raw.replace(/场景[：:][^|，,；;。]+/g, "");
  raw = raw.replace(/(?:单人胸像近景|胸像近景|大远景|远景|群像全景|多人全景|全景|中远景|双人近景|多人中景|中近景|半身|中景|近景|特写|大特写)[，,、]?/g, "");
  raw = raw.replace(/(?:平视|俯视|俯拍|仰视|仰拍|侧拍|过肩镜头|主观视角|高机位|低机位|顶拍)[，,、]?/g, "");
  raw = raw.replace(/(?:长焦压缩后迅速拉近|固定快推|缓慢推镜|快速推镜|固定镜头|半身跟拍|跟拍|摇摄|手持微晃|缓慢拉近|快速拉近|推近后停住|轻推)[，,、]?/g, "");
  raw = raw.replace(/(?:硬切|快切|叠化|闪白转场|空镜切入|直接切)[，,、]?/g, "");
  raw = raw.replace(/持续\d+秒，[^，。]*嘴唇同步说出[:：][“"]?[^”"。]*[”"]?[；;，,]?/g, "");
  raw = raw.replace(/仅人物唇语[^，。；;]*/g, "");
  raw = raw.replace(/不生成字幕[^，。；;]*/g, "");
  raw = raw.replace(/我嘴唇同步[^，。；;]*/g, "");
  raw = raw.replace(/开始话/g, "开始说话");
  raw = raw.replace(/[|]+/g, " ");
  raw = raw.replace(/^[，,；;、\s]+|[，,；;、\s]+$/g, "");
  raw = raw.replace(/\s+/g, " ");
  return rewriteRiskSensitiveVisualText(normalizeKnownCharacterNameRepeats(raw || "主体的具体可见动作或状态变化清楚呈现"));
}

function normalizeSpeakerToAlias(label = "", aliasEntries = []) {
  const info = normalizeDialogueSpeaker(label, aliasEntries);
  return info.speaker ? `${info.speaker}${info.mood ? `（${info.mood}）` : ""}` : text(label);
}

function extractDialogueLinesFromBody(body = "", aliasEntries = []) {
  let working = String(body || "");
  const dialogues = [];
  const lipSyncRegex = /持续\d+秒，([^，,：:]+?)嘴唇同步说出[:：][“"]([^”"]+)[”"]/g;
  working = working.replace(lipSyncRegex, (_, speaker, quote) => {
    const mapped = normalizeSpeakerToAlias(speaker, aliasEntries);
    if (mapped && quote) dialogues.push(`${mapped}：“${text(quote)}”`);
    return "";
  });
  const inlineQuoteRegex = /([^\n：:]{1,20}(?:[（(][^）)]{1,12}[）)])?)[:：][“"]([^”"]+)[”"]/g;
  working = working.replace(inlineQuoteRegex, (_, speaker, quote) => {
    const mapped = normalizeSpeakerToAlias(speaker, aliasEntries);
    if (mapped && quote) dialogues.push(`${mapped}：“${text(quote)}”`);
    return "";
  });
  return { body: working, dialogues };
}

function splitShotChunks(rawBlock = "") {
  const source = String(rawBlock || "").replace(/\r/g, "").trim();
  if (!source) return [];
  const normalized = source.replace(/[；;]/g, "\n");
  const regex = /((?:\d{1,2}:\d{2}|\d+)\s*-\s*(?:\d{1,2}:\d{2}|\d+)s?)\s*([\s\S]*?)(?=(?:\n|^)(?:\d{1,2}:\d{2}|\d+)\s*-\s*(?:\d{1,2}:\d{2}|\d+)s?\s*|$)/gm;
  const chunks = [];
  let match;
  while ((match = regex.exec(normalized))) {
    chunks.push({ time: text(match[1]), body: String(match[2] || "").trim() });
  }
  return chunks;
}

function normalizeShotChunk(chunk, aliasEntries = []) {
  const timeRaw = text(chunk?.time);
  const bodyRaw = String(chunk?.body || "").trim();
  const timeMatch = timeRaw.match(/^(\d{1,2}:\d{2}|\d+)\s*-\s*(\d{1,2}:\d{2}|\d+)s?$/);
  if (!timeMatch) return [];
  const start = formatClock(parseClockToSeconds(timeMatch[1]));
  const end = formatClock(parseClockToSeconds(timeMatch[2]));
  let meta = "";
  let scene = "";
  let content = bodyRaw;
  let isNewStandard = false;

  if (bodyRaw.includes("|")) {
    const parts = bodyRaw.split("|").map((item) => item.trim()).filter(Boolean);
    if (parts.length >= 1) meta = parts[0];
    if (parts.length >= 2 && /^场景[：:]/.test(parts[1])) {
      isNewStandard = true;
      scene = parts[1].replace(/^场景[：:]\s*/, "").trim();
      content = parts.slice(2).join(" | ").trim();
    } else {
      content = parts.slice(1).join(" | ").trim() || bodyRaw;
    }
  }

  if (!meta) {
    const detected = detectShotMetaFromBody(content || bodyRaw);
    meta = `${detected.shotSize}-${detected.angle}-${detected.movement}-${detected.transition}`;
  }

  const extracted = extractDialogueLinesFromBody(content || bodyRaw, aliasEntries);
  content = isNewStandard
    ? cleanNewStandardBody(extracted.body || content)
    : cleanBodyForStandardShot(extracted.body || content || bodyRaw);
  if (!scene) scene = inferSceneFromBody(bodyRaw);
  const main = `${start}-${end} | ${meta} | ${mergeSceneIntoPromptBody(scene, content)}`;
  return [main, ...extracted.dialogues];
}

function normalizeShotSection(rawBlock = "", aliasEntries = []) {
  const chunks = splitShotChunks(rawBlock);
  if (!chunks.length) return [];
  return chunks.flatMap((chunk) => normalizeShotChunk(chunk, aliasEntries));
}

function currentVideoConstraintLines() {
  const style = readStyle();
  return {
    picture: `【画面限制】：${text(style.picture_limit_prompt) || DEFAULT_STYLE.picture_limit_prompt}`,
    quality: `【画质约束】：${text(style.quality_constraint_prompt) || DEFAULT_STYLE.quality_constraint_prompt}`,
  };
}

function trailerStyleForAi(value = "", sourceText = "", genre = "") {
  const novelText = sourceText || text(readFieldValue?.("#novelText"));
  const currentGenre = genre || text(readFieldValue?.("#genre"));
  return normalizeTrailerStyleTemplate(value, novelText, currentGenre);
}


function aiVisualBoundaryRules() {
  return `【AI输入边界｜最终导出字段不参与拆镜】\n“负面提示词、画面限制、画质约束”仅在最终复制/导出时附加，不是小说正文、人物参考、画面参考或Skill内容。禁止复制这些字段到任何镜头，也不得让它们影响场景、动作、人物站位、镜头数量或时长。生成阶段只需避免与剧情无关的字幕、水印、Logo和漂浮UI；原文明确需要的系统面板、聊天记录、来电界面、表格、合同或监控画面必须按剧情保留。`;
}

function videoConstraintRules() {
  return aiVisualBoundaryRules();
}

function normalizeFinalSegmentText(rawText) {
  const source = String(rawText || "").replace(/\r/g, "").trim();
  if (!source) return source;
  const aliasEntries = buildCharacterAliasEntries();
  const lines = source.split("\n").map((line) => line.trim()).filter(Boolean);
  const unifiedLine = buildUnifiedCharacterLine();
  const constraintLines = currentVideoConstraintLines();
  const pictureLimitLine = constraintLines.picture;
  const qualityLine = constraintLines.quality;

  const normalizedLines = lines.map((line) => normalizeDialogueLine(line, aliasEntries));
  const cleaned = normalizedLines.filter((line) => !/^(统一人物：|【画面限制】|【画质约束】)/.test(line));

  const shotIndex = cleaned.findIndex((line) => /^镜头画面[:：]/.test(line));
  if (shotIndex >= 0) {
    const before = cleaned.slice(0, shotIndex);
    const after = cleaned.slice(shotIndex + 1);
    const firstShotLine = cleaned[shotIndex].replace(/^镜头画面[:：]\s*/, "").trim();
    let stopAt = after.findIndex((line) => /^(负面提示词[:：]|补充说明[:：]|备注[:：])/.test(line));
    if (stopAt < 0) stopAt = after.length;
    const shotBodyLines = [firstShotLine, ...after.slice(0, stopAt)].filter(Boolean);
    const shotLines = normalizeShotSection(shotBodyLines.join("\n"), aliasEntries);
    cleaned.splice(0, cleaned.length, ...before, "镜头画面：", ...shotLines, ...after.slice(stopAt));
  }

  let styleIndex = cleaned.findIndex((line) => /^统一风格[:：]/.test(line));
  if (styleIndex < 0) styleIndex = cleaned.findIndex((line) => /^首行提示[:：]/.test(line));
  const insertAt = styleIndex >= 0 ? styleIndex + 1 : 0;
  const injected = [];
  cleaned.forEach((line, index) => {
    injected.push(line);
    if (index + 1 === insertAt) {
      if (unifiedLine) injected.push(unifiedLine);
      injected.push(pictureLimitLine);
      injected.push(qualityLine);
    }
  });
  if (!cleaned.length) {
    if (unifiedLine) injected.push(unifiedLine);
    injected.push(pictureLimitLine, qualityLine);
  } else if (insertAt === 0) {
    const prefix = [];
    if (unifiedLine) prefix.push(unifiedLine);
    prefix.push(pictureLimitLine, qualityLine);
    return [...prefix, ...cleaned].join("\n");
  }
  return injected.join("\n");
}

function isGenericSceneLabel(value = "") {
  return /^(?:当前场景连续|当前场景|当前空间|简洁真实场景|古代实景空间|安静室内空间|世界观匹配的室内空间|世界观匹配的玄幻场景|未来科技空间|室内|室外|某处)$/.test(text(value));
}

function specificSceneForPiece(piece = {}, scene = {}) {
  const promptParts = splitScenePromptParts(piece.prompt, piece.visual_context || piece.shot?.visual_context);
  const candidates = [
    promptParts.scene,
    text(piece.visual_context),
    text(piece.shot?.visual_context),
    text(scene?.visual_context),
    directorLocationAnchor(piece.source_basis || piece.shot?.source_basis || scene?.source_text || scene?.text, `${text(scene?.source_context)} ${text(scene?.source_text || scene?.text)} ${text(scene?.next_context)}`),
  ].map((item) => text(item)).filter(Boolean);
  return candidates.find((item) => !isGenericSceneLabel(item)) || candidates[0] || "与原文时代一致的具体实景位置";
}

function dialogueMoodFromContext(value = "") {
  const source = text(value);
  const moods = ["急促又认真", "平静抬眼", "低声克制", "冷声质问", "厉声呵斥", "愤怒", "哽咽", "颤声", "轻声", "笃定", "决绝", "讥讽", "不耐烦", "温和", "震惊", "无奈", "严肃"];
  return moods.find((item) => source.includes(item)) || "清晰开口";
}

function aliasEntryForSpeakerName(rawName = "", entries = []) {
  const name = text(rawName);
  if (!name) return null;
  return entries.find((entry) => entry.names.some((candidate) => candidate === name || name.includes(candidate) || candidate.includes(name))) || null;
}

// 对白归属只接受 AI 生成阶段已经通过唯一说话人校验的结构化结果。
// 禁止在前端根据原文、本镜人物顺序或台词中的被点名者再次猜测说话人。

const STRICT_BAD_SHOT_PHRASES = /背景人物、家具或建筑线条保持简洁|周围环境保持简洁|背景保持简洁|画面先交代|落实原文|完成原文|当前场景连续|当前剧情实景空间|人物保持原有站位|画面没有其他变化|完后嘴唇闭合|嘴唇开始开合|嘴唇打开|嘴唇闭合|仅人物唇语|嘴唇同步出原文|我嘴唇同步出原文|嘴唇同步说出|开始话|开始说话|不生成或|动作对象|受力方向|必要群像|视觉中心|前后无动作变化|镜头缓慢推进观察|清晰开口但无台词|人物动作与反应清楚呈现|主体动作与反应清楚呈现/;

function stableAppearanceAnchorForName(name = "") {
  const target = text(name);
  if (!target) return "";
  const character = (state.characters || []).find((item) => {
    const normalized = normalizeCharacterRecord(item);
    return normalized.name === target || (normalized.aliases || []).includes(target);
  });
  if (!character) return "";
  const appearance = sanitizeStableCharacterAppearance(character.appearance || "");
  if (!appearance) return "";
  const clauses = appearance.split(/[，,；;]/).map((item) => text(item)).filter(Boolean);
  const selected = [];
  const take = (pattern) => {
    const item = clauses.find((clause) => pattern.test(clause));
    if (item && !selected.includes(item)) selected.push(item);
  };
  clauses.slice(0, 3).forEach((item) => { if (!selected.includes(item)) selected.push(item); });
  take(/发型|短发|长发|卷发|盘发|马尾|发髻|束发/);
  take(/身形|体态|体型|比例|肩背|宽肩|长腿|高挑|修长|纤细|结实/);
  take(/身穿|西装|衬衫|外套|夹克|风衣|礼服|裙|裤|袍|制服|校服|旗袍|战术/);
  take(/整体色调|主色|配色|色系/);
  take(/搭配|配饰|腕表|耳饰|项链|戒指|玉佩|发簪/);
  take(/脚穿|鞋|靴|履/);
  return selected.slice(0, 9).join("，");
}

function strictPromptNeedsRewrite(body = "", source = "") {
  const value = text(body);
  if (!value || value.length < 60) return true;
  if (STRICT_BAD_SHOT_PHRASES.test(value)) return true;
  if (!value.includes("→")) return true;
  const nodes = value.split("→").map((item) => text(item)).filter(Boolean);
  if (nodes.length < 3) return true;
  const actionHits = (value.match(/走|跑|冲|追|逼近|停|抬眼|低头|回头|转身|推|递|拿|放|举|握|抓|扶|拍|砸|亮起|震动|掀起|扬起|后退|前倾|靠近|起身|落下|拔剑|挥剑|格挡|施法|碎裂|坍塌/g) || []).length;
  if (actionHits < 1) return true;
  const sourceCore = text(source).replace(/[，。！？；：、\s]/g, "");
  const bodyCore = value.replace(/[，。！？；：、\s]/g, "");
  if (sourceCore.length > 12 && bodyCore === sourceCore) return true;
  return false;
}

function enrichStrictDirectorPrompt(body = "", source = "", piece = {}, scene = {}) {
  let value = cleanNewStandardBody(body);
  const names = uniqueTextList([...(piece.visible_characters || []), ...(piece.shot?.characters || []), ...(piece.shot?.scene_characters || [])]);
  const lead = names[0] || directorFallbackSubject(source);
  const anchor = stableAppearanceAnchorForName(lead);
  if (anchor && value && !value.includes(anchor.split("，")[0])) {
    value = `${lead}（${anchor}）${value.startsWith(lead) ? value.slice(lead.length) : `，${value}`}`;
  }
  if (!value.includes("→")) {
    const fallback = buildDirectorPrompt(source, scene, { ...(piece.shot || {}), ...piece }, 0);
    if (fallback) value = cleanBodyForStandardShot(fallback);
  }
  const nodes = value.split("→").map((item) => text(item)).filter(Boolean);
  if (nodes.length === 2) {
    const sceneLabel = specificSceneForPiece(piece, scene);
    nodes.splice(1, 0, `${sceneLabel}中的门框、地面线条、光线或周围人物拉出清楚前中后景`);
    value = nodes.join("→");
  }
  return value.replace(/[。；;\s]+$/g, "");
}

function applyStrictFinishedPromptPass(sceneId = "") {
  if (readPromptDensity() !== "strict") return 0;
  const aliasEntries = buildCharacterAliasEntries();
  let changed = 0;
  state.outlineShots.forEach((shot) => {
    const parentId = text(shot.parent_scene_id) || text((shot.parent_scene_ids || [])[0]);
    if (sceneId && parentId !== sceneId) return;
    const scene = sourceSceneById(parentId) || {};
    const source = text(shot.source_basis) || text(scene.source_text || scene.text);
    const segments = normalizeTimelineSegments(shot.timeline_segments);
    if (segments.length) {
      let segmentChanged = false;
      shot.timeline_segments = segments.map((segment) => {
        const segmentSource = text(segment.source_basis) || source;
        const parts = splitScenePromptParts(segment.prompt, segment.visual_context);
        let body = cleanNewStandardBody(parts.body || segment.prompt);
        if (strictPromptNeedsRewrite(body, segmentSource)) {
          const fallback = buildDirectorPrompt(segmentSource, scene, { ...shot, ...segment }, 0);
          if (fallback) body = cleanBodyForStandardShot(fallback);
          body = enrichStrictDirectorPrompt(body, segmentSource, { ...segment, shot }, scene);
          segmentChanged = true;
        }
        const sceneLabel = parts.scene && !isGenericSceneLabel(parts.scene) ? parts.scene : specificSceneForPiece({ ...segment, shot }, scene);
        const dialogueLines = Array.isArray(segment.dialogue_lines) ? segment.dialogue_lines.filter(Boolean) : [];
        return { ...segment, prompt: `场景：${sceneLabel} | ${body}`, visual_context: sceneLabel, dialogue_lines: dialogueLines };
      });
      if (segmentChanged) {
        shot.prompt = timelinePrompt(shot.timeline_segments);
        changed += 1;
      }
    } else {
      const parts = splitScenePromptParts(shot.prompt, shot.visual_context);
      let body = cleanNewStandardBody(parts.body || shot.prompt);
      const sceneLabel = parts.scene && !isGenericSceneLabel(parts.scene) ? parts.scene : specificSceneForPiece({ ...shot, shot }, scene);
      if (strictPromptNeedsRewrite(body, source)) {
        const fallback = buildDirectorPrompt(source, scene, shot, 0);
        if (fallback) body = cleanBodyForStandardShot(fallback);
        body = enrichStrictDirectorPrompt(body, source, { ...shot, shot }, scene);
        shot.prompt = `场景：${sceneLabel} | ${body}`;
        shot.visual_context = sceneLabel;
        changed += 1;
      }
      shot.dialogue_lines = Array.isArray(shot.dialogue_lines) ? shot.dialogue_lines.filter(Boolean) : [];
    }
  });
  return changed;
}

function detailedBodyForPiece(piece = {}, scene = {}) {
  const source = text(piece.source_basis || piece.shot?.source_basis || scene?.source_text || scene?.text);
  const parts = splitScenePromptParts(piece.prompt, piece.visual_context || piece.shot?.visual_context);
  let body = cleanNewStandardBody(parts.body || piece.prompt);
  const strictMode = readPromptDensity() === "strict";
  const weak = strictMode
    ? strictPromptNeedsRewrite(body, source)
    : (body.length < 70 || isWeakDirectorPrompt(body, source, piece.visible_characters || piece.shot?.characters || []));
  if (weak && source) {
    const fallback = buildDirectorPrompt(source, scene, { ...(piece.shot || {}), ...piece }, 0);
    if (fallback) body = cleanBodyForStandardShot(fallback);
  }
  if (strictMode) body = enrichStrictDirectorPrompt(body, source, piece, scene);
  if (!body.includes("→")) {
    const clauses = body.split(/[；;。]/).map((item) => text(item)).filter(Boolean);
    if (clauses.length > 1) body = clauses.slice(0, 4).join("→");
  }
  return body.replace(/[。；;\s]+$/g, "");
}

function flattenOutlinePieces() {
  const pieces = [];
  state.outlineShots.forEach((shot) => {
    const sceneId = text(shot.parent_scene_id) || text((shot.parent_scene_ids || [])[0]);
    const scene = sourceSceneById(sceneId) || {};
    ensureEditableTimelineCurrent(shot, "before_flatten_merge");
    const promptRevision = Math.max(0, Number.parseInt(shot.prompt_edit_revision, 10) || 0);
    const timelineRevision = Math.max(0, Number.parseInt(shot.timeline_edit_revision, 10) || 0);
    const timelineStale = promptRevision > timelineRevision || Boolean(text(shot.timeline_validation_error));
    const segments = timelineStale ? [] : normalizeTimelineSegments(shot.timeline_segments);
    if (segments.length) {
      segments.forEach((segment) => {
        pieces.push({
          ...segment,
          shot,
          scene,
          global_start: Number(shot.start_second) + Number(segment.start_offset),
          global_end: Number(shot.start_second) + Number(segment.end_offset),
          source_basis: text(segment.source_basis) || text(shot.source_basis),
          visible_characters: uniqueTextList([...(segment.visible_characters || []), ...(shot.characters || []), ...(shot.scene_characters || [])]),
        });
      });
    } else {
      pieces.push({
        ...shot,
        shot,
        scene,
        global_start: Number(shot.start_second),
        global_end: Number(shot.end_second),
        source_basis: text(shot.source_basis),
        visible_characters: uniqueTextList([...(shot.characters || []), ...(shot.scene_characters || [])]),
      });
    }
  });
  return pieces.sort((a, b) => a.global_start - b.global_start || a.global_end - b.global_end);
}

function finalShotLinesForRange(rangeStart, rangeEnd, aliasEntries = []) {
  const pieces = flattenOutlinePieces().filter((piece) => piece.global_start < rangeEnd && piece.global_end > rangeStart);
  const result = [];
  pieces.forEach((piece) => {
    const localStart = Math.max(0, piece.global_start - rangeStart);
    const localEnd = Math.max(localStart + 1, Math.min(rangeEnd, piece.global_end) - rangeStart);
    const sceneLabel = specificSceneForPiece(piece, piece.scene);
    const body = detailedBodyForPiece(piece, piece.scene);
    const meta = cameraTagFromSegment(piece);
    result.push(`${formatClock(localStart)}-${formatClock(localEnd)} | ${meta} | ${mergeSceneIntoPromptBody(sceneLabel, stripDialogueTextFromPromptBody(body, piece))}`);

    let dialogueLines = Array.isArray(piece.dialogue_lines) ? piece.dialogue_lines.map((item) => text(item)).filter(Boolean) : [];
    if (!dialogueLines.length && text(piece.speech_text)) {
      const speakerInfo = normalizeDialogueSpeaker(piece.speaker, aliasEntries);
      const speakerEntry = aliasEntryForSpeakerName(piece.speaker, aliasEntries);
      const speaker = speakerInfo.speaker || (speakerEntry ? `${speakerEntry.name}${speakerEntry.alias}` : "");
      const mood = speakerInfo.mood || dialogueMoodFromContext(`${piece.prompt} ${piece.source_basis}`);
      const quotes = String(piece.speech_text).split(/\n+/).map((item) => text(item)).filter(Boolean);
      dialogueLines = speaker ? quotes.map((quote) => `${speaker}（${mood}）：“${quote.replace(/^[“"]|[”"]$/g, "")}”`) : [];
    }
    dialogueLines.forEach((line) => result.push(line));
  });
  return result;
}

function replaceFinalShotSection(finalText = "", shotLines = []) {
  if (!shotLines.length) return finalText;
  const lines = String(finalText || "").replace(/\r/g, "").split("\n").map((line) => line.trim()).filter(Boolean);
  const shotIndex = lines.findIndex((line) => /^镜头画面[:：]/.test(line));
  let stopIndex = shotIndex >= 0 ? lines.findIndex((line, index) => index > shotIndex && /^(负面提示词[:：]|补充说明[:：]|备注[:：])/.test(line)) : -1;
  if (shotIndex >= 0) {
    if (stopIndex < 0) stopIndex = lines.length;
    return [...lines.slice(0, shotIndex), "镜头画面：", ...shotLines, ...lines.slice(stopIndex)].join("\n");
  }
  const negativeIndex = lines.findIndex((line) => /^负面提示词[:：]/.test(line));
  if (negativeIndex >= 0) return [...lines.slice(0, negativeIndex), "镜头画面：", ...shotLines, ...lines.slice(negativeIndex)].join("\n");
  return [...lines, "镜头画面：", ...shotLines].join("\n");
}

function enhanceFinalSegmentsList(segments = []) {
  if (!Array.isArray(segments)) return [];
  const aliasEntries = buildCharacterAliasEntries();
  let cursor = 0;
  return segments.map((segment, index) => {
    const duration = Math.max(1, Number.parseInt(segment?.total_seconds, 10) || 1);
    const rangeStart = cursor;
    const rangeEnd = cursor + duration;
    cursor = rangeEnd;
    const normalized = normalizeFinalSegmentText(segment?.text || "");
    const shotLines = finalShotLinesForRange(rangeStart, rangeEnd, aliasEntries);
    return {
      ...segment,
      index: Number.parseInt(segment?.index, 10) || index + 1,
      text: replaceFinalShotSection(normalized, shotLines),
    };
  });
}

function sceneMappedText(sceneId) {
  return outlineShotsByScene(sceneId)
    .map((shot) => formatShotLine(shot))
    .join("\n");
}

function hydrateScenesWithSourceText(rawScenes, novelText) {
  const scenes = Array.isArray(rawScenes) ? rawScenes.filter((scene) => scene && typeof scene === "object") : [];
  if (!scenes.length) {
    return { scenes: [], compatibilityNotice: "" };
  }

  const allHaveSourceText = scenes.every((scene) => text(scene.source_text));
  if (allHaveSourceText) {
    return {
      scenes: scenes.map((scene, index) => ({
        ...scene,
        text: sourceTextFromScene(scene),
        source_text: sourceTextFromScene(scene),
        source_index: normalizeSourceIndex(scene.source_index, index + 1),
      })),
      compatibilityNotice: "",
    };
  }

  const anyHaveSceneText = scenes.some((scene) => text(scene.text));
  if (anyHaveSceneText) {
    return {
      scenes: scenes.map((scene, index) => ({
        ...scene,
        text: sourceTextFromScene(scene),
        source_text: sourceTextFromScene(scene),
        source_index: normalizeSourceIndex(scene.source_index, index + 1),
      })),
      compatibilityNotice: "",
    };
  }

  const sourceScenes = splitOutlineSourceScenes(novelText);
  if (sourceScenes.length === scenes.length && scenes.length > 0) {
    return {
      scenes: scenes.map((scene, index) => ({
        ...scene,
        text: sourceScenes[index].source_text,
        source_text: sourceScenes[index].source_text,
        source_index: sourceScenes[index].source_index,
      })),
      compatibilityNotice: "当前工作区缺少 AI 原文分镜文本，已按整段原文临时回填，请重新按整段原文生成分镜/画面确认。",
    };
  }

  return {
    scenes: scenes.map((scene, index) => ({
      ...scene,
      text: sourceTextFromScene(scene),
      source_text: sourceTextFromScene(scene),
      source_index: normalizeSourceIndex(scene.source_index, index + 1),
    })),
    compatibilityNotice: "当前工作区缺少可恢复的 AI 原文分镜文本，需重新按整段原文生成分镜/画面对齐原文。",
  };
}

function computeSourceDirty() {
  const baseline = text(state.outlineSourceText);
  const current = text(readFieldValue("#novelText"));
  const hasGenerated = hasGeneratedOutlineState();
  return Boolean(hasGenerated && baseline && current !== baseline);
}

function hasGeneratedOutlineState() {
  return state.scenes.length > 0 || state.outlineShots.length > 0 || state.segments.length > 0;
}

function resetGeneratedOutlineState() {
  state.sceneOptions = [];
  state.scenes = [];
  state.outlineShots = [];
  state.outputs = [];
  state.segments = [];
  state.mergeWarnings = [];
  state.outlineSourceText = "";
  state.sourceDirty = false;
  state.sourceCompatibilityNotice = "";
}

function sourceNoticeMessages() {
  const messages = [];
  if (state.sourceDirty) {
    messages.push("整段原文已改动，当前分镜和时间轴仍基于旧整段生成结果，请重新按整段原文生成分镜/画面。");
  }
  if (text(state.sourceCompatibilityNotice)) {
    messages.push(text(state.sourceCompatibilityNotice));
  }
  return messages;
}

function renderSourceNotices() {
  const messages = sourceNoticeMessages();
  const sourceBox = $("#sourceStateNotice");
  const timelineBox = $("#timelineStateNotice");
  [sourceBox, timelineBox].forEach((node) => {
    if (!node) return;
    if (!messages.length) {
      node.classList.add("hidden");
      node.textContent = "";
      return;
    }
    node.classList.remove("hidden");
    node.textContent = messages.join(" ");
  });
}

function cleanState() {
  state.appearance_reference = text(readFieldValue("#appearanceReference", state.appearance_reference)).slice(0, 1200);
  state.character_guide_input = text(readFieldValue("#characterGuideInput", state.character_guide_input)).slice(0, 1200);
  const currentNovelText = readFieldValue("#novelText");
  const currentCharacterHash = buildCharacterSourceFingerprint(currentNovelText);
  const hasBoundCharacterRegistry = Boolean(
    state.analysisComplete
    || text(state.analysisSourceText)
    || (state.characters || []).length
    || text(state.character_guide_input)
  );
  if (hasBoundCharacterRegistry && state.characterRegistrySourceHash && state.characterRegistrySourceHash !== currentCharacterHash) {
    resetCharacterRegistryForSource(currentNovelText, { clearGuide: false });
  }
  if (hasBoundCharacterRegistry) state.characterRegistrySourceHash = state.characterRegistrySourceHash || currentCharacterHash;
  else state.characterRegistrySourceHash = currentCharacterHash;
  state.lastNovelInputHash = currentCharacterHash;
  state.deletedCharacterKeys = normalizeDeletedCharacterKeys(state.deletedCharacterKeys).filter((item) => item.startsWith(`${currentCharacterHash}::`));
  state.styleLocks = normalizeStyleLocks(state.styleLocks);
  state.styleAiSuggestions = normalizeStyleAiSuggestions(state.styleAiSuggestions);
  state.characterAiSuggestions = normalizeCharacterSuggestions(state.characterAiSuggestions);
  state.tts = normalizeTtsState(state.tts);
  state.characters = (state.characters || [])
    .filter((character) => characterBelongsToSource(character, currentNovelText))
    .map((character) => ensureConcreteAppearance(
      sanitizeCharacterAppearanceByAge(normalizeCharacterRecord({ ...character, source_hash: currentCharacterHash }), currentNovelText, { preserveRich: true }),
      currentNovelText,
    ))
    .filter((character) => character.name && !isCharacterSuppressed(character, currentNovelText));
  reconcileCharacterIdentityGraph(currentNovelText);
  enforceCharacterGuideInvariant(currentNovelText);

  const sceneResult = hydrateScenesWithSourceText(state.scenes, readFieldValue("#novelText"));
  state.scenes = sceneResult.scenes.map((scene) => makeScene(scene.source_text || scene.text, scene));
  state.sourceCompatibilityNotice = sceneResult.compatibilityNotice;

  const rawOutline = Array.isArray(state.outlineShots) && state.outlineShots.length
    ? state.outlineShots
    : Array.isArray(state.outputs)
      ? state.outputs
      : [];
  state.outlineShots = rawOutline.map((shot) => makeOutlineShot(shot)).filter((shot) => text(shot.prompt));
  sortOutlineShots();

  const sceneIds = new Set(state.scenes.map((scene) => scene.id));
  state.outlineShots = state.outlineShots.filter((shot) => {
    const parentIds = shot.parent_scene_ids || [];
    return !parentIds.length || parentIds.some((sceneId) => sceneIds.has(sceneId));
  });
  sortOutlineShots();
  syncSceneCharacterState();
  repairSceneContinuityAndCharacters();
  syncAllSceneCharactersToOutlineShots();
  // V78.3.0.2：历史/草稿/旧工作区进入当前运行时后也收口到同一场景锚点和连续全局时间轴。
  // 这是状态规范化，不在最终分段阶段做文本去重；无效人工时间文本仍由 validation_error 原样保护。
  ensureSceneCardAnchorsV78302("clean_state");
  rebuildCanonicalOutlineTimelineV78302("clean_state");
  state.sourceDirty = computeSourceDirty();
  syncTtsSourceState();
}

function getProjectData() {
  commitLatestEditableUiState("project_snapshot");
  cleanState();
  return {
    novel_text: readFieldValue("#novelText"),
    audio_total_seconds: readAudioTotalSeconds(),
    must_cover_details: text(readFieldValue("#mustCoverDetails")),
    shot_rhythm_requirements: text(readFieldValue("#shotRhythmRequirements")),
    outline_source_text: state.outlineSourceText,
    analysis_source_text: state.analysisSourceText,
    analysis_complete: Boolean(state.analysisComplete),
    source_dirty: state.sourceDirty,
    style: readStyle(),
    style_notes: readStyleNotes(),
    style_locks: state.styleLocks,
    style_ai_suggestions: state.styleAiSuggestions,
    appearance_reference: state.appearance_reference,
    character_guide_input: state.character_guide_input,
    global_analysis_advice: String(readFieldValue("#globalAnalysisAdvice", state.global_analysis_advice) || ""),
    character_registry_source_hash: state.characterRegistrySourceHash,
    character_guide_source_hash: state.characterGuideSourceHash,
    deleted_character_keys: normalizeDeletedCharacterKeys(state.deletedCharacterKeys),
    character_ai_suggestions: state.characterAiSuggestions,
    character_logic_version: state.characterLogicVersion || 2,
    ai_instructions: normalizeAiInstructions(state.aiInstructions),
    prompt_density: readPromptDensity(),
    prompt_example_text: String(readFieldValue("#promptExampleText", state.promptExampleText) || ""),
    prompt_example_logic: String(readFieldValue("#promptExampleLogic", state.promptExampleLogic) || ""),
    characters: state.characters,
    tts: normalizeTtsState(state.tts),
    scene_options: [],
    scenes: state.scenes,
    outputs: state.outlineShots,
    outline_shots: state.outlineShots,
    final_segments: state.segments,
    segment_max_seconds: Number.parseInt(readFieldValue("#segmentMaxSeconds"), 10) || 0,
  };
}

function scheduleDraftSave() {
  clearTimeout(persistTimer);
  if (persistIdleHandle) {
    if (typeof cancelIdleCallback === "function") cancelIdleCallback(persistIdleHandle);
    else clearTimeout(persistIdleHandle);
    persistIdleHandle = null;
  }
  persistTimer = setTimeout(() => {
    const flush = () => {
      persistIdleHandle = null;
      try {
        const serialized = JSON.stringify({
          projectId: state.projectId,
          projectName: readFieldValue("#projectName"),
          data: getProjectData(),
        });
        if (serialized === lastDraftSerialized) return;
        lastDraftSerialized = serialized;
        localStorage.setItem(DRAFT_KEY, serialized);
      } catch (error) {
        console.warn("Could not save local draft", error);
      }
    };
    if (typeof requestIdleCallback === "function") persistIdleHandle = requestIdleCallback(flush, { timeout: 1200 });
    else persistIdleHandle = setTimeout(flush, 0);
  }, 420);
}

function clearFinalSegments() {
  state.segments = [];
  state.mergeWarnings = [];
  renderSegments();
}

function renderAudioDurationWarning(total = null) {
  const warning = $("#durationTargetWarning");
  if (!warning) return;
  warning.classList.add("hidden");
  warning.textContent = "";
}

function formatTotalDuration() {
  const total = state.outlineShots.reduce((sum, item) => sum + normalizeDuration(item.duration), 0);
  const target = readAudioTotalSeconds();
  const targetText = target ? `（配音参考 ${target} 秒）` : "";
  const suffix = state.segments.length ? `，已分 ${state.segments.length} 段` : "";
  writeTextContent("#durationSummary", `总时长 ${total} 秒${targetText}${suffix}`);
  renderAudioDurationWarning(total);
}

function recalculateOutlineTimelineFromIndex(startIndex = 0) {
  if (!state.outlineShots.length) return;
  sortOutlineShots();
  const index = Math.max(0, Math.min(startIndex, state.outlineShots.length - 1));
  let cursor = index > 0 ? Number(state.outlineShots[index - 1].end_second) || 0 : 0;
  for (let i = index; i < state.outlineShots.length; i += 1) {
    const shot = state.outlineShots[i];
    const duration = normalizeDuration(shot.duration, 2);
    shot.duration = duration;
    shot.start_second = cursor;
    shot.end_second = cursor + duration;
    cursor = shot.end_second;
  }
  state.outputs = state.outlineShots;
}

async function updateShotDuration(shotId, nextDuration, options = {}) {
  sortOutlineShots();
  const index = state.outlineShots.findIndex((shot) => shot.id === shotId);
  if (index < 0) return false;

  const shot = state.outlineShots[index];
  if (Array.isArray(shot.timeline_segments) && shot.timeline_segments.length) {
    const retimed = retimeTimelineSegments(shot.timeline_segments, nextDuration);
    shot.timeline_segments = retimed.segments;
    shot.duration = retimed.duration;
    shot.prompt = timelinePrompt(retimed.segments);
    shot.lip_sync_fast = retimed.fastLipSync;
  } else {
    shot.duration = normalizeDuration(nextDuration, shot.duration);
  }
  shot.duration_locked = true;
  recalculateOutlineTimelineFromIndex(index);

  const shouldRerender = options.rerender !== false;
  const shouldPersist = options.persist !== false;
  const shouldAutoMerge = options.autoMerge ?? state.segments.length > 0;

  if (shouldRerender) {
    renderScenes();
    renderOutputs();
  }

  if (shouldAutoMerge) {
    await mergeSegments({ silent: true, render: shouldRerender, persist: shouldPersist });
  } else {
    if (shouldRerender) clearFinalSegments();
    if (shouldPersist) scheduleDraftSave();
  }
  return true;
}

function setButtonBusy(button, busy, label = "处理中") {
  if (!button) return;
  if (busy) {
    button.dataset.originalText = button.textContent;
    button.disabled = true;
    button.textContent = label;
  } else {
    button.disabled = false;
    button.textContent = button.dataset.originalText || button.textContent;
  }
}

function sleep(ms) {
  return new Promise((resolve) => window.setTimeout(resolve, ms));
}

function shouldRetryHttpStatus(status) {
  return [408, 429, 502, 503, 504].includes(Number(status));
}

function trimLongNovelText(value = "", limit = 14000) {
  const source = String(value || "");
  if (source.length <= limit) return source;
  const marker = "\n\n【长文本保护：已保留开头与结尾关键剧情，中间过长段落自动压缩】\n\n";
  const available = Math.max(0, limit - marker.length);
  const head = Math.floor(available * 0.62);
  const tail = Math.max(0, available - head);
  return `${source.slice(0, head)}${marker}${source.slice(-tail)}`;
}


const DEFAULT_AI_TIMEOUT_SECONDS = 400;

function clampAiTimeoutSeconds(value) {
  const number = Number.parseInt(value, 10);
  if (!Number.isFinite(number)) return DEFAULT_AI_TIMEOUT_SECONDS;
  return Math.max(30, Math.min(400, number));
}

function currentAiTimeoutSeconds() {
  return clampAiTimeoutSeconds(state.settings?.ai_timeout_seconds);
}

function isRemoteAiProcessingEndpoint(url = "") {
  return /\/api\/(?:analyze|character-core\/analyze|outline-scenes|regenerate-scene-outline|optimize-|settings\/test|generate-scene-prompts)/.test(String(url || ""));
}

function currentToolSessionToken() {
  const buildSession = String(globalThis.__VIDEO_PROMPT_TOOL_BUILD__?.session || "").trim();
  if (buildSession) return buildSession;
  try { return String(new URLSearchParams(globalThis.location?.search || "").get("session") || "").trim(); }
  catch (_error) { return ""; }
}

async function requestJSON(url, options = {}) {
  const timeoutMs = Math.max(30000, Number(options.timeoutMs) || 150000);
  const timeoutLabelSeconds = Math.max(30, Number(options.timeoutLabelSeconds) || Math.round(timeoutMs / 1000));
  const controller = new AbortController();
  const timer = window.setTimeout(() => controller.abort(), timeoutMs);
  const safeOptions = { ...options };
  delete safeOptions.timeoutMs;
  delete safeOptions.timeoutLabelSeconds;
  let response;
  try {
    response = await fetch(url, {
      ...safeOptions,
      cache: "no-store",
      signal: controller.signal,
      headers: {
        "Content-Type": "application/json",
        "Cache-Control": "no-store, no-cache, must-revalidate",
        "Pragma": "no-cache",
        "X-VideoPromptTool-Session": currentToolSessionToken(),
        ...(safeOptions.headers || {}),
      },
    });
  } catch (error) {
    if (error?.name === "AbortError") {
      throw new Error(`AI单次处理超过 ${timeoutLabelSeconds} 秒，软件已停止本次请求。系统不会自动重试；可在“AI 设置”中把最长等待调到 400 秒。`);
    }
    throw new Error(`无法连接本地服务：${formatApiError(error)}。系统未自动重试；可再次手动点击。`);
  } finally {
    window.clearTimeout(timer);
  }

  const rawText = await response.text();
  let data = {};
  try {
    data = rawText ? JSON.parse(rawText) : {};
  } catch (_error) {
    data = { detail: rawText || "本地服务返回了无法识别的内容。" };
  }

  if (!response.ok) {
    if (data?.code === "STALE_BROWSER_SESSION") {
      try { globalThis.__retireVideoPromptToolPage?.(data?.error || "旧页面会话已失效。"); } catch (_error) {}
    }
    const detail = formatApiError(data?.detail ?? data?.message ?? data?.error ?? data);
    throw new Error(`请求失败（HTTP ${response.status}）：${detail}。本次点击只请求1次，未自动重试；可再次手动点击。`);
  }

  if (data && typeof data === "object" && (data.error || data.detail?.error)) {
    throw new Error(`${formatApiError(data.error || data.detail)}。本次点击只请求1次，未自动重试；可再次手动点击。`);
  }
  return data;
}

async function persistModifiedAiSettingsBeforeRequest(url = "") {
  if (!isRemoteAiProcessingEndpoint(url) || /\/api\/(?:settings|runtime-config)/.test(url)) return;
  const selectors = ["#settingsMode", "#settingsBaseUrl", "#settingsModel", "#settingsAiTimeout", "#settingsApiKey"];
  const modifiedNodes = selectors.map((selector) => document.querySelector(selector)).filter((node) => node?.dataset.liveModified === "true");
  if (!modifiedNodes.length) return;
  const timeoutSeconds = clampAiTimeoutSeconds(readFieldValue("#settingsAiTimeout", currentAiTimeoutSeconds()));
  const payload = readSettingsForm();
  const settingsResponse = await requestJSON("/api/settings", {
    method: "POST",
    body: JSON.stringify(payload),
    timeoutMs: 30000,
    timeoutLabelSeconds: 30,
  });
  const runtimeResponse = await requestJSON("/api/runtime-config", {
    method: "POST",
    body: JSON.stringify({ ai_timeout_seconds: timeoutSeconds }),
    timeoutMs: 30000,
    timeoutLabelSeconds: 30,
  });
  state.settings = {
    ...(settingsResponse?.settings || state.settings || {}),
    ai_timeout_seconds: clampAiTimeoutSeconds(runtimeResponse?.runtime_config?.ai_timeout_seconds ?? timeoutSeconds),
  };
  modifiedNodes.forEach((node) => { delete node.dataset.liveModified; });
  const keyInput = document.querySelector("#settingsApiKey");
  if (keyInput && payload.api_key) keyInput.value = "";
  updateAIStatus?.();
}

async function postJSON(url, body) {
  try { commitLatestEditableUiState(`before_api:${url}`); } catch (_error) {}
  await persistModifiedAiSettingsBeforeRequest(url);
  const safeBody = sanitizeApiRequestBody(body);
  if (safeBody && typeof safeBody === 'object') {
    if (typeof safeBody.novel_text === 'string' && /analyze|optimize/.test(url)) {
      safeBody.novel_text = trimLongNovelText(compactTransportPromptText(safeBody.novel_text));
    }
    if (typeof safeBody.must_cover_details === 'string') safeBody.must_cover_details = compactTransportPromptText(safeBody.must_cover_details);
    if (typeof safeBody.shot_rhythm_requirements === 'string') safeBody.shot_rhythm_requirements = compactTransportPromptText(safeBody.shot_rhythm_requirements);
  }
  const isAiRequest = isRemoteAiProcessingEndpoint(url);
  const timeoutSeconds = isAiRequest ? currentAiTimeoutSeconds() : 90;
  // Browser timeout includes a small response/JSON parsing buffer. The backend
  // generation read timeout remains exactly the value selected by the user.
  const timeoutMs = isAiRequest ? (timeoutSeconds * 1000 + 15000) : 90000;
  return requestJSON(url, {
    method: "POST",
    body: JSON.stringify(safeBody),
    timeoutMs,
    timeoutLabelSeconds: timeoutSeconds,
  });
}

// V78 Phase14: old postJSON remains an independent network validator/fallback.
// Native Generator Service reads this compatibility bridge but owns the promoted request path.
function describeV77GeneratorRequestPlan(url, body) {
  const safeBody = sanitizeApiRequestBody(body);
  if (safeBody && typeof safeBody === "object") {
    if (typeof safeBody.novel_text === "string" && /analyze|optimize/.test(url)) safeBody.novel_text = trimLongNovelText(compactTransportPromptText(safeBody.novel_text));
    if (typeof safeBody.must_cover_details === "string") safeBody.must_cover_details = compactTransportPromptText(safeBody.must_cover_details);
    if (typeof safeBody.shot_rhythm_requirements === "string") safeBody.shot_rhythm_requirements = compactTransportPromptText(safeBody.shot_rhythm_requirements);
  }
  const isAiRequest = isRemoteAiProcessingEndpoint(url);
  const timeoutSeconds = isAiRequest ? currentAiTimeoutSeconds() : 90;
  const stable = (value) => { if (value === null || typeof value !== "object") return value; if (Array.isArray(value)) return value.map(stable); const out = {}; Object.keys(value).sort().forEach((key) => { if (value[key] !== undefined && typeof value[key] !== "function") out[key] = stable(value[key]); }); return out; };
  let h = 2166136261; for (const ch of JSON.stringify(stable(safeBody || {}))) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); }
  return { endpoint: String(url || ""), method: "POST", body: safeBody, timeout_seconds: timeoutSeconds, timeout_ms: isAiRequest ? (timeoutSeconds * 1000 + 15000) : 90000, content_type: "application/json", body_hash: (h >>> 0).toString(16).padStart(8, "0"), body_chars: JSON.stringify(safeBody || {}).length };
}
globalThis.__V78_GENERATOR_HOST_BRIDGE__ = {
  version: "v77_generator_host_bridge_phase14",
  describeLegacyRequest: describeV77GeneratorRequestPlan,
  executeLegacy: async (url, payload) => normalizeApiCharacterReferences(await postJSON(url, payload)),
  persistSettingsBeforeRequest: (url) => persistModifiedAiSettingsBeforeRequest(url),
  commitLatestEditableUiState: (reason) => commitLatestEditableUiState(reason),
  currentAiTimeoutSeconds: () => currentAiTimeoutSeconds(),
  normalizeResponse: (data) => normalizeApiCharacterReferences(data),
};

function characterSuggestionFor(index) {
  const character = state.characters[index] || {};
  const key = characterSuggestionKey(character, index);
  return normalizeCharacterSuggestionEntry(state.characterAiSuggestions[key] || {});
}

function setCharacterSuggestion(index, suggestion) {
  const character = state.characters[index] || {};
  const key = characterSuggestionKey(character, index);
  const normalized = normalizeCharacterSuggestionEntry(suggestion);
  if (normalized.appearance || normalized.role) {
    state.characterAiSuggestions[key] = normalized;
  } else {
    delete state.characterAiSuggestions[key];
  }
}

function applyCharacterSuggestion(index) {
  const suggestion = characterSuggestionFor(index);
  if (!suggestion.appearance && !suggestion.role) return;
  if (suggestion.appearance) {
    const novelText = text(readFieldValue("#novelText"));
    state.characters[index].appearance = sanitizeCharacterAppearanceByAge({ ...state.characters[index], appearance: suggestion.appearance }, novelText).appearance;
  }
  if (suggestion.role) {
    state.characters[index].role = suggestion.role;
  }
  setCharacterSuggestion(index, {});
  renderCharacters();
  renderScenes();
  clearFinalSegments();
  scheduleDraftSave();
}

function appearanceDirectiveRules(note = "") {
  const source = text(note);
  const replacements = [];
  const removals = [];
  const additions = [];
  const seen = new Set();
  const cleanPart = (value) => text(value)
    .replace(/^(?:把|将|请把|请将|帮我把|需要把|外形里|描述里)/, "")
    .replace(/(?:一些|一点|一下|的描述|这个特征)$/g, "")
    .trim();

  const replacementPattern = /(?:把|将|请把|请将|帮我把)?\s*([^，,。；;\n]{1,36}?)\s*(?:改为|改成|换成|替换为|调整为|变为)\s*([^，,。；;\n]{1,36})(?=$|[，,。；;\n])/g;
  let match;
  while ((match = replacementPattern.exec(source))) {
    const from = cleanPart(match[1]);
    const to = cleanPart(match[2]);
    if (!from || !to || from === to) continue;
    const key = `r:${from}->${to}`;
    if (!seen.has(key)) { seen.add(key); replacements.push({ from, to }); }
  }

  const removalPattern = /(?:删除|去掉|移除|不要|取消)\s*([^，,。；;\n]{1,30})(?=$|[，,。；;\n])/g;
  while ((match = removalPattern.exec(source))) {
    const value = cleanPart(match[1]);
    if (!value || /^(?:人物|角色|描述|外形|内容)$/.test(value)) continue;
    const key = `d:${value}`;
    if (!seen.has(key)) { seen.add(key); removals.push(value); }
  }

  const additionPattern = /(?:增加|加入|添加|补充|加上)\s*([^，,。；;\n]{1,30})(?=$|[，,。；;\n])/g;
  while ((match = additionPattern.exec(source))) {
    const value = cleanPart(match[1]);
    if (!value || /^(?:细节|描述|内容|一些细节)$/.test(value)) continue;
    const key = `a:${value}`;
    if (!seen.has(key)) { seen.add(key); additions.push(value); }
  }
  return { replacements, removals, additions };
}

function applyAppearanceModificationNote(currentAppearance = "", aiAppearance = "", note = "") {
  const baseline = sanitizeStableCharacterAppearance(currentAppearance);
  let next = sanitizeStableCharacterAppearance(aiAppearance) || baseline;
  const rules = appearanceDirectiveRules(note);
  rules.replacements.forEach(({ from, to }) => {
    const pattern = new RegExp(escapeGuidanceRegExp(from), "g");
    if (pattern.test(next)) next = next.replace(pattern, to);
    else if (!next.includes(to) && baseline.includes(from)) next = `${next}，${to}`;
  });
  rules.removals.forEach((target) => {
    next = next
      .split(/[，,；;。]/)
      .map((item) => text(item))
      .filter(Boolean)
      .filter((item) => !item.includes(target))
      .join("，");
  });
  rules.additions.forEach((target) => {
    if (!next.includes(target)) next = `${next}，${target}`;
  });
  return sanitizeStableCharacterAppearance(next) || baseline;
}

function validateAppearanceModificationApplied(before = "", after = "", note = "") {
  const userNote = text(note);
  if (!userNote) return { ok: true, reason: "" };
  const previous = sanitizeStableCharacterAppearance(before);
  const current = sanitizeStableCharacterAppearance(after);
  const rules = appearanceDirectiveRules(userNote);
  for (const { from, to } of rules.replacements) {
    if (!current.includes(to) || current.includes(from)) return { ok: false, reason: `“${from}改为${to}”没有落实` };
  }
  for (const target of rules.removals) {
    if (current.includes(target)) return { ok: false, reason: `“去掉${target}”没有落实` };
  }
  for (const target of rules.additions) {
    if (!current.includes(target)) return { ok: false, reason: `“增加${target}”没有落实` };
  }
  if (!rules.replacements.length && !rules.removals.length && !rules.additions.length
      && previous.replace(/[\s，,。；;：:]+/g, "") === current.replace(/[\s，,。；;：:]+/g, "")) {
    return { ok: false, reason: "AI返回内容与修改前完全一致" };
  }
  return { ok: true, reason: "" };
}

async function optimizeCharacterDescription(index) {
  const novelText = text(readFieldValue("#novelText"));
  if (!novelText) return apiError("请先粘贴整段原文。");
  const button = document.querySelector?.(`[data-optimize-character="${index}"]`);
  setButtonBusy(button, true, "优化中");
  try {
    const style = readStyle();
    const current = normalizeCharacterRecord(state.characters[index] || {});
    const userNote = text(current.appearance_note);
    const focusedNovel = [
      appendInstructionToNovel(novelText, "single_character"),
      `【当前人物】${current.name}`,
      `【人物修改意见｜最高优先级】${userNote || "未填写；只提升准确度和稳定识别细节"}`,
      "只返回修改后的外形；不得改变姓名、性别、身份、年龄阶段，不得输出模型内部判断或年龄校验说明。",
    ].join("\n");
    const data = await postJSON("/api/optimize-character-copy", {
      novel_text: focusedNovel,
      genre: style.genre,
      trailer_style: trailerStyleForAi(style.trailer_style),
      character: characterForAppearanceAi({ ...current, appearance_note: userNote }),
    });
    const rawCandidateAppearance = sanitizeStableCharacterAppearance(data.appearance || data.character?.appearance || "");
    if (!rawCandidateAppearance) throw new Error("AI没有返回可用的人物外形，原人物卡已保留。");
    const candidateAppearance = applyAppearanceModificationNote(current.appearance, rawCandidateAppearance, userNote);
    const noteCheck = validateAppearanceModificationApplied(current.appearance, candidateAppearance, userNote);
    if (!noteCheck.ok) throw new Error(`人物修改意见没有真正落实：${noteCheck.reason}。原人物卡已保留。`);
    state.characters[index] = sanitizeCharacterAppearanceByAge({
      ...current,
      name: current.name,
      gender: current.gender,
      role: current.role,
      appearance: candidateAppearance,
      appearance_note: current.appearance_note,
      age_stages: current.age_stages || inferCharacterAgeStages(novelText, current),
      aliases: current.aliases,
    }, novelText, { preserveRich: true });
    reconcileCharacterIdentityGraph(novelText);
    renderCharacters();
    renderScenes();
    clearFinalSegments();
    scheduleDraftSave();
    showAIStatusNotice(`人物“${current.name}”已按人物修改意见重新生成外形，姓名、性别、身份和年龄阶段均保持不变。`, "ready", 5000);
  } catch (error) {
    apiError(error.message);
  } finally {
    setButtonBusy(button, false);
  }
}

function validateOptimizedCharacterBatch(currentCharacters = [], incomingCharacters = [], novelText = "") {
  if (!Array.isArray(incomingCharacters) || !incomingCharacters.length || incomingCharacters.length !== currentCharacters.length) return null;
  const incoming = incomingCharacters.map((character) => normalizeCharacterRecord(character));
  const used = new Set();
  const result = currentCharacters.map((rawCurrent, index) => {
    const current = normalizeCharacterRecord(rawCurrent);
    let matchIndex = incoming.findIndex((candidate, candidateIndex) => !used.has(candidateIndex)
      && sanitizeCharacterIdentityName(candidate.name, candidate.role, candidate.aliases) === current.name);
    if (matchIndex < 0 && index < incoming.length && !used.has(index)) matchIndex = index;
    if (matchIndex < 0) return null;
    used.add(matchIndex);
    const candidate = incoming[matchIndex];
    const rawAppearance = sanitizeStableCharacterAppearance(candidate.appearance);
    if (!rawAppearance) return null;
    const appearance = applyAppearanceModificationNote(current.appearance, rawAppearance, current.appearance_note);
    const noteCheck = validateAppearanceModificationApplied(current.appearance, appearance, current.appearance_note);
    if (!noteCheck.ok) return null;
    return sanitizeCharacterAppearanceByAge({
      ...current,
      name: current.name,
      gender: current.gender,
      role: current.role,
      appearance,
      appearance_note: current.appearance_note,
      age_stages: current.age_stages || candidate.age_stages,
      aliases: current.aliases,
    }, novelText, { preserveRich: true });
  });
  return result.some((item) => item === null) ? null : result;
}

async function optimizeAllCharacters() {
  const characterCore = globalThis.__characterCoreV2Api;
  if (characterCore && typeof characterCore.runCharacters === "function") {
    return characterCore.runCharacters({button: $("#optimizeAllCharactersBtn")});
  }
  const novelText = text(readFieldValue("#novelText"));
  if (!novelText) return apiError("请先粘贴整段原文。");
  if (!state.characters.length) return apiError("当前没有可重新生成的人物。");
  const button = $("#optimizeAllCharactersBtn");
  const snapshot = state.characters.map((character) => normalizeCharacterRecord(character));
  const appearanceReference = text(readFieldValue("#appearanceReference")).slice(0, 1200);
  setButtonBusy(button, true, "全部生成中");
  try {
    const style = readStyle();
    const characterNotes = snapshot
      .filter((item) => text(item.appearance_note))
      .map((item) => `${item.name}：${text(item.appearance_note)}`)
      .join("；");
    const data = await postJSON("/api/optimize-all-characters", {
      novel_text: appendInstructionToNovel(novelText, "all_characters"),
      genre: style.genre,
      trailer_style: trailerStyleForAi(style.trailer_style),
      // Put user notes first so schema trimming can never remove the key edits.
      appearance_reference: [characterNotes ? `人物修改意见（最高优先级）：${characterNotes}` : "", appearanceReference, storyEraHint(novelText), `人物年龄阶段：${snapshot.map((item) => `${item.name}=${text(item.age_stages) || "待判断"}`).join("；")}`].filter(Boolean).join("\n").slice(0, 900),
      characters: snapshot.map((item) => characterForAppearanceAi(item)),
    });
    const nextCharacters = validateOptimizedCharacterBatch(snapshot, data.characters, novelText);
    if (!nextCharacters) throw new Error("AI 返回的人物名单不完整或顺序不一致，已保留原人物，未做部分覆盖。");
    const beforeAppearance = snapshot.map((item) => text(item.appearance)).join('\n');
    state.characters = nextCharacters;
    repairCharacterAgeStages(novelText, { force: false });
    reconcileCharacterIdentityGraph(novelText);
    const afterAppearance = state.characters.map((item) => text(item.appearance)).join('\n');
    state.appearance_reference = appearanceReference;
    renderCharacters();
    renderScenes();
    clearFinalSegments();
    scheduleDraftSave();
    showAIStatusNotice(
      beforeAppearance === afterAppearance
        ? "AI返回的人物外形与当前内容一致，人物卡未发生变化；原有高质量描述已保留，没有被通用模板或内部年龄规则覆盖。"
        : `已重新生成全部 ${state.characters.length} 个人物的外形；姓名、性别、身份、年龄阶段和每张人物卡的修改意见均保持对应。`,
      beforeAppearance === afterAppearance ? "warning" : "ready",
      7000,
    );
  } catch (error) {
    apiError(error.message);
  } finally {
    setButtonBusy(button, false);
  }
}

function renderCharacters() {
  cleanState();
  const container = $("#characters");
  const template = $("#characterTemplateV2") || $("#characterTemplate");
  if (!container || !template) return;
  container.innerHTML = "";
  if (!state.characters.length) {
    container.innerHTML = '<div class="empty-state compact">还没有人物。可先让 AI 判断人物，也可以手动新增。</div>';
    return;
  }

  const currentNovelText = text(readFieldValue("#novelText"));
  const fragment = document.createDocumentFragment();
  state.characters.forEach((rawCharacter, index) => {
    const character = sanitizeCharacterAppearanceByAge(normalizeCharacterRecord(rawCharacter), currentNovelText, { preserveRich: true });
    state.characters[index] = character;
    const node = template.content.firstElementChild.cloneNode(true);
    node.querySelector(".character-title").textContent = `人物 ${index + 1}${character.stage_label ? ` · ${character.stage_label}` : ""}`;

    const nameInput = node.querySelector('[data-field="name"]');
    const genderInput = node.querySelector('[data-field="gender"]');
    const appearanceInput = node.querySelector('[data-field="appearance"]');
    const appearanceNoteInput = node.querySelector('[data-field="appearanceNote"]');
    const ageStagesInput = node.querySelector('[data-field="ageStages"]');
    const optimizeBtn = node.querySelector('[data-field="optimizeCharacter"]');

    nameInput.value = characterDisplayName(character);
    genderInput.value = character.gender;
    appearanceInput.value = character.appearance;
    if (appearanceNoteInput) appearanceNoteInput.value = character.appearance_note || "";
    if (ageStagesInput) ageStagesInput.value = character.age_stages || "";

    if (optimizeBtn) optimizeBtn.dataset.optimizeCharacter = String(index);

    nameInput.addEventListener("change", () => {
      const oldName = state.characters[index]?.name;
      const parsedName = parseCharacterDisplayName(nameInput.value);
      const newName = parsedName.name;
      if (!newName) {
        apiError("人物名字不能为空。");
        nameInput.value = characterDisplayName(state.characters[index]);
        return;
      }
      if (state.characters.some((item, itemIndex) => itemIndex !== index && item.name === newName)) {
        apiError("人物名字不能重复。");
        nameInput.value = characterDisplayName(state.characters[index]);
        return;
      }
      const oldKey = characterSuggestionKey({ name: oldName }, index);
      const nextKey = characterSuggestionKey({ name: newName }, index);
      if (state.characterAiSuggestions[oldKey] && oldKey !== nextKey) {
        state.characterAiSuggestions[nextKey] = state.characterAiSuggestions[oldKey];
        delete state.characterAiSuggestions[oldKey];
      }
      state.characters[index].name = newName;
      state.characters[index].display_name = parsedName.display_name || newName;
      state.characters[index].aliases = uniqueTextList([...(state.characters[index].aliases || []), ...(parsedName.aliases || [])]).filter((item) => item !== newName);
      state.characters[index].card_origin = "manual";
      state.characters[index].source_hash = buildCharacterSourceFingerprint(readNovelTextRaw());
      unsuppressCharacterForCurrentSource(state.characters[index], readNovelTextRaw());
      state.scenes.forEach((scene) => {
        scene.characters = scene.characters.map((name) => name === oldName ? newName : name);
      });
      state.outlineShots.forEach((shot) => {
        shot.characters = (shot.characters || []).map((name) => name === oldName ? newName : name);
      });
      syncAllSceneCharactersToOutlineShots();
      renderCharacters();
      renderScenes();
      renderOutputs();
      clearFinalSegments();
      scheduleDraftSave();
    });

    genderInput.addEventListener("change", () => {
      state.characters[index].gender = text(genderInput.value) || "未定";
      state.characters[index].card_origin = isManuallyManagedCharacter(state.characters[index]) ? state.characters[index].card_origin : "manual";
      clearFinalSegments();
      scheduleDraftSave();
    });

    appearanceInput.addEventListener("input", () => {
      state.characters[index].appearance = text(appearanceInput.value).slice(0, CHARACTER_APPEARANCE_MAX_CHARS);
      state.characters[index].appearance_fields = {};
      state.characters[index].appearance_protocol = "manual_text";
      state.characters[index].appearance_source = "user_edited";
      state.characters[index].generation_status = v38AppearanceIsUsable(state.characters[index].appearance) ? "ready" : "needs_generation";
      state.characters[index].card_origin = isManuallyManagedCharacter(state.characters[index]) ? state.characters[index].card_origin : "manual";
      clearFinalSegments();
      scheduleDraftSave();
    });

    appearanceNoteInput?.addEventListener("input", () => {
      state.characters[index].appearance_note = text(appearanceNoteInput.value).slice(0, 1800);
      state.characters[index].card_origin = isManuallyManagedCharacter(state.characters[index]) ? state.characters[index].card_origin : "manual";
      scheduleDraftSave();
    });

    ageStagesInput?.addEventListener("input", () => {
      state.characters[index].age_stages = text(ageStagesInput.value).slice(0, 320);
      state.characters[index].card_origin = isManuallyManagedCharacter(state.characters[index]) ? state.characters[index].card_origin : "manual";
      clearFinalSegments();
      scheduleDraftSave();
    });

    optimizeBtn.addEventListener("click", () => optimizeCharacterDescription(index));

    node.querySelector(".delete-character").addEventListener("click", () => {
      const removedName = character.name;
      suppressCharacterForCurrentSource(character, readNovelTextRaw());
      delete state.characterAiSuggestions[characterSuggestionKey(character, index)];
      state.characters.splice(index, 1);
      state.scenes.forEach((scene) => {
        scene.characters = scene.characters.filter((name) => name !== removedName);
      });
      state.outlineShots.forEach((shot) => {
        shot.characters = (shot.characters || []).filter((name) => name !== removedName);
      });
      syncAllSceneCharactersToOutlineShots();
      renderCharacters();
      renderScenes();
      renderOutputs();
      clearFinalSegments();
      scheduleDraftSave();
    });

    fragment.appendChild(node);
  });
  container.appendChild(fragment);
}

function renderMappedOutline(container, scene) {
  container.innerHTML = "";
  const mappedShots = outlineShotsByScene(scene.id);
  if (!mappedShots.length) {
    container.innerHTML = '<div class="empty-state compact">这条原文分镜还没有命中时间片。</div>';
    return;
  }
  const head = document.createElement("div");
  head.className = "mapped-outline-head";
  const title = document.createElement("p");
  title.className = "field-label inline";
  const segmentCount = mappedShots.reduce((sum, shot) => sum + (shot.timeline_segments?.length || 1), 0);
  title.textContent = "本条完整视频画面提示词";
  const badge = document.createElement("span");
  badge.className = "count-badge";
  badge.textContent = `内含 ${segmentCount} 个时段`;
  head.append(title, badge);
  container.appendChild(head);

  const list = document.createElement("div");
  list.className = "mapped-outline-list";
  mappedShots.forEach((shot, index) => {
    const card = document.createElement("article");
    card.className = "mapped-shot-card";
    const shotHead = document.createElement("div");
    shotHead.className = "mapped-shot-head";
    const shotTitle = document.createElement("strong");
    shotTitle.textContent = mappedShots.length === 1 ? "完整画面提示词" : `画面卡 ${index + 1}/${mappedShots.length}`;
    const time = document.createElement("span");
    time.textContent = `${shot.start_second}-${shot.end_second}s`;
    shotHead.append(shotTitle, time);

    const body = document.createElement("p");
    body.className = "mapped-shot-body";
    body.textContent = formatShotLine(shot);

    card.append(shotHead, body);
    list.appendChild(card);
  });
  container.appendChild(list);
}

function classifyShotPurpose(shot) {
  const prompt = text(shot?.prompt);
  if (!prompt) return "主画面";
  if (/(特写|局部|屏幕|指尖|钥匙|戒指|房产证|文件|细节|物件)/.test(prompt)) return "补细节";
  if (/(反应|愣住|错愕|停住|抬眼|沉默|看向|神情)/.test(prompt)) return "反应镜头";
  if (/(推进|推近|前移|走进|靠近|转身|硬切|切到|反转)/.test(prompt)) return "推进镜头";
  return "主画面";
}


function normalizeSceneCastSlotIds(values = []) {
  return uniqueTextList(Array.isArray(values) ? values : []);
}

function sceneAutomaticSlotIds(scene = {}) {
  return normalizeSceneCastSlotIds([
    ...(Array.isArray(scene.relation_selected_slot_ids) ? scene.relation_selected_slot_ids : []),
    ...(Array.isArray(scene.keyword_selected_slot_ids) ? scene.keyword_selected_slot_ids : []),
  ]);
}

function sceneEffectiveSlotIds(scene = {}) {
  const relationIds = normalizeSceneCastSlotIds(scene.relation_selected_slot_ids);
  const keywordIds = normalizeSceneCastSlotIds(scene.keyword_selected_slot_ids);
  const manualAdded = normalizeSceneCastSlotIds(scene.manual_added_slot_ids);
  const manualExcluded = normalizeSceneCastSlotIds(scene.manual_excluded_slot_ids);
  if (!relationIds.length && !keywordIds.length && !manualAdded.length && !manualExcluded.length) {
    return normalizeSceneCastSlotIds(scene.character_slot_ids);
  }
  const selected = new Set([...relationIds, ...keywordIds, ...manualAdded]);
  manualExcluded.forEach((slotId) => selected.delete(slotId));
  return [...selected];
}

function characterCardBySlotId(slotId = "") {
  const safe = text(slotId);
  if (!safe) return null;
  try {
    const core = globalThis.__characterCoreV2Api?.state?.();
    const slot = Array.isArray(core?.slots) ? core.slots.find((item) => text(item.slot_id) === safe) : null;
    if (slot) return {
      id: slot.slot_id,
      slot_id: slot.slot_id,
      person_id: slot.person_id,
      name: slot.display_name,
      display_name: slot.display_name,
      aliases: Array.isArray(slot.aliases) ? [...slot.aliases] : [],
      gender: slot.gender,
      role: slot.age?.visual_age_stage || "",
      appearance: slot.appearance || "",
    };
  } catch (_error) {}
  const legacy = (Array.isArray(state.characters) ? state.characters : []).find((person) => text(person.slot_id || person.id) === safe);
  return legacy || null;
}

function buildManualCastRow(slotId = "") {
  const person = characterCardBySlotId(slotId);
  if (!person) return null;
  return {
    slot_id: text(person.slot_id || person.id),
    person_id: text(person.person_id),
    display_name: text(person.name || person.display_name),
    scene_role: "visible",
    selection_source: "manual_add",
    matched_keywords: [],
    keyword_evidence: [],
    relationship_evidence: [],
    evidence: [{ type: "manual_add", keyword: text(person.name || person.display_name), reason: "用户人工增加本镜人物" }],
    confidence: 1,
  };
}

function applySceneEffectiveCast(scene = {}) {
  const effectiveIds = sceneEffectiveSlotIds(scene);
  const effectiveSet = new Set(effectiveIds);
  const rowMap = new Map();
  [
    ...(Array.isArray(scene.relation_cast_rows) ? scene.relation_cast_rows : []),
    ...(Array.isArray(scene.keyword_cast_rows) ? scene.keyword_cast_rows : []),
    ...(Array.isArray(scene.character_core_cast) ? scene.character_core_cast : []),
  ].forEach((row) => {
    const slotId = text(row?.slot_id);
    if (slotId && effectiveSet.has(slotId) && !rowMap.has(slotId)) rowMap.set(slotId, { ...row });
  });
  normalizeSceneCastSlotIds(scene.manual_added_slot_ids).forEach((slotId) => {
    if (!effectiveSet.has(slotId)) return;
    const manualRow = buildManualCastRow(slotId);
    if (manualRow) rowMap.set(slotId, manualRow);
  });
  effectiveIds.forEach((slotId) => {
    if (!rowMap.has(slotId)) {
      const row = buildManualCastRow(slotId);
      if (row) rowMap.set(slotId, row);
    }
  });
  const rows = effectiveIds.map((slotId) => rowMap.get(slotId)).filter(Boolean);
  scene.character_slot_ids = effectiveIds;
  scene.character_core_cast = rows;
  scene.characters = rows.map((row) => text(row.display_name)).filter(Boolean);
  scene.characters_mode = normalizeSceneCastSlotIds(scene.manual_added_slot_ids).length || normalizeSceneCastSlotIds(scene.manual_excluded_slot_ids).length ? "manual" : "auto";
  scene.characters_authoritative = true;
  scene.character_core_manual_locked = false;
  scene.preselected_cast_frozen = false;
  return scene;
}

globalThis.__applySceneEffectiveCastV77 = applySceneEffectiveCast;
globalThis.__sceneEffectiveSlotIdsV77 = sceneEffectiveSlotIds;

function castSourceLabel(scene = {}, slotId = "") {
  const relation = new Set(normalizeSceneCastSlotIds(scene.relation_selected_slot_ids));
  const keyword = new Set(normalizeSceneCastSlotIds(scene.keyword_selected_slot_ids));
  const added = new Set(normalizeSceneCastSlotIds(scene.manual_added_slot_ids));
  const excluded = new Set(normalizeSceneCastSlotIds(scene.manual_excluded_slot_ids));
  if (excluded.has(slotId)) return "人工排除";
  if (added.has(slotId)) return "人工增加";
  if (relation.has(slotId) && keyword.has(slotId)) return "关系图+关键词";
  if (relation.has(slotId)) return "关系图";
  if (keyword.has(slotId)) return "关键词";
  return "";
}

function commitSceneCharacterCheckbox(scene = {}, slotId = "", checked = false) {
  const safeSlotId = text(slotId);
  if (!scene || !safeSlotId) return;
  const automatic = new Set(sceneAutomaticSlotIds(scene));
  const added = new Set(normalizeSceneCastSlotIds(scene.manual_added_slot_ids));
  const excluded = new Set(normalizeSceneCastSlotIds(scene.manual_excluded_slot_ids));
  if (checked) {
    excluded.delete(safeSlotId);
    if (automatic.has(safeSlotId)) added.delete(safeSlotId);
    else added.add(safeSlotId);
  } else {
    added.delete(safeSlotId);
    if (automatic.has(safeSlotId)) excluded.add(safeSlotId);
    else excluded.delete(safeSlotId);
  }
  scene.manual_added_slot_ids = [...added];
  scene.manual_excluded_slot_ids = [...excluded];
  applySceneEffectiveCast(scene);
  scene.cast_snapshot_source = "relationship_plus_keyword_plus_manual_override";
  scene.cast_snapshot_at = new Date().toISOString();
  try { syncSceneCharactersToOutlineShots(scene.id); } catch (_error) {}
  try { clearFinalSegments(); } catch (_error) {}
  try { scheduleDraftSave(); } catch (_error) {}
  try { renderOutputs(); } catch (_error) {}
  console.info("[MANUAL_CAST_TRACE]", {
    scene_id: scene.id,
    slot_id: safeSlotId,
    checked,
    relation_selected_slot_ids: scene.relation_selected_slot_ids,
    keyword_selected_slot_ids: scene.keyword_selected_slot_ids,
    manual_added_slot_ids: scene.manual_added_slot_ids,
    manual_excluded_slot_ids: scene.manual_excluded_slot_ids,
    effective_slot_ids: scene.character_slot_ids,
  });
}

function renderScenes() {
  cleanState();
  renderSourceNotices();
  const container = $("#scenes");
  const template = $("#sceneTemplate");
  if (!container || !template) return;
  container.innerHTML = "";
  if (!state.scenes.length) {
    container.innerHTML = '<div class="empty-state">先让 AI 判断风格和人物，再按整段原文生成分镜/画面。</div>';
    return;
  }

  const fragment = document.createDocumentFragment();
  state.scenes.forEach((scene, index) => {
    const node = template.content.firstElementChild.cloneNode(true);
    node.dataset.sceneId = scene.id;
    node.querySelector(".scene-title").textContent = `分镜 ${index + 1}`;
    const textInput = node.querySelector('[data-field="text"]');
    const guidanceInput = node.querySelector('[data-field="guidance"]');
    const peopleBox = node.querySelector('[data-field="characters"]');
    const mappedOutline = node.querySelector('[data-field="mappedOutline"]');
    const warning = node.querySelector('[data-field="sceneWarning"]');
    textInput.value = scene.source_text || scene.text;
    textInput.readOnly = true;
    guidanceInput.value = scene.guidance || "";

    guidanceInput.addEventListener("input", () => {
      state.scenes[index].guidance = normalizeGuidance(guidanceInput.value);
      warning.textContent = "补充建议是当前这条分镜重新生成的最高修改要求，会直接左右新画面；软件会检查AI是否真的改动画面，不会把建议原样写进输出。";
      warning.classList.remove("hidden");
      scheduleDraftSave();
      // Hotfix28: guidance typing only updates this scene state. Re-rendering every
      // output card on each keystroke was a primary main-thread stall source.
    });

    migrateSceneCastIdsToCoreV16(scene);
    applySceneEffectiveCast(scene);
    const scenePeople = characterCoreScenePeopleV16();
    if (!scenePeople.length) {
      peopleBox.innerHTML = '<span class="muted">请先在第 2 步补充人物</span>';
    } else {
      const effectiveIds = new Set(sceneEffectiveSlotIds(scene));
      scenePeople.forEach((person) => {
        const label = document.createElement("label");
        label.className = "person-check";
        label.style.cursor = "pointer";
        const checkbox = document.createElement("input");
        checkbox.type = "checkbox";
        const personSlotId = text(person.slot_id || person.id);
        checkbox.checked = Boolean(personSlotId && effectiveIds.has(personSlotId));
        checkbox.dataset.sceneId = scene.id;
        checkbox.dataset.slotId = personSlotId;
        checkbox.addEventListener("change", () => {
          const activeScene = state.scenes.find((item) => item.id === scene.id) || state.scenes[index];
          commitSceneCharacterCheckbox(activeScene, personSlotId, checkbox.checked);
          const sourceTag = label.querySelector(".cast-source-tag");
          if (sourceTag) sourceTag.textContent = castSourceLabel(activeScene, personSlotId);
        });
        const nameNode = document.createTextNode(characterDisplayName(person));
        const sourceTag = document.createElement("small");
        sourceTag.className = "cast-source-tag";
        sourceTag.style.marginLeft = "4px";
        sourceTag.style.color = "#64748b";
        sourceTag.textContent = castSourceLabel(scene, personSlotId);
        label.append(checkbox, nameNode, sourceTag);
        peopleBox.appendChild(label);
      });
      const resetButton = document.createElement("button");
      resetButton.type = "button";
      resetButton.className = "mini-btn cast-reset-auto";
      resetButton.textContent = "恢复自动勾选";
      resetButton.style.marginLeft = "8px";
      resetButton.addEventListener("click", () => {
        const activeScene = state.scenes.find((item) => item.id === scene.id) || state.scenes[index];
        activeScene.manual_added_slot_ids = [];
        activeScene.manual_excluded_slot_ids = [];
        applySceneEffectiveCast(activeScene);
        try { syncSceneCharactersToOutlineShots(activeScene.id); } catch (_error) {}
        scheduleDraftSave();
        renderScenes();
        renderOutputs();
      });
      peopleBox.appendChild(resetButton);
    }

    renderMappedOutline(mappedOutline, scene);
    if (state.sourceDirty) {
      warning.textContent = "整段原文已改动，当前分镜和时间轴仍基于旧整段生成结果；请回到第 1 步重新按整段原文生成分镜/画面。";
      warning.classList.remove("hidden");
    } else if (text(state.sourceCompatibilityNotice)) {
      warning.textContent = text(state.sourceCompatibilityNotice);
      warning.classList.remove("hidden");
    } else if (normalizeSceneCastSlotIds(scene.manual_added_slot_ids).length || normalizeSceneCastSlotIds(scene.manual_excluded_slot_ids).length) {
      warning.textContent = `当前本镜人物已应用人工覆盖：人工增加 ${normalizeSceneCastSlotIds(scene.manual_added_slot_ids).length} 人，人工排除 ${normalizeSceneCastSlotIds(scene.manual_excluded_slot_ids).length} 人。重新生成这一条会使用当前最终勾选，不会由AI反向修改。`;
      warning.classList.remove("hidden");
    } else if (text(scene.character_inference_note)) {
      warning.textContent = `${text(scene.character_inference_note)}。如判断不准确，可手动勾选人物后再重新生成这一条。`;
      warning.classList.remove("hidden");
    } else {
      warning.classList.add("hidden");
    }

    node.querySelector(".move-up").addEventListener("click", () => {
      if (index === 0) return;
      [state.scenes[index - 1], state.scenes[index]] = [state.scenes[index], state.scenes[index - 1]];
      renderScenes();
      scheduleDraftSave();
    });

    node.querySelector(".move-down").addEventListener("click", () => {
      if (index === state.scenes.length - 1) return;
      [state.scenes[index + 1], state.scenes[index]] = [state.scenes[index], state.scenes[index + 1]];
      renderScenes();
      scheduleDraftSave();
    });

    node.querySelector(".generate-one").addEventListener("click", () => regenerateSceneOutline(scene.id));
    fragment.appendChild(node);
  });
  container.appendChild(fragment);
}

function formatOutlinePreview(shot) {
  return formatShotLine(shot);
}

function renderOutputs() {
  cleanState();
  renderSourceNotices();
  const container = $("#outputs");
  const template = $("#outputTemplate");
  if (!container || !template) return;
  container.innerHTML = "";
  if (!state.outlineShots.length) {
    container.className = "output-list empty-state";
    container.textContent = "生成后会显示整段时间轴镜头卡。";
    formatTotalDuration();
    return;
  }

  container.className = "output-list";
  const fragment = document.createDocumentFragment();
  state.scenes.forEach((scene, sceneIndex) => {
    const sceneShots = outlineShotsByScene(scene.id);
    if (!sceneShots.length) return;
    const group = document.createElement("section");
    group.className = "output-group";
    const head = document.createElement("div");
    head.className = "output-group-head";
    const title = document.createElement("strong");
    title.textContent = `分镜 ${sceneIndex + 1}`;
    const badge = document.createElement("span");
    badge.className = "count-badge";
    const segmentCount = sceneShots.reduce((sum, shot) => sum + (shot.timeline_segments?.length || 1), 0);
    badge.textContent = sceneShots.length === 1 ? `1 张画面卡 · ${segmentCount} 个时段` : `${sceneShots.length} 张画面卡`;
    head.append(title, badge);
    group.appendChild(head);

    sceneShots.forEach((shot, shotIndex) => {
      const node = template.content.firstElementChild.cloneNode(true);
      node.dataset.outputId = shot.id;
      node.querySelector(".output-title").textContent = sceneShots.length === 1 ? "完整画面提示词" : `画面卡 ${shotIndex + 1}/${sceneShots.length}`;
      const durationInput = node.querySelector('[data-field="duration"]');
      const promptInput = node.querySelector('[data-field="prompt"]');
      durationInput.value = shot.duration;
      if (Array.isArray(shot.timeline_segments) && shot.timeline_segments.length) {
        durationInput.min = "1";
        durationInput.max = "10";
      }
      promptInput.value = shot.prompt;
      node.querySelector(".output-scene").textContent = `全局时间：${shot.start_second}-${shot.end_second}s`;
      node.querySelector(".output-guidance").textContent = text(scene.guidance)
        ? `补充建议（当前分镜最高修改要求）：会和原文、当前完整画面、本镜人物及增强 Skill 一起进入AI；AI返回后会直接覆盖当前画面，本地诊断不再拒绝结果。当前摘要：${text(scene.guidance)}`
        : "补充建议：未填写。当前镜头按原文分镜和已有画面继续生成，不会把导演备注原样写进导出。";
      node.querySelector(".output-source").textContent = `原文分镜：${text(scene.source_text || scene.text)}`;
      node.querySelector(".output-meta").textContent = `镜头定位：${classifyShotPurpose(shot)} · ${shotMetaText(shot)}`;
      if (shot.lip_sync_fast) {
        node.querySelector(".output-meta").textContent += " · 当前唇语速度较快";
      }
      if (text(shot.timeline_validation_error)) {
        node.querySelector(".output-meta").textContent += ` · 时间格式错误：${text(shot.timeline_validation_error)}`;
      }
      node.querySelector(".format-preview").textContent = `最终格式预览：${formatOutlinePreview(shot)}`;

      durationInput.addEventListener("change", async () => {
        await updateShotDuration(shot.id, durationInput.value);
      });

      promptInput.addEventListener("input", () => {
        const nextPrompt = String(promptInput.value || "").slice(0, 12000);
        const synced = syncEditablePromptToTimeline(shot, nextPrompt, { source: "manual_prompt_input" });
        if (synced.ok && Array.isArray(shot.timeline_segments) && shot.timeline_segments.length) {
          recalculateOutlineTimelineFromIndex(state.outlineShots.findIndex((item) => item.id === shot.id));
        }
        node.querySelector(".format-preview").textContent = `最终格式预览：${formatOutlinePreview(shot)}`;
        clearFinalSegments();
        scheduleDraftSave();
      });

      group.appendChild(node);
    });
    fragment.appendChild(group);
  });
  container.appendChild(fragment);
  formatTotalDuration();
}


function characterLetterLabel(index) {
  const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  if (index < letters.length) return letters[index];
  const first = letters[Math.floor(index / letters.length) - 1] || "A";
  const second = letters[index % letters.length] || "A";
  return `${first}${second}`;
}

function buildUnifiedCharactersLine() {
  const items = (state.characters || []).filter((item) => text(item.name));
  if (!items.length) return "";
  return `统一人物：${items.map((character, index) => {
    const label = characterLetterLabel(index);
    const role = text(character.role);
    const appearance = text(character.appearance);
    const core = [role, appearance].filter(Boolean).join("：");
    return core ? `${text(character.name)}${label}（${core}）` : `${text(character.name)}${label}`;
  }).join("、")}`;
}

function buildVideoConstraintLines(rawText = "") {
  const lines = [];
  const current = currentVideoConstraintLines();
  if (!/【画面限制】/.test(rawText)) lines.push(current.picture);
  if (!/【画质约束】/.test(rawText)) lines.push(current.quality);
  return lines;
}

function enhanceFinalSegmentText(rawText = "") {
  const value = String(rawText || "").trim();
  if (!value) return "";
  const blocks = [];
  if (!/统一人物[：:]/.test(value)) {
    const charactersLine = buildUnifiedCharactersLine();
    if (charactersLine) blocks.push(charactersLine);
  }
  blocks.push(...buildVideoConstraintLines(value));
  blocks.push(value);
  return blocks.filter(Boolean).join("\n");
}

function allEnhancedSegmentText() {
  return state.segments.map((item) => enhanceFinalSegmentText(item.text)).filter(Boolean).join("\n\n");
}


function renderSegments() {
  const container = $("#segments");
  const warningBox = $("#mergeWarnings");
  if (!container || !warningBox) return;
  warningBox.innerHTML = "";
  const warningMessages = [...sourceNoticeMessages(), ...state.mergeWarnings];
  if (warningMessages.length) {
    warningBox.classList.remove("hidden");
    warningMessages.forEach((message) => {
      const line = document.createElement("p");
      line.textContent = message;
      warningBox.appendChild(line);
    });
  } else {
    warningBox.classList.add("hidden");
  }

  container.innerHTML = "";
  if (!state.segments.length) {
    container.className = "segments empty-state";
    container.textContent = "先生成整段时间轴，再点击“按秒数分段并合并”。";
    formatTotalDuration();
    return;
  }

  container.className = "segments";
  const template = $("#segmentTemplate");
  const fragment = document.createDocumentFragment();
  state.segments.forEach((segment, segmentIndex) => {
    const node = template.content.firstElementChild.cloneNode(true);
    node.dataset.segmentIndex = String(segmentIndex);
    node.querySelector(".segment-title").textContent = `第 ${segment.index} 段`;
    node.querySelector(".segment-meta").textContent = `本段 ${segment.total_seconds} 秒 · ${segment.scene_count} 个镜头`;
    const formattedSegmentText = enhanceFinalSegmentText(segment.text);
    const textarea = node.querySelector(".segment-text");
    textarea.value = formattedSegmentText;
    textarea.addEventListener("change", () => {
      state.segments[segmentIndex].text = textarea.value;
      scheduleDraftSave();
    });
    node.querySelector(".copy-segment").addEventListener("click", async () => {
      await copyText(textarea.value, node.querySelector(".copy-segment"));
    });
    fragment.appendChild(node);
  });
  container.appendChild(fragment);
  formatTotalDuration();
}

function clearPreviousAiAnalysisForFreshRun(novelText = "") {
  const source = text(novelText);
  const guideInput = text(readFieldValue("#characterGuideInput", state.character_guide_input)).slice(0, 1200);
  const sourceHash = buildCharacterSourceFingerprint(source);

  // 每次主动点击都先清理上一轮AI结果。人物引导输入属于用户输入，必须保留。
  resetCharacterRegistryForSource(source, { clearGuide: false });
  state.character_guide_input = guideInput;
  state.characterGuideSourceHash = guideInput ? sourceHash : "";
  state.characterRegistrySourceHash = sourceHash;
  state.lastNovelInputHash = sourceHash;
  state.sceneOptions = [];
  state.scenes = [];
  state.outlineShots = [];
  state.outputs = [];
  state.segments = [];
  state.outlineSourceText = "";
  state.sourceDirty = false;
  state.sourceCompatibilityNotice = "";
  state.styleAiSuggestions = createEmptyStyleSuggestions();
  state.characterAiSuggestions = createEmptyCharacterSuggestions();
  // 未锁定的内容类型与统一风格属于上一轮 AI 结果，主动重判时立即清空，避免旧结果残留或被误认为本轮结果。
  if (!state.styleLocks?.genre) writeFieldValue("#genre", "");
  if (!state.styleLocks?.trailer_style) writeFieldValue("#trailerStyle", "");

  renderCharacters();
  renderScenes();
  renderOutputs();
  clearFinalSegments();
}

function clearPreviousOutlineForFreshRun() {
  state.sceneOptions = [];
  state.scenes = [];
  state.outlineShots = [];
  state.outputs = [];
  state.segments = [];
  state.outlineSourceText = "";
  state.sourceDirty = false;
  state.sourceCompatibilityNotice = "";
  renderScenes();
  renderOutputs();
  clearFinalSegments();
}

async function analyzeNovel() {
  commitLatestEditableUiState("before_analysis_ai");
  const novelText = text(readFieldValue("#novelText"));
  if (!novelText) return apiError("请先粘贴整段原文。");
  const button = $("#analyzeBtn");
  setButtonBusy(button, true, "AI 判断中");
  try {
    // 每次点击都先清空上一轮人物、分镜和画面结果，再向AI发起一次全新请求。
    clearPreviousAiAnalysisForFreshRun(novelText);
    clearCurrentSourceCharacterSuppressions(novelText);
    prepareCharacterAnalysisSession(novelText);
    state.global_analysis_advice = text(readFieldValue("#globalAnalysisAdvice", state.global_analysis_advice)).slice(0, 1800);
    const analysisPayload = { novel_text: buildAnalysisNovelPayload(novelText) };
    const data = await postJSON("/api/analyze", analysisPayload);
    applyAnalysisResult(data);
    state.analysisSourceText = novelText;
    state.analysisComplete = true;
    renderCharacters();
    renderScenes();
    const guideSpec = readActiveCharacterGuideSpec(novelText);
    enforceCharacterGuideInvariant(novelText);
    const requiredGuideCards = fillGuideCharactersFromSource(guideSpec, novelText, state.characters || []);
    const missingGuideCards = requiredGuideCards.filter((required) => !state.characters.some((item) => strictCharacterIdentityMatch(item, required) || characterMatchesGuideBaseV37(item, required)));
    const guideExpectedCount = Math.max(guideSpec.requested_count || 0, requiredGuideCards.length);
    const guideAppliedCount = guideExpectedCount ? guideExpectedCount - missingGuideCards.length : 0;
    const guideStatus = guideExpectedCount ? `；人物卡引导要求 ${guideExpectedCount} 人，已落实 ${guideAppliedCount} 人` : "";
    if (missingGuideCards.length) {
      showAIStatusNotice(`人物识别未完成：最终生成 ${state.characters.length} 张人物卡${guideStatus}；仍缺少：${missingGuideCards.map((item) => item.name).join("、")}。请检查强制名单是否为中文人物名称；软件不会用英文、物品或句子残片代替缺失人物。`, "warning", 15000);
    } else {
      showAIStatusNotice(`人物识别、阶段卡与外形 Skill 完成：最终生成 ${state.characters.length} 张阶段人物卡${guideStatus}；强制名单只锁定正式人物身份，同一人物跨年龄会自动拆卡；无卡临时配角、环境群体、系统界面与系统精灵不建卡但会在分镜中落实；本次主动重新识别已清除当前原文的删除抑制记录，被删人物可以重新生成；英文名、物品、地点、系统界面和句子残片会被过滤；人物外形已按时代、身份与题材生成高质量稳定锚点；内容类型已由AI自由判断并统一为“XXXX短剧”；统一风格附加视觉信息已通过十一字段模板自动校正，完整覆盖电影质感、实拍、颗粒、滤镜、镜头、噪点、对比度、饱和度、光线层次、叙事构图与氛围感；本次为全新AI请求，未读取任何历史生成结果。`, "ready", 14000);
    }
    scheduleDraftSave();
  } catch (error) {
    apiError(error.message);
  } finally {
    setButtonBusy(button, false);
  }
}

function v7827CleanSceneMeta(value = "") {
  return text(value)
    .replace(/(?:与原文时代一致的)?主要实景空间/g, "")
    .replace(/根据原文可见环境确定具体子空间/g, "")
    .replace(/原文明示的(?:门厅、客厅、庭院或其他子空间|入口、宾客区、主桌或仪式区域)/g, "")
    .replace(/原文对应(?:科室、诊区或病房|办公区域|教学或活动区域|席位或证据展示区|调查或检验区域|殿堂、回廊、庭院或门廊|宗门或修炼区域|操作或实验区域|安全区或废墟位置|路口或人行区域)/g, "")
    .replace(/原文人物所在座位/g, "")
    .replace(/[｜|]{2,}/g, "｜")
    .replace(/^\s*[｜|]\s*|\s*[｜|]\s*$/g, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function v7827ConcreteSubspaceFromSource(raw = "") {
  const source=text(raw);
  const choices=[
    [/告别厅|灵堂|吊唁厅/, "告别厅内"],
    [/殡仪馆|侯仪馆/, "殡仪馆告别空间内"],
    [/病房/, "医院病房内"], [/诊室/, "医院诊室内"], [/候诊/, "医院候诊区"], [/挂号/, "医院挂号区"],
    [/会议室|董事会/, "公司会议室内"], [/办公室|工位/, "办公区内"],
    [/教室/, "教室内"], [/操场/, "校园操场"], [/宿舍/, "宿舍内"],
    [/门厅|玄关/, "宅邸门厅内"], [/客厅|沙发|茶几/, "客厅内"], [/书房/, "书房内"], [/庭院|院子/, "庭院内"], [/卧室|床头|衣柜/, "卧室内"], [/厨房|灶台|水槽/, "厨房内"],
    [/宴会厅|酒会|订婚宴|婚礼|庆功宴/, "宴会厅内"], [/包厢/, "餐厅包厢内"], [/餐厅/, "餐厅内"],
    [/法庭|律师席/, "法庭内"], [/审讯/, "审讯室内"], [/警局/, "警局内"], [/法医|证物/, "检验或证物空间内"],
    [/寝殿/, "宫廷寝殿内"], [/朝堂/, "朝堂内"], [/宫门/, "宫门外"], [/侯府|相府/, "古代府邸内"], [/皇宫|宫殿/, "宫廷内"],
    [/山门/, "宗门山门前"], [/宗门|仙门/, "宗门内"], [/秘境/, "秘境内"],
    [/实验室/, "实验室内"], [/飞船|星舰/, "飞船舱内"], [/避难所|基地/, "避难所或基地内"], [/废墟/, "废墟外景"],
    [/车内|驾驶座|副驾驶|后座/, "车辆内"], [/街道|马路|人行道/, "城市街道外景"], [/路口|巷口/, "城市路口外景"],
  ];
  const hit=choices.find(([pattern])=>pattern.test(source));
  return hit?hit[1]:"";
}

function inferSceneContextFromSourceLine(sourceLine = "", previousContext = "") {
  const raw = text(sourceLine);
  const previous = v7827CleanSceneMeta(previousContext);
  const explicit = raw.match(/(?:在|来到|走进|走到|回到|抵达|进入|站在|坐在|停在)([^，。！？!?]{2,42}(?:客厅|卧室|厨房|玄关|门口|走廊|办公室|会议室|教室|操场|医院|诊室|病房|大厅|庄园|别墅|宴会厅|餐厅|包厢|法庭|警局|街道|路口|车内|车外|机场|站台|宫殿|寝殿|侯府|宗门|山门|森林|实验室|避难所|战场|院子|庭院|书房|阳台|楼梯|电梯|告别厅|灵堂|殡仪馆|侯仪馆))([^，。！？!?]{0,18})/);
  if (explicit) {
    const place = text(explicit[1]);
    const tail = text(explicit[2]);
    return v7827CleanSceneMeta(tail ? `${place}｜${tail}` : place);
  }
  const concrete=v7827ConcreteSubspaceFromSource(raw);
  if(concrete){
    if(previous&&!/(来到|走进|回到|抵达|进入|另一边|与此同时|电话另一端|回忆|梦境|前世|监控|视频画面)/.test(raw)){
      const prevMain=previous.split(/[｜|]/)[0];
      if(prevMain&&concrete.includes(prevMain))return concrete;
    }
    return concrete;
  }
  // 没有可验证地点时宁可继承上一镜或留空，也不制造“根据原文确定子空间”元指令。
  return previous || "";
}

function v7827LooksLikeConcreteScene(value = "") {
  const scene=v7827CleanSceneMeta(value);
  if(!scene)return false;
  if(/^(?:冷调|暖调|青灰|暖灰|冷灰|柔光|硬光|光线|光影|色调|氛围|电影感)/.test(scene) && !/(厅|馆|室|房|院|庭|门|廊|楼|街|路|车|场|宫|府|宗门|山门|校园|医院|公司|办公室|教室|实验室|基地|废墟|外景|内景|内$|外$)/.test(scene))return false;
  return /(厅|馆|室|房|院|庭|门|廊|楼|街|路|车|场|宫|府|宗门|山门|校园|医院|公司|办公室|教室|实验室|基地|废墟|外景|内景|内$|外$)/.test(scene);
}

function normalizeConcreteSceneContext(value = "", sourceLine = "", previousContext = "", body = "") {
  const incoming=text(value).replace(/^场景[：:]\s*/, "");
  const hadMeta=/(根据原文可见环境确定具体子空间|原文对应|原文明示的|主要实景空间|人物当前站位)/.test(incoming);
  let scene = v7827CleanSceneMeta(incoming);
  if (hadMeta || !v7827LooksLikeConcreteScene(scene) || /^(?:当前场景连续|当前场景|某处|室内|室外|根据上下文)$/.test(scene)) {
    const bodyScene = v7827CleanSceneMeta(inferSceneFromBody(body));
    scene = v7827LooksLikeConcreteScene(bodyScene) && bodyScene !== "当前场景连续" ? bodyScene : "";
  }
  if (!scene) scene = inferSceneContextFromSourceLine(sourceLine, previousContext);
  // 只有从原文能得到真实子空间时才补充，不再拼接任何“原文对应/根据原文”占位。
  if (scene && !/[｜|]/.test(scene)) {
    const concrete=v7827ConcreteSubspaceFromSource(sourceLine);
    if(concrete && concrete!==scene && !scene.includes(concrete) && !concrete.includes(scene)) scene=`${scene}｜${concrete}`;
  }
  return v7827CleanSceneMeta(scene).slice(0, 240);
}

function v7827SanitizePromptMetaLeak(value = "", sourceLine = "", visualContext = "") {
  let result=String(value||"");
  const before=result;
  result=result
    .replace(/(?:[^，。；;]{0,24}光线)?(?:的)?根据原文可见环境确定具体子空间/g, "")
    .replace(/原文明示的(?:门厅、客厅、庭院或其他子空间|入口、宾客区、主桌或仪式区域)/g, "")
    .replace(/原文对应(?:科室、诊区或病房|办公区域|教学或活动区域|席位或证据展示区|调查或检验区域|殿堂、回廊、庭院或门廊|宗门或修炼区域|操作或实验区域|安全区或废墟位置|路口或人行区域)/g, "")
    .replace(/(?:与原文时代一致的)?主要实景空间/g, "")
    .replace(/人物当前站位/g, "");
  result=result.replace(/，{2,}/g,"，").replace(/。{2,}/g,"。").replace(/\s{2,}/g," ").trim();
  const ctx=v7827CleanSceneMeta(visualContext)||inferSceneContextFromSourceLine(sourceLine,"");
  if(before!==result && ctx && !result.includes(ctx.split(/[｜|]/)[0])){
    result=`${ctx.replace(/[｜|]/g,"的")}，${result}`.replace(/，{2,}/g,"，");
  }
  return result;
}

function normalizedSourceComparable(value = "") {
  return text(value).replace(/[\s，,。.!！？?；;：:、“”\"'‘’]/g, "");
}

function chooseSourceLineIndexForShot(shot = {}, returnedScenes = [], sourceScenes = [], fallbackIndex = 0) {
  const parentId = text(shot.parent_scene_id) || text((shot.parent_scene_ids || [])[0]);
  const parent = returnedScenes.find((scene) => text(scene.id) === parentId);
  const basis = text(shot.source_basis || parent?.source_text || parent?.text);
  const key = normalizedSourceComparable(basis);
  if (key) {
    let best = -1;
    let bestScore = 0;
    sourceScenes.forEach((scene, index) => {
      const target = normalizedSourceComparable(scene.source_text);
      if (!target) return;
      const score = key === target ? 100000 : key.includes(target) ? target.length : target.includes(key) ? key.length : 0;
      if (score > bestScore) { best = index; bestScore = score; }
    });
    if (best >= 0) return best;
  }
  const sourceIndex = Number.parseInt(parent?.source_index || shot.source_index, 10);
  if (sourceIndex > 0 && sourceIndex <= sourceScenes.length) return sourceIndex - 1;
  return Math.max(0, Math.min(sourceScenes.length - 1, fallbackIndex));
}

function shotSizeSequenceForLineV37(sourceLine = "", count = 1, plan = {}) {
  const source = text(sourceLine);
  let sequence = ["中景", "中近景", "近景", "局部特写"];
  if ((plan.system_entities || []).length || (plan.system_sprites || []).length) sequence = ["中景", "主观中景", "局部特写", "近景"];
  else if (/(?:来到|走进|进入|抵达|推开.*门|新的|另一边|多年后|回忆里|梦中|与此同时)/.test(source)) sequence = ["中远景", "中景", "中近景", "近景"];
  else if (/冲|跑|追|推|拉|砸|撞|扑|起身|转身|走到|挥|夺|抢|抱|跪|倒下|崩|击|射|刺|砍|打|扇|泼/.test(source)) sequence = ["中远景", "全身景", "局部特写", "近景"];
  else if (/说|问|喊|回答|质问|怒斥|开口|声音/.test(source) && ((plan.allowed || []).length + (plan.temporary_characters || []).length >= 2)) sequence = ["双人中景", "过肩中近景", "反打近景", "物件特写"];
  else if (/手机|合同|名单|照片|戒指|钥匙|门把手|指纹|证据|文件|药瓶|信件|按钮|屏幕/.test(source)) sequence = ["中景", "物件特写", "中近景", "近景"];
  else if ((plan.crowd_characters || []).length) sequence = ["群像全景", "中景", "中近景", "近景"];
  else if (/忽然|猛地|发现|看见|愣住|僵住|震惊|眼神|手指/.test(source)) sequence = ["中近景", "近景", "大特写", "中景"];
  if (count <= 1) return [sequence[0]];
  return Array.from({ length: count }, (_, index) => sequence[Math.min(index, sequence.length - 1)]);
}

function normalizeShotSizeDiversityV37(segments = [], sourceLine = "", plan = {}, previousPrimary = "", repeatedPrimary = 0) {
  const items = (segments || []).map((item) => ({ ...item }));
  if (!items.length) return { segments: items, primary: previousPrimary, repeated: repeatedPrimary };
  const current = items.map((item) => text(item.shot_size));
  const nonEmpty = current.filter(Boolean);
  const allSame = nonEmpty.length === items.length && new Set(nonEmpty).size === 1;
  const missing = nonEmpty.length !== items.length;
  const suggested = shotSizeSequenceForLineV37(sourceLine, items.length, plan);
  if (missing || (items.length >= 2 && allSame)) {
    items.forEach((item, index) => { item.shot_size = suggested[index] || suggested[suggested.length - 1] || "中景"; });
  } else if (items.length >= 3) {
    for (let index = 2; index < items.length; index += 1) {
      if (text(items[index].shot_size) && text(items[index].shot_size) === text(items[index - 1].shot_size) && text(items[index].shot_size) === text(items[index - 2].shot_size)) {
        items[index].shot_size = suggested[index] && suggested[index] !== items[index - 1].shot_size ? suggested[index] : "近景";
      }
    }
  }
  let primary = text(items[0].shot_size) || suggested[0] || "中景";
  let repeated = primary === previousPrimary ? repeatedPrimary + 1 : 1;
  if (items.length === 1 && repeated >= 3) {
    const alternatives = suggested.filter((item) => item && item !== previousPrimary);
    if (alternatives.length) {
      items[0].shot_size = alternatives[0];
      primary = alternatives[0];
      repeated = 1;
    }
  }
  return { segments: items, primary, repeated };
}


function temporaryCharacterToken(item = {}) {
  return text(item.source_phrase || item.label || item.identity || item.entity_type);
}

function temporaryCharacterVisualClause(_item = {}) {
  return "";
}

function ensureTemporaryCharactersInShotList(shots = [], _temporaryCharacters = [], sourceText = "", sceneGroup = "temp_scene_1", sourceKey = "") {
  const nextShots = (shots || []).map((rawShot) => {
    const shot = makeOutlineShot(rawShot);
    const current = Array.isArray(rawShot?.temporary_characters) ? rawShot.temporary_characters : [];
    shot.temporary_characters = v7824AiPrimaryTemporary(current, sourceText || shot.source_basis, sceneGroup, sourceKey || shot.source_key);
    return shot;
  });
  return { shots: nextShots, applied: 0, missing_count: 0, required_count: 0 };
}

function enforceTemporaryCharactersForOutline(lineCharacterPlans = []) {
  state.outlineShots = (state.outlineShots || []).map((rawShot) => {
    const sourceIndex = Math.max(1, Number(rawShot.source_index || 1));
    const plan = lineCharacterPlans[sourceIndex - 1] || {};
    const scene = (state.scenes || [])[sourceIndex - 1] || {};
    const group = text(plan.temporary_scene_group || scene.temporary_scene_group || `temp_scene_${sourceIndex}`);
    const sourceKey = text(rawShot.source_key || scene.source_key || plan.source_key);
    const aiReturned = (rawShot.temporary_characters || []).filter((item) => item?.ai_discovered === true || item?.selection_source_v7824 === "ai_primary" || item?.manual_added_v7824 === true);
    return { ...rawShot, temporary_characters: v7824AiPrimaryTemporary(aiReturned, plan.source_text || rawShot.source_basis || scene.source_text, group, sourceKey) };
  });
  state.scenes = (state.scenes || []).map((scene, index) => {
    const plan = lineCharacterPlans[index] || {};
    const group = text(plan.temporary_scene_group || scene.temporary_scene_group || `temp_scene_${index + 1}`);
    const sourceKey = text(scene.source_key || plan.source_key);
    const shotTemps = outlineShotsByScene(scene.id).flatMap((shot) => shot.temporary_characters || []);
    const aiOnly = [...(scene.temporary_characters || []), ...shotTemps].filter((item) => item?.ai_discovered === true || item?.selection_source_v7824 === "ai_primary" || item?.manual_added_v7824 === true);
    const finalTemps = v7824AiPrimaryTemporary(aiOnly, scene.source_text, group, sourceKey);
    return { ...scene, temporary_scene_group: group, temporary_characters: finalTemps, temporary_judge_v7824: "ai_primary", manual_temporary_characters_v7824: v7824ManualTemporaryForScene(sourceKey) };
  });
  return 0;
}

function cloneValueV16(value) {
  try { return typeof structuredClone === "function" ? structuredClone(value) : JSON.parse(JSON.stringify(value)); }
  catch (_error) { return value; }
}

function outlineCoverageBySourceV16(data = {}, novelText = "") {
  const sourceScenes = splitOutlineSourceScenes(novelText);
  const returnedScenes = Array.isArray(data?.scenes) ? data.scenes : [];
  const returnedShots = Array.isArray(data?.outline_shots) ? data.outline_shots : [];
  const groups = sourceScenes.map(() => []);
  returnedShots.forEach((shot, index) => {
    const targetIndex = chooseSourceLineIndexForShot(shot, returnedScenes, sourceScenes, Math.min(index, Math.max(0, sourceScenes.length - 1)));
    if (groups[targetIndex]) groups[targetIndex].push(shot);
  });
  if (returnedShots.length === sourceScenes.length && groups.some((group) => group.length !== 1)) {
    groups.forEach((group) => group.splice(0));
    returnedShots.forEach((shot, index) => { if (groups[index]) groups[index].push(shot); });
  }
  const coverage = sourceScenes.map((scene, index) => {
    const group = groups[index] || [];
    const validShots = group.filter((rawShot) => {
      const shot = makeOutlineShot(rawShot);
      const segments = fallbackTimelineSegmentsFromShot(shot);
      return segments.some((segment) => text(segment?.prompt || shot?.prompt));
    });
    return {
      source_index: index + 1,
      source_key: buildSceneSourceKey(scene.source_text, index + 1),
      source_text: scene.source_text,
      returned_count: group.length,
      valid_count: validShots.length,
      complete: validShots.length > 0,
    };
  });
  return { sourceScenes, groups, coverage, missing: coverage.filter((item) => !item.complete) };
}

function remapSupplementalOutlineV16(data = {}, missing = []) {
  const result = cloneValueV16(data) || {};
  const missingByText = new Map(missing.map((item) => [normalizeOutlineCompareText(item.source_text), item]));
  const missingByRelative = new Map(missing.map((item, index) => [index + 1, item]));
  result.outline_shots = (Array.isArray(result.outline_shots) ? result.outline_shots : []).map((rawShot, index) => {
    const shot = { ...rawShot };
    const sourceText = text(shot.source_basis || shot.source_text || shot.text);
    let target = missingByText.get(normalizeOutlineCompareText(sourceText));
    if (!target) target = missingByRelative.get(Number(shot.source_index || 0));
    if (!target) target = missing[Math.min(index, missing.length - 1)];
    if (target) {
      shot.source_index = target.source_index;
      shot.source_basis = target.source_text;
      shot.source_key = target.source_key;
    }
    return shot;
  });
  result.scenes = (Array.isArray(result.scenes) ? result.scenes : []).map((rawScene, index) => {
    const scene = { ...rawScene };
    const sourceText = text(scene.source_text || scene.text);
    let target = missingByText.get(normalizeOutlineCompareText(sourceText));
    if (!target) target = missingByRelative.get(Number(scene.source_index || 0));
    if (!target) target = missing[Math.min(index, missing.length - 1)];
    if (target) {
      scene.source_index = target.source_index;
      scene.source_text = target.source_text;
      scene.source_key = target.source_key;
    }
    return scene;
  });
  return result;
}

