function sceneCastIdMigrationMapV16() {
  const corePeople = characterCoreScenePeopleV16();
  const valid = new Set(corePeople.map((person) => text(person.slot_id)).filter(Boolean));
  const byPerson = new Map();
  const byName = new Map();
  corePeople.forEach((person) => {
    if (text(person.person_id)) byPerson.set(text(person.person_id), text(person.slot_id));
    uniqueTextList([person.name, person.display_name, ...(Array.isArray(person.aliases) ? person.aliases : [])]).forEach((name) => {
      const key = normalizeOutlineCompareText(name);
      if (key && !byName.has(key)) byName.set(key, text(person.slot_id));
    });
  });
  const legacyById = new Map((Array.isArray(state.characters) ? state.characters : []).map((person) => [text(person.slot_id || person.id), person]));
  const migrate = (rawId) => {
    const id = text(rawId);
    if (!id) return "";
    if (valid.has(id)) return id;
    const legacy = legacyById.get(id);
    if (legacy) {
      const personId = text(legacy.person_id);
      if (personId && byPerson.has(personId)) return byPerson.get(personId);
      const names = uniqueTextList([legacy.name, legacy.display_name, ...(Array.isArray(legacy.aliases) ? legacy.aliases : [])]);
      for (const name of names) {
        const mapped = byName.get(normalizeOutlineCompareText(name));
        if (mapped) return mapped;
      }
    }
    return "";
  };
  return { migrate, valid, corePeople };
}

function migrateSceneCastIdsToCoreV16(scene = {}) {
  const { migrate } = sceneCastIdMigrationMapV16();
  const fields = ["relation_selected_slot_ids", "keyword_selected_slot_ids", "manual_added_slot_ids", "manual_excluded_slot_ids", "character_slot_ids"];
  fields.forEach((field) => {
    scene[field] = uniqueTextList((Array.isArray(scene[field]) ? scene[field] : []).map((id) => migrate(id) || text(id)).filter(Boolean));
  });
  ["relation_cast_rows", "keyword_cast_rows", "character_core_cast"].forEach((field) => {
    scene[field] = (Array.isArray(scene[field]) ? scene[field] : []).map((row) => ({ ...row, slot_id: migrate(row?.slot_id) || text(row?.slot_id) })).filter((row) => text(row.slot_id));
  });
  return scene;
}

function migrateAllSceneCastIdsToCoreV16() {
  (Array.isArray(state.scenes) ? state.scenes : []).forEach((scene) => {
    migrateSceneCastIdsToCoreV16(scene);
    applySceneEffectiveCast(scene);
  });
}

function canonicalizeOutlineToSourceLines(data = {}, novelText = "", lineCharacterPlans = []) {
  const sourceScenes = splitOutlineSourceScenes(novelText);
  if (!sourceScenes.length) return { scenes: [], outline_shots: [] };
  const returnedScenes = Array.isArray(data.scenes) ? data.scenes : [];
  const returnedShots = Array.isArray(data.outline_shots) ? data.outline_shots : [];
  const groups = sourceScenes.map(() => []);
  returnedShots.forEach((shot, index) => {
    const targetIndex = chooseSourceLineIndexForShot(shot, returnedScenes, sourceScenes, Math.min(index, sourceScenes.length - 1));
    groups[targetIndex].push(shot);
  });

  // When AI returned one card per line but source matching was weak, preserve strict index alignment.
  if (returnedShots.length === sourceScenes.length && groups.some((group) => group.length !== 1)) {
    groups.forEach((group) => group.splice(0));
    returnedShots.forEach((shot, index) => groups[index].push(shot));
  }

  let absoluteCursor = 0;
  const scenes = sourceScenes.map((scene, index) => {
    const plan = lineCharacterPlans[index] || {};
    const hasPlan = Array.isArray(plan.allowed);
    return makeScene(scene.source_text, {
      ...scene,
      id: `scene_${index + 1}`,
      source_index: index + 1,
      source_key: text(plan.source_key) || buildSceneSourceKey(scene.source_text, index + 1),
      source_context: index ? sourceScenes[index - 1].source_text : "",
      next_context: index < sourceScenes.length - 1 ? sourceScenes[index + 1].source_text : "",
      characters: hasPlan ? uniqueTextList(plan.allowed) : [],
      character_slot_ids: hasPlan ? uniqueTextList(plan.character_slot_ids || []) : [],
      relation_selected_slot_ids: hasPlan ? uniqueTextList(plan.relation_selected_slot_ids || []) : [],
      keyword_selected_slot_ids: hasPlan ? uniqueTextList(plan.keyword_selected_slot_ids || []) : [],
      manual_added_slot_ids: hasPlan ? uniqueTextList(plan.manual_added_slot_ids || []) : [],
      manual_excluded_slot_ids: hasPlan ? uniqueTextList(plan.manual_excluded_slot_ids || []) : [],
      relation_cast_rows: hasPlan ? (plan.relation_cast_rows || []) : [],
      keyword_cast_rows: hasPlan ? (plan.keyword_cast_rows || []) : [],
      character_core_cast: hasPlan ? (plan.character_core_context?.selected_characters || plan.character_packages || []) : [],
      character_casting_evidence: hasPlan ? uniqueTextList((plan.keyword_evidence || []).map((item) => item?.reason || item?.keyword || "")) : [],
      characters_mode: hasPlan ? normalizeSceneCharactersMode(plan.characters_mode) : "auto",
      characters_authoritative: hasPlan,
      character_inference_note: hasPlan
        ? (plan.whitelist_source === "current_scene_selection" ? "已按当前本镜人物勾选名单锁定实体出镜人物与正确阶段卡" : "已按当前行语义区分正式人物、年龄阶段、临时配角、系统实体与仅被提及人物")
        : "",
      stage_bindings: plan.stage_bindings || [],
      temporary_characters: v7824AiPrimaryTemporary((returnedScenes[index]?.temporary_characters || []), scene.source_text, plan.temporary_scene_group || `temp_scene_${index + 1}`, text(plan.source_key) || buildSceneSourceKey(scene.source_text, index + 1)),
      crowd_characters: plan.crowd_characters || [],
      system_entities: plan.system_entities || [],
      system_sprites: plan.system_sprites || [],
      shot_strategy: plan.shot_strategy || "",
      temporary_scene_group: plan.temporary_scene_group || `temp_scene_${index + 1}`,
    });
  });
  const outlineShots = [];
  let lastVisualContext = "";
  let previousPrimaryShotSize = "";
  let repeatedPrimaryShotSize = 0;

  scenes.forEach((scene, index) => {
    const group = groups[index];
    if (!group.length) return;
    let segments = [];
    let localCursor = 0;
    group.forEach((rawShot) => {
      fallbackTimelineSegmentsFromShot(makeOutlineShot(rawShot)).forEach((rawSegment) => {
        if (localCursor >= 10) return;
        const duration = Math.max(1, Math.min(4, Number(rawSegment.end_offset) - Number(rawSegment.start_offset) || 1, 10 - localCursor));
        const visualContext = normalizeConcreteSceneContext(
          rawSegment.visual_context || rawShot.visual_context || segments[segments.length - 1]?.visual_context,
          scene.source_text,
          segments[segments.length - 1]?.visual_context || lastVisualContext,
          rawSegment.prompt || rawShot.prompt,
        );
        const cleanPrompt = v7827SanitizePromptMetaLeak(rawSegment.prompt || rawShot.prompt || "", scene.source_text, visualContext);
        segments.push({ ...rawSegment, prompt: cleanPrompt, start_offset: localCursor, end_offset: localCursor + duration, visual_context: visualContext });
        lastVisualContext = visualContext || lastVisualContext;
        localCursor += duration;
      });
    });
    if (!segments.length) return;
    const plan = lineCharacterPlans[index] || {};
    const shotSizeNormalized = normalizeShotSizeDiversityV37(segments, scene.source_text, plan, previousPrimaryShotSize, repeatedPrimaryShotSize);
    segments = shotSizeNormalized.segments;
    previousPrimaryShotSize = shotSizeNormalized.primary;
    repeatedPrimaryShotSize = shotSizeNormalized.repeated;
    const first = group[0];
    const aiCharacters = uniqueTextList(group.flatMap((item) => item.characters || item.scene_characters || []));
    const aiVisibleCharacters = uniqueTextList(group.flatMap((item) => item.visible_characters || item.characters || []));
    const characters = Array.isArray(plan.allowed) ? uniqueTextList(plan.allowed) : aiCharacters;
    const visibleCharacters = Array.isArray(plan.allowed) ? uniqueTextList(plan.allowed) : aiVisibleCharacters;
    const shot = makeOutlineShot({
      ...first,
      id: `shot_line_${index + 1}`,
      parent_scene_id: scene.id,
      parent_scene_ids: [scene.id],
      source_basis: scene.source_text,
      source_index: index + 1,
      start_second: absoluteCursor,
      end_second: absoluteCursor + localCursor,
      duration: localCursor,
      characters,
      scene_characters: characters,
      visible_characters: visibleCharacters,
      stage_bindings: plan.stage_bindings || [],
      temporary_characters: v7824AiPrimaryTemporary(group.flatMap((item) => Array.isArray(item?.temporary_characters) ? item.temporary_characters : []), scene.source_text, plan.temporary_scene_group || `temp_scene_${index + 1}`, text(plan.source_key) || text(scene.source_key)),
      crowd_characters: plan.crowd_characters || [],
      system_entities: plan.system_entities || [],
      system_sprites: plan.system_sprites || [],
      shot_strategy: plan.shot_strategy || "",
      shot_size: text(segments[0]?.shot_size),
      timeline_segments: segments,
      prompt: timelinePrompt(segments),
    });
    absoluteCursor += Math.max(1, localCursor);
    outlineShots.push(shot);
    scene.outline_shot_ids = [shot.id];
    scene.visual_context = text(segments[0]?.visual_context);
    scene.temporary_characters = v7824AiPrimaryTemporary(shot.temporary_characters || [], scene.source_text, plan.temporary_scene_group || `temp_scene_${index + 1}`, text(scene.source_key));
    scene.temporary_judge_v7824 = "ai_primary";
    scene.manual_temporary_characters_v7824 = v7824ManualTemporaryForScene(text(scene.source_key));
  });
  return { scenes, outline_shots: outlineShots };
}

function temporaryCastDiagnosticsV22(lineCharacterPlans = []) {
  const issues = [];
  (Array.isArray(state.scenes) ? state.scenes : []).forEach((scene, index) => {
    const plan = lineCharacterPlans[index] || {};
    const required = temporaryVisibleCastV22(scene.temporary_characters || []);
    if (!required.length) return;
    const shots = outlineShotsByScene(scene.id);
    const promptText = shots.map((shot) => formatShotLine(shot)).join("\n");
    const returned = mergeTemporaryCharactersV22([], shots.flatMap((shot) => shot.temporary_characters || []), scene.source_text, plan.temporary_scene_group || `temp_scene_${index + 1}`);
    const renderedIds = new Set(returned.filter((item) => item.rendered === true).map((item) => text(item.continuity_id || item.label)));
    const missing = required.filter((item) => {
      const token = text(item.source_phrase || item.label);
      const label = text(item.label);
      return !renderedIds.has(text(item.continuity_id || item.label)) && !(label && promptText.includes(label)) && !(token && promptText.includes(token));
    });
    if (missing.length) issues.push({ source_index: index + 1, source_key: text(scene.source_key), missing: missing.map((item) => item.label), required: required.map((item) => item.label) });
  });
  if (issues.length) console.warn("[TEMP_CAST_TRACE] 临时人物存在未明确落实项（仅诊断，不阻拦）", issues);
  else console.info("[TEMP_CAST_TRACE] 临时人物实体落实检查通过");
  return issues;
}

