    const plan = plans[index] || {};
    return { ...scene, characters: uniqueTextList(plan.allowed || []), characters_mode: "auto", characters_authoritative: false, character_inference_note: "已按主角、别称、实际出镜语义与唯一年龄阶段自动勾选" };
