      const aliasOfSelf = v49AliasEvidence("我", base, source);
      if (aliasOfSelf) return;
      const meta = v49CandidateMentionScore(base, source);
      if (meta.score >= 6 || meta.dialogue || (meta.active && meta.count >= 1)) result.push(base);
