function v52PersonNodes(cards = state.characters) {
  const byId = new Map();
  (cards || []).map(normalizeCharacterRecord).forEach((card) => {
    if (!card.base_person_id || !card.base_name) return;
    const existing = byId.get(card.base_person_id) || {
      node_id: card.base_person_id,
      base_name: card.base_name,
      display_name: card.base_name,
      slot_ids: [],
      stage_cards: [],
      identity_hints: [],
      node_type: "forced_person",
    };
    existing.slot_ids = v52Unique([...existing.slot_ids, card.slot_id]);
    existing.stage_cards.push({ slot_id: card.slot_id, name: card.name, display_name: characterDisplayName(card), stage_key: card.stage_key, stage_label: card.stage_label });
    existing.identity_hints = v52Unique([...existing.identity_hints, card.identity_hint, ...(card.identity_descriptors || [])]);
    byId.set(card.base_person_id, existing);
  });
  return [...byId.values()];
}

function v52IdentityTokens(node = {}) {
  const noisy = /^(?:主角|女主|男主|配角|重要人物|人物|成年|少女|少年|儿童|中年|老年)$/;
  const hintTokens = (node.identity_hints || []).flatMap((value) => String(value || "").split(/[、,，|｜/；;\s]+/));
  return v52Unique([node.base_name, ...hintTokens]).filter((token) => token && !noisy.test(token));
}

function v52ResolveNodeByLabel(label = "", nodes = []) {
  const raw = v52Text(label);
  if (!raw) return null;
  const base = sanitizeCharacterIdentityName(characterBaseName(raw));
  return nodes.find((node) => node.node_id === raw || node.base_name === base || v52IdentityTokens(node).includes(raw) || v52IdentityTokens(node).includes(base)) || null;
}

function v52MentionEntity(label = "", type = "person_mention") {
  const clean = v52Text(label) || "未命名人物";
  return { entity_id: v52SafeId("mention", clean), label: clean, entity_type: type, node_type: "mention_only" };
}

function v52NormalizeRelationEdge(raw = {}, nodes = [], mentions = []) {
  const sourceLabel = v52Text(raw.source_node_id || raw.subject_node_id || raw.subject_base || raw.subject || raw.source);
  const targetLabel = v52Text(raw.target_node_id || raw.object_node_id || raw.object_base || raw.object || raw.object_label || raw.target);
  const sourceNode = v52ResolveNodeByLabel(sourceLabel, nodes);
  if (!sourceNode) return null;
  const targetNode = v52ResolveNodeByLabel(targetLabel, nodes);
  let targetId = targetNode?.node_id || "";
  let objectLabel = targetNode?.base_name || targetLabel;
  if (!targetId && objectLabel) {
    let mention = mentions.find((item) => item.label === objectLabel);
    if (!mention) { mention = v52MentionEntity(objectLabel); mentions.push(mention); }
    targetId = mention.entity_id;
  }
  const relationLabel = v52Text(raw.relation_label || raw.label || raw.relation || raw.relation_type || "相关");
  const relationType = v52Text(raw.relation_type) || V52_RELATION_LOOKUP.get(relationLabel) || "related";
  const sourceLine = Number(raw.source_line || raw.line || 0) || 0;
  const evidence = v52Text(raw.evidence || raw.source_evidence).slice(0, 300);
  const timeline = v52Text(raw.timeline_scope || raw.timeline || "当前或未明确");
  const worldline = v52Text(raw.worldline_id || raw.worldline || "main_world");
  const origin = ["manual", "confirmed", "ai", "local", "guide", "legacy"].includes(v52Text(raw.origin)) ? v52Text(raw.origin) : "ai";
  const status = ["manual", "confirmed", "corrected", "auto", "disabled"].includes(v52Text(raw.status)) ? v52Text(raw.status) : (origin === "manual" ? "manual" : "auto");
  const idSeed = `${sourceNode.node_id}|${relationType}|${targetId}|${sourceLine}|${evidence}`;
  return {
    relation_id: v52Text(raw.relation_id || raw.id) || v52SafeId("relation", idSeed),
    source_node_id: sourceNode.node_id,
    subject_base: sourceNode.base_name,
    target_node_id: targetId,
    object_base: targetNode?.base_name || "",
    object_label: objectLabel,
    relation_type: relationType,
    relation_label: relationLabel,
    direction: v52Text(raw.direction || "directed"),
    timeline_scope: timeline,
    worldline_id: worldline,
    start_line: Number(raw.start_line || sourceLine || 0) || 0,
    end_line: raw.end_line === null || raw.end_line === undefined ? null : (Number(raw.end_line) || null),
    source_line: sourceLine,
    evidence,
    confidence: Number(raw.confidence) || (origin === "manual" || origin === "confirmed" ? 1 : 0.72),
    origin,
    status,
    locked: Boolean(raw.locked || origin === "manual" || origin === "confirmed"),
    disabled: Boolean(raw.disabled || status === "disabled"),
    correction_reason: v52Text(raw.correction_reason),
  };
}

function v52NormalizeAliasBinding(raw = {}, nodes = []) {
  const alias = v52Text(raw.alias || raw.term || raw.address_term);
  const target = v52ResolveNodeByLabel(raw.target_node_id || raw.person || raw.base_name || raw.target, nodes);
  if (!alias || !target) return null;
  const sourceLine = Number(raw.source_line || raw.line || 0) || 0;
  const origin = ["manual", "confirmed", "ai", "local", "guide", "legacy"].includes(v52Text(raw.origin)) ? v52Text(raw.origin) : "ai";
  return {
    binding_id: v52Text(raw.binding_id || raw.id) || v52SafeId("alias", `${alias}|${target.node_id}|${sourceLine}`),
    alias,
    target_node_id: target.node_id,
    target_base_name: target.base_name,
    source_line: sourceLine,
    end_line: raw.end_line === null || raw.end_line === undefined ? null : (Number(raw.end_line) || null),
    evidence: v52Text(raw.evidence).slice(0, 300),
    confidence: Number(raw.confidence) || (origin === "manual" || origin === "confirmed" ? 1 : 0.75),
    origin,
    status: v52Text(raw.status) || (origin === "manual" ? "manual" : "auto"),
    locked: Boolean(raw.locked || origin === "manual" || origin === "confirmed"),
    disabled: Boolean(raw.disabled),
    scope: v52Text(raw.scope || "global"),
  };
}

function v52GuideAliasBindings(nodes = []) {
  const bindings = [];
  nodes.forEach((node) => {
    v52IdentityTokens(node).forEach((alias) => {
      if (alias === node.base_name) return;
      bindings.push(v52NormalizeAliasBinding({ alias, target_node_id: node.node_id, origin: "guide", status: "auto", confidence: 0.95 }, nodes));
    });
  });
  return bindings.filter(Boolean);
}

function v52GuideRelationEdges(nodes = []) {
  const protagonist = nodes.find((node) => node.base_name === "我" || node.identity_hints.some((hint) => /主角|女主|男主/.test(hint)));
  if (!protagonist) return [];
  const mentions = [];
  const edges = [];
  nodes.forEach((node) => {
    if (node.node_id === protagonist.node_id) return;
    const labels = v52IdentityTokens(node).filter((token) => V52_RELATION_LOOKUP.has(token));
    labels.forEach((label) => {
      const type = V52_RELATION_LOOKUP.get(label);
      if (!["spouse", "fiance", "lover", "mother", "father", "child", "sibling", "master", "disciple", "employment", "service", "ally", "enemy"].includes(type)) return;
      const edge = v52NormalizeRelationEdge({ source_node_id: protagonist.node_id, target_node_id: node.node_id, relation_type: type, relation_label: label, origin: "guide", confidence: 0.85 }, nodes, mentions);
      if (edge) edges.push(edge);
    });
  });
  return edges;
}

function v52LocalRelationGraph(novelText = "", nodes = [], aliasBindings = []) {
  const source = String(novelText || "");
  const lines = source.replace(/\r/g, "").split(/\n/);
  const mentions = [];
  const edges = [];
  const bindings = [];
  const addEdge = (edge) => { if (edge) edges.push(edge); };
  const aliasesForNode = (node) => v52Unique([node.base_name, ...v52IdentityTokens(node), ...aliasBindings.filter((binding) => binding.target_node_id === node.node_id && !binding.disabled).map((binding) => binding.alias)]).sort((a, b) => b.length - a.length);
  lines.forEach((line, lineIndex) => {
    const clean = v52Text(line);
    if (!clean) return;
    nodes.forEach((node) => {
      aliasesForNode(node).forEach((ownerToken) => {
        V52_RELATION_TOKENS.forEach((relationLabel) => {
          const relationPattern = new RegExp(`${escapeGuidanceRegExp(ownerToken)}(?:的)?${escapeGuidanceRegExp(relationLabel)}`);
          if (!relationPattern.test(clean)) return;
          const relationType = V52_RELATION_LOOKUP.get(relationLabel) || "related";
          const targetNode = nodes.find((candidate) => candidate.node_id !== node.node_id && v52IdentityTokens(candidate).includes(relationLabel));
          addEdge(v52NormalizeRelationEdge({
            source_node_id: node.node_id,
            target_node_id: targetNode?.node_id || "",
            object_label: targetNode?.base_name || relationLabel,
            relation_type: relationType,
            relation_label: relationLabel,
            source_line: lineIndex + 1,
            evidence: clean,
            timeline_scope: /曾经|当年|过去|小时候|前世|十年前|多年以前/.test(clean) ? "过去" : /后来|如今|现在|现任/.test(clean) ? "当前" : "当前或未明确",
            origin: "local",
            confidence: targetNode ? 0.88 : 0.68,
          }, nodes, mentions));
        });
      });
    });
    nodes.forEach((targetNode) => {
      aliasesForNode(targetNode).forEach((targetToken) => {
        nodes.forEach((ownerNode) => {
          if (ownerNode.node_id === targetNode.node_id) return;
          aliasesForNode(ownerNode).forEach((ownerToken) => {
            V52_RELATION_TOKENS.forEach((relationLabel) => {
              const reversePattern = new RegExp(`${escapeGuidanceRegExp(targetToken)}(?:是|就是|乃是|作为)${escapeGuidanceRegExp(ownerToken)}(?:的)?${escapeGuidanceRegExp(relationLabel)}`);
              if (!reversePattern.test(clean)) return;
              addEdge(v52NormalizeRelationEdge({ source_node_id: ownerNode.node_id, target_node_id: targetNode.node_id, relation_label: relationLabel, relation_type: V52_RELATION_LOOKUP.get(relationLabel), source_line: lineIndex + 1, evidence: clean, origin: "local", confidence: 0.95 }, nodes, mentions));
            });
          });
        });
      });
    });
    const quotedAlias = clean.match(/(?:叫|称|称作|人称|外号是|代号是)[“"'‘]([^”"'’]{1,20})[”"'’]/);
    if (quotedAlias) {
      const preceding = nodes.filter((node) => clean.includes(node.base_name));
      if (preceding.length === 1) bindings.push(v52NormalizeAliasBinding({ alias: quotedAlias[1], target_node_id: preceding[0].node_id, source_line: lineIndex + 1, evidence: clean, origin: "local", confidence: 0.9 }, nodes));
    }
  });
  return { edges: edges.filter(Boolean), alias_bindings: bindings.filter(Boolean), mention_entities: mentions };
}

function v52MergeGraphItems(items = [], idKey = "relation_id") {
  const byId = new Map();
  items.filter(Boolean).forEach((item) => {
    const id = item[idKey];
    if (!id) return;
    const existing = byId.get(id);
    if (!existing) { byId.set(id, item); return; }
    const rank = (value) => value.origin === "manual" ? 6 : value.status === "confirmed" ? 5 : value.origin === "guide" ? 4 : value.origin === "ai" ? 3 : value.origin === "local" ? 2 : 1;
    if (rank(item) >= rank(existing)) byId.set(id, { ...existing, ...item });
  });
  return [...byId.values()];
}

function v52BuildRelationshipGraph(novelText = "", cards = [], data = {}) {
  v52EnsureRelationshipState();
  const nodes = v52PersonNodes(cards);
  const prior = state.relationshipGraph || v52EmptyRelationshipGraph();
  const mentionEntities = v52List(prior.mention_entities).map((raw) => ({
    ...v52MentionEntity(raw.label || raw.name || raw.entity_id, raw.entity_type || "person_mention"),
    ...raw,
  }));
  const priorManualEdges = v52List(prior.edges)
    .filter((edge) => edge.origin === "manual" || edge.status === "confirmed" || edge.locked)
    .map((edge) => v52NormalizeRelationEdge(edge, nodes, mentionEntities))
    .filter(Boolean);
  const priorManualAliases = v52List(prior.alias_bindings)
    .filter((binding) => binding.origin === "manual" || binding.status === "confirmed" || binding.locked)
    .map((binding) => v52NormalizeAliasBinding(binding, nodes))
    .filter(Boolean);
  const guideAliases = v52GuideAliasBindings(nodes);
  const incomingAliases = [
    ...v52List(data.alias_bindings),
    ...v52List(data.relationship_graph?.alias_bindings),
  ].map((item) => v52NormalizeAliasBinding(item, nodes)).filter(Boolean);
  const provisionalAliases = v52MergeGraphItems([...guideAliases, ...incomingAliases, ...priorManualAliases], "binding_id");
  const local = v52LocalRelationGraph(novelText, nodes, provisionalAliases);
  local.mention_entities.forEach((item) => { if (!mentionEntities.some((existing) => existing.entity_id === item.entity_id)) mentionEntities.push(item); });
  v52List(data.mention_entities || data.relationship_graph?.mention_entities).forEach((raw) => {
    const item = v52MentionEntity(raw.label || raw.name || raw.entity_id, raw.entity_type || "person_mention");
    if (!mentionEntities.some((existing) => existing.entity_id === item.entity_id)) mentionEntities.push({ ...item, ...raw });
  });
  const incomingEdges = [
    ...v52List(data.relationships),
    ...v52List(data.relationship_graph?.edges),
  ].map((item) => v52NormalizeRelationEdge({ ...item, origin: item.origin || "ai" }, nodes, mentionEntities)).filter(Boolean);
  const guideEdges = v52GuideRelationEdges(nodes);
  const localEdges = local.edges;
  const suppressedEdges = new Set(state.relationshipOverrides.suppressed_edge_ids || []);
  const suppressedAliases = new Set(state.relationshipOverrides.suppressed_alias_ids || []);
  let edges = v52MergeGraphItems([...guideEdges, ...incomingEdges, ...localEdges, ...priorManualEdges], "relation_id")
    .filter((edge) => !edge.disabled && !suppressedEdges.has(edge.relation_id));
  let aliases = v52MergeGraphItems([...provisionalAliases, ...local.alias_bindings], "binding_id")
    .filter((binding) => !binding.disabled && !suppressedAliases.has(binding.binding_id));
  // 自动纠错：相同别称在同一作用域只能指向一个人，保留用户修正/确认或更高可信结果。
  const aliasByTerm = new Map();
  aliases.forEach((binding) => {
    const key = `${binding.alias}|${binding.scope || "global"}`;
    const existing = aliasByTerm.get(key);
    const rank = (item) => item.origin === "manual" ? 6 : item.status === "confirmed" ? 5 : item.origin === "guide" ? 4 : item.confidence || 0;
    if (!existing || rank(binding) > rank(existing)) aliasByTerm.set(key, binding);
  });
  aliases = [...aliasByTerm.values()];
  edges = edges.filter((edge) => edge.source_node_id && edge.target_node_id && edge.source_node_id !== edge.target_node_id);
  const pending = [];
  const ambiguousAliases = new Map();
  [...guideAliases, ...incomingAliases, ...local.alias_bindings].forEach((binding) => {
    if (!binding) return;
    if (!ambiguousAliases.has(binding.alias)) ambiguousAliases.set(binding.alias, new Set());
    ambiguousAliases.get(binding.alias).add(binding.target_node_id);
  });
  ambiguousAliases.forEach((targets, alias) => {
    if (targets.size > 1 && !aliases.some((item) => item.alias === alias && (item.origin === "manual" || item.status === "confirmed"))) {
      pending.push({ pending_id: v52SafeId("pending", alias), type: "ambiguous_alias", text: `称呼“${alias}”存在多个候选人物`, alias, candidate_node_ids: [...targets] });
    }
  });
  return {
    version: RELATIONSHIP_GRAPH_VERSION_V52,
    nodes,
    mention_entities: v52MergeGraphItems(mentionEntities.map((item) => ({ ...item, relation_id: item.entity_id })), "relation_id").map(({ relation_id, ...item }) => item),
    edges,
    alias_bindings: aliases,
    pending,
    source_hash: buildCharacterSourceFingerprint(novelText),
    updated_at: new Date().toISOString(),
  };
}

v49BuildRelationshipGraph = function v52RelationshipGraphCompatibility(novelText = "", cards = []) {
  return v52BuildRelationshipGraph(novelText, cards, {}).edges.map((edge) => ({ ...edge, subject_base: edge.subject_base, object_base: edge.object_base, object_label: edge.object_label }));
};

v49FinalizeIdentityGraph = function v52DoNotMutateCharactersFromRelationshipGraph(cards = [], novelText = "", incomingRelations = []) {
  const normalizedCards = (cards || []).map(normalizeCharacterRecord);
  const graph = v52BuildRelationshipGraph(novelText, normalizedCards, { relationships: incomingRelations });
  return { characters: normalizedCards, relationships: graph.edges, relationship_graph: graph };
};

function v52NodeById(graph, nodeId) { return v52List(graph?.nodes).find((node) => node.node_id === nodeId) || null; }
function v52NodeTokens(graph, node) {
  const aliases = v52List(graph?.alias_bindings).filter((binding) => !binding.disabled && binding.target_node_id === node.node_id).map((binding) => binding.alias);
  return v52Unique([node.base_name, ...v52IdentityTokens(node), ...aliases]).sort((a, b) => b.length - a.length);
}

const V52_VISIBLE_ACTIONS = /站|坐|走|跑|进|出|推|拉|拿|放|抬|低|转|回|看|盯|望|听|说|问|喊|叫|笑|哭|皱|点头|摇头|伸手|抬手|跪|躺|靠|抱|吻|打|递|接|打开|关上|穿|戴|脱下|扶|拦|挡|追|停|弯腰|起身|冲|摔|泼|端|举|握|掏|按|敲|开口|回答|质问|呵斥/;
const V52_MENTION_ONLY = /提到|提起|说起|想起|想到|听说|得知|传闻|据说|告诉我|消息里|资料里|名单上|遗言|过去经历|梦到但未切画面/;
const V52_OFFSCREEN = /电话里|电话那头|耳机里|广播里|门外传来|画外音|语音里|录音里/;
const V52_PHOTO_SCREEN = /照片里|照片中的|监控里|监控中的|屏幕里|视频里|视频中的|手机画面里/;
const V52_MEMORY = /回忆中|记忆里|画面切回|闪回|梦境中|梦里|前世画面/;
const V52_POSSESSIVE_RELATIONS = [
  ["mother", /(?:母亲|妈妈|妈|娘|母后|婆婆|岳母)/],
  ["father", /(?:父亲|爸爸|爸|爹|父皇|公公|岳父)/],
  ["spouse", /(?:丈夫|妻子|老公|老婆|夫君|夫人|道侣)/],
  ["fiance", /(?:未婚夫|未婚妻)/],
  ["lover", /(?:男友|女友|恋人|爱人|前任)/],
  ["child", /(?:儿子|女儿|孩子|皇子|公主)/],
  ["sibling", /(?:哥哥|姐姐|弟弟|妹妹|兄长|长姐)/],
  ["master", /(?:师父|师尊|师傅|老师|导师)/],
  ["disciple", /(?:徒弟|弟子|学生)/],
];

function v52RelationTargetNodes(graph = {}, ownerNode = null, relationType = "") {
  if (!ownerNode || !relationType) return [];
  return v52List(graph.edges)
    .filter((edge) => !edge.disabled && edge.source_node_id === ownerNode.node_id && edge.relation_type === relationType)
    .map((edge) => v52NodeById(graph, edge.target_node_id))
    .filter(Boolean);
}

function v52IsSpeakerToken(clause = "", token = "") {
  const source = String(clause || "");
  const value = String(token || "");
  if (!value) return false;
  const tokenIndex = source.indexOf(value);
  if (tokenIndex >= 0) {
    const before = source.slice(Math.max(0, tokenIndex - 6), tokenIndex);
    const after = source.slice(tokenIndex + value.length, tokenIndex + value.length + 10);
    if (/(?:对|向|冲着|告诉|询问|质问|提醒)$/.test(before) && /^(?:说|问|喊|叫|道|回答|开口|表示)/.test(after)) return false;
  }
  const escaped = escapeGuidanceRegExp(value);
  return new RegExp(`${escaped}[^。！？]{0,12}(?:说|问|喊|叫|道|回答|开口|质问|呵斥|告诉)|[”’"'](?:，|,)?${escaped}[^。！？]{0,6}(?:说|问|喊|道|回答)`).test(source);
}

function v52DialogueRoles(clause = "", graph = {}) {
  const nodes = v52List(graph.nodes);
  let speaker = null;
  let addressee = null;
  for (const candidate of nodes) {
    const tokens = v52NodeTokens(graph, candidate);
    const token = tokens.find((item) => v52IsSpeakerToken(clause, item));
    if (token) { speaker = candidate; break; }
  }
  if (speaker) {
    for (const candidate of nodes) {
      if (candidate.node_id === speaker.node_id) continue;
      const speakerTokens = v52NodeTokens(graph, speaker);
      const targetTokens = v52NodeTokens(graph, candidate);
      const matched = speakerTokens.some((speakerToken) => targetTokens.some((targetToken) => {
        const direct = new RegExp(`${escapeGuidanceRegExp(speakerToken)}[^。！？]{0,12}(?:对|向|冲着|告诉|问|质问|提醒)${escapeGuidanceRegExp(targetToken)}[^。！？]{0,12}(?:说|问|喊|道|开口|表示)?`);
        const postposed = new RegExp(`${escapeGuidanceRegExp(speakerToken)}[^。！？]{0,12}(?:说|问|喊|道)[^。！？]{0,18}(?:给|对|向)${escapeGuidanceRegExp(targetToken)}`);
        return direct.test(clause) || postposed.test(clause);
      }));
      if (matched) { addressee = candidate; break; }
    }
  }
  return { speaker, addressee };
}

function v52TokenRegex(token = "") {
  if (token === "我") return /我(?!的?(?:妈|娘|爹|爸|父|母|丈夫|妻子|未婚夫|未婚妻|男友|女友|孩子|女儿|儿子|哥哥|姐姐|弟弟|妹妹))/;
  return new RegExp(escapeGuidanceRegExp(token));
}

function v52ResolveSceneParticipants(sceneText = "", graph = state.relationshipGraph, previousStageByNode = new Map()) {
  const source = v52Text(sceneText);
  const result = [];
  const add = (node, participation, evidence = "", confidence = 0.8) => {
    if (!node) return;
    const existing = result.find((item) => item.node_id === node.node_id);
    const rank = { mentioned_only: 1, addressee: 2, offscreen_voice: 3, photo_visible: 4, screen_visible: 4, memory_visible: 5, dream_visible: 5, speaker: 6, visible: 7 };
    if (!existing) result.push({ node_id: node.node_id, base_name: node.base_name, participation, evidence, confidence });
    else if ((rank[participation] || 0) > (rank[existing.participation] || 0)) Object.assign(existing, { participation, evidence, confidence });
  };
  const clauses = source.split(/(?<=[。！？!?；;])|\n+/).map(v52Text).filter(Boolean);
  let lastExplicitNode = null;
  clauses.forEach((clause) => {
    const matched = [];
    const dialogueRoles = v52DialogueRoles(clause, graph || {});
    v52List(graph?.nodes).forEach((node) => {
      const token = v52NodeTokens(graph, node).find((candidate) => v52TokenRegex(candidate).test(clause));
      if (!token) return;
      const tokenIndex = clause.search(v52TokenRegex(token));
      const nearby = clause.slice(Math.max(0, tokenIndex - 14), Math.min(clause.length, tokenIndex + token.length + 24));
      const isOffscreen = V52_OFFSCREEN.test(nearby) || V52_OFFSCREEN.test(clause);
      const isPhoto = V52_PHOTO_SCREEN.test(nearby) || V52_PHOTO_SCREEN.test(clause);
      const isMemory = V52_MEMORY.test(nearby) || V52_MEMORY.test(clause);
      const mentionMatch = nearby.match(V52_MENTION_ONLY);
      const localTokenIndex = nearby.search(v52TokenRegex(token));
      const mentionIndex = mentionMatch?.index ?? -1;
      const actorOfMention = mentionIndex >= 0 && localTokenIndex >= 0 && localTokenIndex + token.length <= mentionIndex;
      const isMention = (mentionIndex >= 0 || V52_MENTION_ONLY.test(clause)) && !actorOfMention;
      const isSpeaker = v52IsSpeakerToken(clause, token);
      const isVisibleAction = V52_VISIBLE_ACTIONS.test(nearby) || isSpeaker || actorOfMention;
      let participation = "mentioned_only";
      if (isOffscreen && isSpeaker) participation = "offscreen_voice";
      else if (isPhoto) participation = /监控|屏幕|视频|手机/.test(nearby) ? "screen_visible" : "photo_visible";
      else if (isMemory) participation = /梦/.test(nearby) ? "dream_visible" : "memory_visible";
      else if (isVisibleAction && !isMention) participation = isSpeaker ? "speaker" : "visible";
      else if (isSpeaker) participation = "speaker";
      add(node, participation, clause, isVisibleAction ? 0.92 : 0.72);
      matched.push(node);
    });
    if (dialogueRoles.speaker) add(dialogueRoles.speaker, "speaker", clause, 0.96);
    if (dialogueRoles.addressee) add(dialogueRoles.addressee, "addressee", clause, 0.9);

    // 结合说话人与受话人解析“你妈/我妈/某人的母亲”等所属关系；关系对象只标记被提及，不会被自动勾选出镜。
    V52_POSSESSIVE_RELATIONS.forEach(([relationType, relationRegex]) => {
      const relationSource = relationRegex.source;
      const owners = [];
      if (new RegExp(`你(?:的)?${relationSource}`).test(clause) && dialogueRoles.addressee) owners.push(dialogueRoles.addressee);
      const narrator = v52List(graph?.nodes).find((node) => node.base_name === "我");
      if (new RegExp(`我(?:的)?${relationSource}`).test(clause) && narrator) owners.push(narrator);
      v52List(graph?.nodes).forEach((ownerNode) => {
        const ownerMentioned = v52NodeTokens(graph, ownerNode).some((token) => new RegExp(`${escapeGuidanceRegExp(token)}(?:的)?${relationSource}`).test(clause));
        if (ownerMentioned) owners.push(ownerNode);
      });
      v52Unique(owners.map((owner) => owner.node_id)).forEach((ownerId) => {
        const owner = v52NodeById(graph, ownerId);
        v52RelationTargetNodes(graph, owner, relationType).forEach((target) => add(target, "mentioned_only", clause, 0.96));
      });
    });

    if (matched.length === 1) lastExplicitNode = matched[0];
    if (dialogueRoles.speaker) lastExplicitNode = dialogueRoles.speaker;
    if (lastExplicitNode && /^(?:他|她|其|这个男人|这个女人)[^。！？]{0,18}/.test(clause) && V52_VISIBLE_ACTIONS.test(clause)) {
      add(lastExplicitNode, /说|问|喊|道|开口/.test(clause) ? "speaker" : "visible", clause, 0.74);
    }
  });
  // 低置信度不强行勾选：只返回明确可视或明确说话并在场的人物。
  const selected = result.filter((item) => ["visible", "speaker", "memory_visible", "dream_visible", "photo_visible", "screen_visible"].includes(item.participation));
  const cards = (state.characters || []).map(normalizeCharacterRecord);
  const characterNames = [];
  selected.forEach((item) => {
    const nodeCards = cards.filter((card) => card.base_person_id === item.node_id);
    const selectedCard = v52SelectStageCard(nodeCards, source, previousStageByNode.get(item.node_id) || "");
    if (selectedCard) {
      characterNames.push(selectedCard.name);
      if (selectedCard.stage_key) previousStageByNode.set(item.node_id, selectedCard.stage_key);
    }
  });
  return { mentions: result, selected_names: v52Unique(characterNames) };
}

function v52SelectStageCard(cards = [], sourceLine = "", previousStageKey = "") {
  if (!cards.length) return null;
  if (cards.length === 1) return cards[0];
  const explicit = v52StageMeta(sourceLine);
  if (explicit.exact_age !== null) {
    const byAge = cards.find((card) => Number(card.exact_age) === Number(explicit.exact_age));
    if (byAge) return byAge;
  }
  if (explicit.key) {
    const exact = cards.find((card) => card.stage_key === explicit.key);
    if (exact) return exact;
  }
  if (/小时候|童年|小学|孩提/.test(sourceLine)) {
    const child = cards.find((card) => ["infant", "young_child", "child"].includes(card.stage_key));
    if (child) return child;
  }
  if (/少女时|少年时|初中|高中|青春期/.test(sourceLine)) {
    const teen = cards.find((card) => card.stage_key === "teen");
    if (teen) return teen;
  }
  if (/长大后|多年后|如今|现在|成年后|工作|婚礼|结婚|丈夫|妻子/.test(sourceLine)) {
    const adult = cards.find((card) => card.stage_key === "adult");
    if (adult) return adult;
  }
  if (previousStageKey) {
    const previous = cards.find((card) => card.stage_key === previousStageKey);
    if (previous) return previous;
  }
  return cards.find((card) => card.stage_key === "adult") || cards[0];
}

function v52RefreshSceneCharacterBindings(novelText = readNovelTextRaw()) {
  v52EnsureRelationshipState();
  const previousStageByNode = new Map();
  state.scenes = (state.scenes || []).map((scene) => {
    const mode = normalizeSceneCharactersMode(scene.characters_mode);
    if (mode === "manual") {
      const valid = new Set((state.characters || []).map((card) => normalizeCharacterRecord(card).name));
      return { ...scene, characters: v52Unique(scene.characters || []).filter((name) => valid.has(name)), characters_mode: "manual", characters_authoritative: true };
    }
    const sourceLine = v52Text(scene.source_text || scene.text);
    const resolution = v52ResolveSceneParticipants(sourceLine, state.relationshipGraph, previousStageByNode);
    const key = scene.id || v52SafeId("scene", sourceLine);
    state.sceneCharacterResolutions[key] = { source_text: sourceLine, mentions: resolution.mentions, selected_names: resolution.selected_names };
    return { ...scene, characters: resolution.selected_names, characters_mode: "auto", characters_authoritative: false, character_inference_note: "已按独立关系图、指代语义、出镜状态和强制阶段卡匹配；仅被提及者不勾选" };
  });
  if (typeof syncAllSceneCharactersToOutlineShots === "function") syncAllSceneCharactersToOutlineShots();
  return state.scenes;
}

v42RefreshSceneCharacterBindings = v52RefreshSceneCharacterBindings;

const __v51BuildLineCharacterPlansForV52 = buildLineCharacterPlansV36;
buildLineCharacterPlansV36 = function v52BuildLineCharacterPlans(novelText = "") {
  const basePlans = __v51BuildLineCharacterPlansForV52(novelText);
  const sourceScenes = splitOutlineSourceScenes(novelText);
  const previousStageByNode = new Map();
  const registry = (state.characters || []).map(normalizeCharacterRecord);
  return basePlans.map((raw, index) => {
    const sourceText = v52Text(sourceScenes[index]?.source_text || raw.source_text);
    const manual = raw.characters_mode === "manual" || raw.whitelist_source === "current_scene_selection";
    const allowed = manual ? v52Unique(raw.allowed || []).filter((name) => registry.some((card) => card.name === name)) : v52ResolveSceneParticipants(sourceText, state.relationshipGraph, previousStageByNode).selected_names;
    const bindings = allowed.map((name) => {
      const card = registry.find((item) => item.name === name);
      return card ? { name: card.name, base_name: card.base_name, stage: card.stage_label, scene_identity_label: card.stage_label, gender: card.gender, is_protagonist: /主角|女主|男主/.test(card.identity_hint || card.role) || card.base_name === "我" } : null;
    }).filter(Boolean);
    return {
      ...raw,
      source_text: sourceText,
      allowed,
      stage_bindings: bindings,
      excluded_formal_characters: registry.filter((card) => !allowed.includes(card.name)).map((card) => card.name),
      visual_center: bindings.find((item) => item.is_protagonist)?.name || allowed[0] || "",
      protagonist_visible: bindings.some((item) => item.is_protagonist),
      whitelist_source: manual ? "current_scene_selection" : "relationship_graph_v52",
    };
  });
};

reconcileCharacterIdentityGraph = function v52ReconcileBySlotOnly(_novelText = "") {
  const bySlot = new Map();
  (state.characters || []).map(normalizeCharacterRecord).forEach((card) => {
    const key = card.slot_id || card.name;
    if (key && !bySlot.has(key)) bySlot.set(key, card);
  });
  state.characters = [...bySlot.values()];
  const validNames = new Set(state.characters.map((card) => card.name));
  state.scenes = (state.scenes || []).map((scene) => ({ ...scene, characters: v52Unique(scene.characters || []).filter((name) => validNames.has(name)) }));
  return new Map();
};

const V52_UNIVERSAL_RELATIONSHIP_GRAPH_SKILL = `【V52通用小说人物关系图与分镜选角Skill｜关系图独立，只读人物卡】
1. 强制人物卡槽位是人物卡唯一权威。关系图只能引用这些基础人物节点；名单外角色只能建立mention_only实体，不得进入characters，不得新增、删除、合并、改名、改阶段或改外形。
2. 逐句识别完整姓名、真实别名、身份称谓、亲属称谓、职业称谓、代词、群体称谓、说话人、受话人、动作执行者、动作承受者和所属链。称谓必须绑定所属人，例如“丈夫助理的母亲”不得误认成女主母亲。
3. 第一人称必须按叙述作用域区分主叙事、信件、日记、转述、回忆、梦境、小说内小说和多主角章节；第二人称必须结合说话人与受话人解析“你妈/你爸/你丈夫”；第三人称不能只按最近人物匹配。
4. 关系边必须有方向、证据行、原文证据、置信度、时间范围和世界线。过去/现在、前任/现任、身份揭晓前后、前世/今生、平行世界、时间循环不得互相污染。推测、传闻、伪装和事实必须区分。
5. 通用覆盖现代家庭豪门、校园职场、古代宫斗宅斗、仙侠玄幻修真、悬疑刑侦、科幻末世系统文、群像多视角。支持父母/继亲/养亲、夫妻/前任、主仆、师徒同门、上下级、盟友敌对、宿主系统、器灵灵宠、本体分身、身体灵魂、克隆体、假名代号、双胞胎和隐藏身份。
6. 分镜参与状态必须区分visible、speaker、addressee、offscreen_voice、mentioned_only、photo_visible、screen_visible、memory_visible、dream_visible、system_entity、group_visible和unknown。仅被提到、传闻、资料名、联系人名、历史关系对象默认不得勾选本镜人物。
7. 电话、广播和录音中的人物标记offscreen_voice；照片、监控、视频和手机屏幕中的人物按可见媒介标记；回忆、梦境和前世画面只在画面真正切入时标记可见。
8. 不确定称呼或代词时返回候选与较低置信度，不得强行绑定。用户手动修正、确认、禁用关系的优先级最高，后续自动分析不得覆盖。
9. 关系图先解析基础人物身份，阶段选择器再从现有强制人物卡槽位中选择唯一正确阶段；关系图不得创建阶段。同一镜头除非原文明示时空同框、照片对照或平行世界同框，不得同时选择同一人物多个阶段。`;

function v52CompactAnalysisOverride(novelText = "") {
  const slots = v52SlotsForCurrentSource(novelText);
  const slotRows = slots.map((slot) => `${slot.slot_id}|${slot.display_name}|基础名=${slot.base_name}|身份=${slot.identity_hint || "无"}|阶段=${slot.stage_label}`).join("\n") || "（名单为空：characters必须返回空数组）";
  return [
    "【V52最终覆盖规则｜人物卡与关系图，只以本段为准】",
    "人物卡集合只能来自下面的强制槽位；不得自动识别人、补主角、补配角、增加或删除人物，也不得增加年龄阶段。每个slot_id必须独立返回一张卡，同一基础人物不同阶段绝对不能合并。未列槽位时characters=[]。",
    "每张卡只写当前槽位指定阶段的外形，禁止写少女到成年、年轻时到后来等跨阶段过程。AI不得改slot_id、姓名、身份或阶段。外形缺字段也直接返回，不要二次补全。",
    "同时返回relationships与alias_bindings供独立关系图使用。关系图可理解名单外人物为mention_only，但不得把名单外人物放进characters，不得修改人物卡。关系边要有主体、关系类型、对象、原文行、证据、时间线/世界线和可信度。称呼、代词、对话说话人、电话/照片/回忆与仅被提及状态要结合上下文判断；不确定时不要强绑。",
    "严格返回一个JSON对象：{genre,trail​​er_style,story_era,characters:[{slot_id,name,gender,role,stage_label,appearance,appearance_fields}],relationships:[{subject_base,relation_type,relation_label,object_base,object_label,source_line,evidence,timeline_scope,worldline_id,confidence}],alias_bindings:[{alias,target,source_line,evidence,confidence}],mention_entities:[{label,entity_type}]}",
    "强制人物卡槽位：",
    slotRows,
  ].join("\n").replace("trail​​er", "trailer");
}

const V52_ANALYSIS_SETTINGS_NOTICE = "v52人物分析只使用强制人物卡槽位：名单每一项固定一张卡，同名不同阶段不得合并；名单外人物和额外阶段不得进入人物卡。关系图独立服务称呼、指代、对白与本镜人物匹配，不能修改人物卡。人物外形直接返回，不做完整度校验或二次补全。";
