function v52TrimAnalysisPayload(payload = "", maxLength = 42000) {
  const source = String(payload || "");
  if (source.length <= maxLength) return source;
  const marker = "\n\n【长原文保护：仅压缩中间原文，强制槽位协议与结尾协议完整保留】\n\n";
  const available = Math.max(0, maxLength - marker.length);
  const headLength = Math.floor(available * 0.62);
  const tailLength = Math.max(0, available - headLength);
  return `${source.slice(0, headLength)}${marker}${source.slice(-tailLength)}`;
}

