    let eraHint="";
    try{ eraHint=["analysis","single_character","all_characters"].includes(stepKey) ? storyEraHint(source) : ""; }catch(_e){}
    const extra=[block,eraHint].filter(Boolean).join("\n\n");
    const combined=extra ? `${source}\n\n${extra}` : source;
    console.info("[AI_INSTRUCTION_TRACE]",{step:stepKey,input_chars:source.length,total_payload_chars:combined.length,truncated:false,transport:"novel_text_append_full"});
    return combined;
