  resetAiInstructionSettings = function v23ResetAiInstructionSettings(){ state.aiInstructions=v23DefaultSet(); writeAiInstructionForm(); v23PersistGlobal(); try{scheduleDraftSave?.();}catch(_e){} };

  let v23CurrentKey="";
  function v23Meta(key){ return V23_META.find((item)=>item.key===key) || V23_META[0]; }
