    const meta=v23Meta(key); const ins=v23Normalize(state.aiInstructions||v23LoadGlobal());
    const title=v23ById("instructionCenterTitle"),group=v23ById("instructionCenterGroup"),desc=v23ById("instructionCenterDescription"),editor=v23ById("instructionCenterEditor"),lock=v23ById("instructionCenterProtocolLock");
    if(title)title.textContent=meta.title;if(group)group.textContent=meta.group;if(desc)desc.textContent=meta.desc;if(editor){editor.value=ins[key]||"";editor.dataset.loadedKey=key;}if(lock)lock.textContent=V23_PROTOCOL_LOCKS[key]||V23_PROTOCOL_LOCKS.global;
