      const btn=document.createElement("button");btn.type="button";btn.className="instruction-nav-button";btn.dataset.instructionKey=item.key;btn.textContent=item.title;btn.addEventListener("click",()=>v23LoadEditor(item.key));nav.appendChild(btn);
